window.__D("text/torat-shmuel/c043",{"p":[[2000470385,"<b>וביאור</b> הענין דהנה ארז\"ל מעשה אבות סימן לבנים<sup data-n=\"3333\">57</sup> וגבי יעקב כתי' ויקח מאבני המקום<sup data-n=\"3334\">58</sup> כתי' ל' רבים ואח\"כ וישם אותה מצבה<sup data-n=\"3335\">59</sup> ל' יחיד, והאבן הזאת<sup data-n=\"3336\">60</sup> ל' יחיד, וידוע דיעקב נטל י\"ב אבנים<sup data-n=\"3337\">61</sup> ועשאן אבן אחת, והענין דהנה נת\"ל דאבנים הם אותיות וכמ\"ש בס\"י שתי אבנים כו' ועוי\"ל מפני מה נק' אותיות בשם אבנים שהוא דומם<sup data-n=\"3338\">62</sup> ולכן בחי' שהוא מקור המהווה עולמות נק' אותיות שהוא בחי' אחרונה וה\"ה<sup data-n=\"3339\">63</sup> בחי' דומם, והנה מהאותיות אפשר שישתלשל כ\"כ עד שיהי' אותיות חרן שהוא היפך גרון<sup data-n=\"3340\">64</sup>, דהנה גרון הוא שדרך בו עובר הקול וממילא נשמעים האותיות אבל חרן הוא ניחר גרוני<sup data-n=\"3341\">65</sup> שאינו נשמע הקול וממילא אינם נשמעים האותיות ג\"כ, והנמשל הוא כששומע האותיות היינו שמרגיש חיות העולמות איך שהעולם חי וכמו אדם חי שניכר החיות בכל האברים שיש בהם תנועה אבל בצאת הנפש הגם שהאדם הוא בכל אבריו כמו שהי' קודם אך אין בו חיות ותנועה כלל, וכמו\"כ כשמרגיש שהעולם חי היינו שנמשך גילוי אלקות בעולמות עד שמרגיש החיות שאינו מסתיר כ\"כ, אבל חרן הוא ניחר גרוני שאינו נרגש חיות העולם הגם שיש חיות המחי' וכמ\"ש ואתה מחי' את כולם אפי' קליפות וסט\"א<sup data-n=\"3342\">66</sup> וא\"ת מחי' אלא מהווה<sup data-n=\"3343\">67</sup> אך אינו מרגיש החיות וע\"ד מ\"ש אותותינו לא ראינו<sup data-n=\"3344\">68</sup> הגם שיש אותות ומופתים וכמ\"ש לעושה נפלאות גדולות לבדו אין בעה\"נ<sup data-n=\"3345\">69</sup> מכיר בניסו אך מ\"מ לא ראינו שאינו מרגיש אותם וזהו חר\"ן. והנה יעקב בירר אותם וזהו ויקח מאבני המקום מאבני ולא כל אבני<sup data-n=\"3346\">70</sup> וכמשית\"ל שיש אותיות שאפשר לברר אותם ויש אותיות שא\"א לברר אותם, וישם אותה מצבה שהעלה אותם לחכ' שהוא ביטול שהוא אחד האמת שבו שורה אוא\"ס<sup data-n=\"3347\">71</sup>, ויצוק עלי' שמן ית\"ל אי\"ה, והאבן הזא\"ת תי' הזאת יש בו ג\"כ מכוון וית\"ל אי\"ה.",[["3333","57","<b>מעשה אבות סימן לבנים</b>: ראה תו\"א וישלח כו, רע\"א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' צא. רמב\"ן לך יב, ו. לקו\"ש תולדות כרך כה ע' 123. וש\"נ."],["3334","58","<b>ויקח מאבני המקום</b>: ויצא כח, יא."],["3335","59","<b>וישם אותה מצבה</b>: ויצא שם, יח."],["3336","60","<b>והאבן הזאת</b>: שם כח, כב."],["3337","61","<b>דיעקב נטל י\"ב אבנים</b>: פדר\"א פל\"ה. ב\"ר פס\"ח, יא. זהר ויצא קמז, ב. ויחי רלא, ב. פקודי רכט, ב."],["3338","62","<b>נק' אותיות בשם אבנים שהוא דומם</b>: ראה תו\"א ויצא כב, א. תו\"ח שם קסד, סע\"א ואילך."],["3339","63","<b>וה\"ה</b>: אולי כתוב: ה\"ה."],["3340","64","<b>חרן. . גרון</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' פג. וש\"נ. תו\"ח ויצא קסו, ב ובהערה 28."],["3341","65","<b>חרן הוא ניחר גרוני</b>: תהלים סט, ד. ראה תו\"א ויצא כא, ג. כב, ב. תו\"ח שם קסו, ב ובהערה 30."],["3342","66","<b>ואתה מחי'. . קליפות וסט\"א</b>: נחמי' ט, ו. ראה גם תו\"א וישב כז, א. סה\"מ תרל\"ח ע' חצר ובהערה 52."],["3343","67","<b>ואתה מחי'. . אלא מהוה</b>: ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."],["3344","68","<b>אותותינו לא ראינו</b>: תהלים עד, ט."],["3345","69","<b>לעושה נפלאות. . אין בעה\"נ</b>: ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה תכון תפלתי ובהערה 97."],["3346","70","<b>ויקח מאבני המקום ולא כל אבני</b>: ראה גם תו\"א ויצא כב, א."],["3347","71","<b>לחכ'. . אוא\"ס</b>: ראה תניא פל\"ה בהגהה."]]],[2000470386,"<b>וביאור</b> הענין דהנה על לע\"ל כתי' והסרותי<sup data-n=\"3348\">72</sup> לב האבן מבשרכם<sup data-n=\"3349\">73</sup> דהיצה\"ר<sup data-n=\"3350\">74</sup> נק' לב האבן כמו שהאבן אטום כמו\"כ לבו אטום שאינו מקבל דבר חכ' והוא טמטום הלב, וטמטום המוח<sup data-n=\"3351\">75</sup> הוא שאינו משיג כלל והוא גרוע מטמטום הלב לכן נק' אבן, והנה נת\"ל<sup data-n=\"3352\">76</sup> שהיצה\"ר בעצם אינו רע רק הוא כח המתאווה ואפשר שיהי' לו אהבה לאלקות ולפי פי' הב' ה\"ה טוב רק שהאדם מצייר בו ציור רע ומלביש אותו בלבושים רעים, והנה יש בזה כמה חלוקי מדרי' וכמו\"כ בהלבושים ג\"כ, וכמו למטה בחולי הגוף יש ג' מיני חולאים, א' חולה שאין בו סכנה היינו שיש לו מיחושים וסובל יסורים מזה אך אינו נוגע לו לחיי נפשו ממש שיכול לחיות בחולי זה מדה הקצובה שנקצב לו, אך כשיארע לו עוד חולאת ה\"ה חלוש ואין ביכולתו להתגבר עליו ואז נוגע לו לחיי נפשו ממש, אבל חולאת זה לבדו אינו נוגע לו לחיי נפשו ממש. ב' חולה שיש בו סכנה כמו חולי החום ששואב הלחלוחית ונשאר עצמות יבישות וכידוע שיש ב' מיני זיעות כשמזיע בזיעה דבוקה (בל\"א קלעפיקע) ה\"ז הוראה שיהי' בריא, אבל כשמזיע זיעה קרה ה\"ז שואב הלחלוחית ונשארים עצמות יבישות. ג' חולה בדקות היינו שאין לו שום חולאת רק שהוא חלוש שאם יש לו איזה מיחוש ה\"ז חולי שאין בו סכנה וזה אינו חולה כלל רק חלוש.\n<b>וכמו\"כ</b> יובן ג' מיני חולאים אלו בנפש, יש חולה בדקות חולה בגימ' מ\"ט<sup data-n=\"3353\">77</sup> וכשחסר לו שער הנו\"ן ה\"ז חולי, אך זה בדקות דגבי משה כתיב ותחסריהו מעט מאלקים<sup data-n=\"3354\">78</sup> שחסר לו מעט מאלקים דבינה<sup data-n=\"3355\">79</sup> (בפ\"א<sup data-n=\"3356\">80</sup> אלקים חיים ומלך עולם<sup data-n=\"3357\">81</sup> ) דמ\"ט שערים נמסרו למשה<sup data-n=\"3358\">82</sup> ושער הנו\"ן לא השיג עד הסתלקותו ואז<sup data-n=\"3359\">84</sup> השיג",[["3348","72","<b>לע\"ל כתי' והסרותי</b>: ראה גם שע\"ת סג, סע\"ב ובהערה 20. ש\"א פז, א. אוה\"ת שבהערה 74."],["3349","73","<b>והסרותי לב האבן מבשרכם</b>: יחזקאל לו, כו [בדילוג]."],["3350","74","<b>והסרותי לב האבן. . דהיצה\"ר</b>: ראה סוכה נב, א. זהר ואתחנן רסז, ב. אוה\"ת יחזקאל כרך א ס\"ע תיז ואילך."],["3351","75","<b>טמטום הלב וטמטום המוח</b>: ראה יומא לט, א. תו\"ח שמות ח\"א ב, ב. וש\"נ. סה\"מ תרכ\"ו ע' לא. המשך והחרים תרל\"א ע' ג."],["3352","76","<b>נת\"ל</b>: (בחלק המאמרים) בריש ההמשך פ\"ב."],["3353","77","<b>חולה בגימ' מ\"ט</b>: ראה טעמי המצות להאריז\"ל ר\"פ וירא. לקו\"ת להאריז\"ל ויחי מח, ב. מאו\"א מערכת חולה סל\"ה. לקו\"ת ברכה צז, ב. המשך וככה תרל\"ז ספס\"ג."],["3354","78","<b>ותחסריהו מעט מאלקים</b>: תהלים ח, ו. ראה מאמרי אדה\"א במדבר ח\"ב ע' תלד."],["3355","79","<b>מאלקים דבינה</b>: ראה זהר בהקדמה ב, א. תו\"ח בראשית ח, ב ובהערה 35."],["3356","80","<b>בפ\"א</b>: [ בפעם א? אמר כ\"ק אדמו\"ר מהר\"ש] ראה גם לקמן[ednref_205_א] כאן על יד הערה 138[ednref_206_ב]. הנחה ד\"ה ישקני מנשיקות פיהו על יד הערה 78 [ושם: בפ\"ג]."],["3357","81","<b>אלקים חיים ומלך עולם</b>: ברכת יוצר. ירמי' י, י."],["3358","82","<b>דמ\"ט שערים נמסרו למשה</b>: ראה ר\"ה כא, ב."],["3359","84","<b>ואז</b>: אינו ברור בגוכתי\"ק.\n\n[edn_205_א] לעיל הנחה ד\"ה זאת חנוכת המזבח על יד הערות 14 30. ד\"ה ויהי הענן והחשך על יד הערה 46.\n\n[edn_206_ב] לקמן ע' שכב. ע' שלב-שלג (ג\"פ). ע' שמוז-שמח (ג\"פ). ע' שנו. ע' שסד-שסח (ז\"פ). ע' שעד-שעה (ג\"פ). ע' שפז. ע' שצ-שצד (ד\"פ). לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך ובהערה 74."]]],[2000470387,"שער הנו\"ן<sup data-n=\"3360\">83</sup> וזהו שארז\"ל לעליונים נדמה להם למטה<sup data-n=\"3361\">85</sup> ולתחתונים נדמה להם למעלה לעליונים ר\"ל מהחכ' ולמעלה נדמה להם למטה דשער הנו\"ן למטה מחכ' ולתחתונים מהבינה ולמטה נדמה להם למעלה דשער למעלה<sup data-n=\"3362\">*86</sup> מהם, שהוא השגה ואינו השגה (דשער הנו\"ן הוא המחבר חו\"ב<sup data-n=\"3363\">86</sup>, ובאמת שרשו למעלה גם מחכ' לכן יש בכוחו לחבר חו\"ב) הנה באמת ה\"ז חולי שאינו שלימות העבודה, אך הוא בדקות מאד דחולי שגם משה הי' חולה בזה ה\"ז בדקות מאד. ב', חולה שאין בו סכנה, הנה חולה זה הוא חולה באמת רק שאין בו סכנה והוא מי שהוא משוקע בתאות היתר הגם שהוא היתר היפך האיסר, דאיסר ר\"ל שאסור וקשור בידי החיצונים והיתר ר\"ל שאינו אסור וקשור בידי החיצונים<sup data-n=\"3364\">87</sup> ואפשר לכוון לשם שמים אבל כשעושה אותה למלאות תאוות נפשו כי ירעב<sup data-n=\"3365\">88</sup> ה\"ז חולי, ובאמת הנה ארז\"ל אבר קטן יש באדם<sup data-n=\"3366\">89</sup> משביעו רעב שאין שיעור לתאוותו ואין שייך לומר כשממלא תאוותו אינו רוצה עוד אלא אף שמילא תאוותו מ\"מ הוא רוצה עוד וכמארז\"ל אין אדם מת וחצי תאוותו בידו<sup data-n=\"3367\">90</sup>, וכמו מי שהוא זולל וסובא אין שייך לומר כשכבר אכל אינו רוצה עוד אלא יאכל עוד כמקדם, וכמארז\"ל רווחא לבסומי שכיחא<sup data-n=\"3368\">91</sup> ונעשה עוד ריווח, והנה ע\"י יורד<sup data-n=\"3369\">92</sup> עשר מעלות אחורנית<sup data-n=\"3370\">93</sup> דהנה ארז\"ל כל העולם כולו לא נברא אלא לצוות לזה<sup data-n=\"3371\">94</sup>, צוות הוא ל' צוותא וחיבור<sup data-n=\"3372\">95</sup> דצומח חי ע\"י שהאדם אוכל אותם מתחברים עם האדם וה\"ז עלי' להם, אך כשהאדם מקבל עונג מהצומח ה\"ה מקבל ממנו ונמצא ה\"ה שפל מהם וה\"ז ירידה גדולה, ובאמת מי שהוא משוקע בתאוות עוה\"ז שדי תיכלא בכולו<sup data-n=\"3373\">96</sup>, שאפי' מי שיש לו חושים טובים ודקים אך מאחר שמשוקע בתאוות קען ער זיך ניט נעמען צוא קיין זאך, קיין זאך גייט<sup data-n=\"3374\">97</sup> עם ניט איין שה\"ה רוצה למלאות תאוות נפשו ואינו יכול לקשר עצמו לראות במו\"מ, והנה איש אשר אלה לו הוא חולה ממש, אך אין בו סכנה שבקל יכול לתקן זאת שיאכל לשם שמים בכדי שיוכל ללמוד ולהתפלל וכמ\"ש צדיק אוכל לשובע נפשו<sup data-n=\"3375\">98</sup> ובטן רשעים",[["3360","83","<b>הסתלקותו. . שער הנו\"ן</b>: ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן הערה 350."],["3361","85","<b>לעליונים נדמה להם למטה</b>: ראה סוטה יד, רע\"א. מאמרי אדה\"ז תקס\"ה ח\"א ע' קפד לקו\"ת במדבר יב, א ואילך (בשם המגיד). לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה והוא כחתן על יד הערה 25."],["3362","*86","<b>דשער למעלה</b>: כנצ\"ל: דשער הנו\"ן למעלה."],["3363","86","<b>דשער הנו\"ן הוא המחבר חו\"ב</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו ספ\"ט. המשך תער\"ב ח\"ב ע' א'ר. לקו\"ת במדבר יב, א ואילך."],["3364","87","<b>דאיסר. . והיתר. . החיצונים</b>: ראה תניא פ\"ז. אגה\"ק סכ\"ו (קמג, ב)."],["3365","88","<b>למלאות. . נפשו כי ירעב</b>: ע\"פ משלי ו, ל."],["3366","89","<b>אבר קטן יש באדם</b>: סנהדרין קז, א."],["3367","90","<b>וכמארז\"ל אין אדם. . בידו</b>: בסה\"מ תש\"ג ע' 191: ”מה שאמרו\" — וראה בהערה לשם."],["3368","91","<b>רווחא לבסומי שכיחא</b>: ראה ערובין פב, ב."],["3369","92","<b>ע\"י יורד</b>: אוצ\"ל: עי\"ז יורד ע\"י התאוות יורד."],["3370","93","<b>עשר מעלות אחורנית</b>: ע\"פ מלכים-ב כ, י. יא. ישעי' לח, ח."],["3371","94","<b>כל העולם כולו. . לזה</b>: ראה ברכות ו, ב."],["3372","95","<b>לצוות. . צוותא וחיבור</b>: ראה גם מאמרי אדה\"ז תקס\"ז ע' רצ. אוה\"ת מטות ע' א'רנח. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן על יד הערה 357. סה\"מ תרמ\"ד ס\"ע רעג ואילך."],["3373","96","<b>שדי תיכלא בכולו</b>: ראה חולין סד, ב."],["3374","97","<b>גייט</b>: אינו ברור בגוכתי\"ק ואולי כצ\"ל."],["3375","98","<b>צדיק אוכל לשובע נפשו</b>: משלי יג, כה. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ואמנם יש עוד בחי' חולה ובהערה 13."]]],[2000470388,"תחסר, בטן רשעים תחסר הוא כשאוכל למלאות תאוות נפשו וכמארז\"ל מליא כריסא זיני בישא<sup data-n=\"3376\">99</sup>, וצדיק אוכל לשובע נפשו היינו כשאוכל בכוונה לשם שמים. ג', חולה שיש בו סכנה, היינו כשמשוקע בתאוות איסור וכ\"ש כשנופל ח\"ו באחת מהנה וכמ\"ש בעשותו אחת מכל מצות ה' אשר לא תעשינה ואשם<sup data-n=\"3377\">100</sup> שעי\"ז מגשם<sup data-n=\"3378\">101</sup> נפשו והנה עי\"ז<sup data-n=\"3379\">102</sup> כורת נפשו מאוא\"ס חיי החיים<sup data-n=\"3380\">103</sup> וזה יש בו סכנה דמאחר שכורת נפשו מא\"ס חיי החיים ה\"ז סכנה ממש, ובזה יש חייבי כריתות וחייבי מיתות, והגם שאין לך דבר שעומד מפני התשובה<sup data-n=\"3381\">104</sup> דתשובה מועיל ע\"ז ג\"כ ומי שנפל ח\"ו בתאוות איסר אל יאמר נואש דתשובה מועיל ע\"ז ג\"כ, אך צריכים תשובה עמוקה וכמו תשובת ראב\"ד שגעה בבכי' עד שיצאה נשמתו<sup data-n=\"3382\">105</sup>, תמורת שכרת נפשו מאלקות ונשתקע בתאוות עוה\"ז נקשר אח\"כ באלקות, וכ\"כ עד שכרת נפשו לגמרי מתאוות עוה\"ז, ולא כל אדם זוכה לתשובה כזו, אך מי שזכה לתשובה זו גדלה מעלתו על מעלות הצדיקים וכמארז\"ל במקום שבעלי תשובה עומדים<sup data-n=\"3383\">106</sup> צדיקים גמורים אינם יכולים לעמוד דמאן דמשכי לי' בחילי יתיר<sup data-n=\"3384\">107</sup> ה\"ז מדרי' היותר גבוה ממדריגות הצדיקים.\n<b>והנה</b> כמו שנת\"ל ג' מיני חולאים בנפש כמו\"כ ישנם בלבושי הנפש מחו\"ד ג\"כ. א, חולה בדקות הוא מי שנופל לו מח\"ז בשעת התפלה ולפ\"ע דקות האדם לפ\"ע זה דקות המח\"ז וכמארז\"ל על ר\"ח יומא חדא הוה בעית לאכוונה<sup data-n=\"3385\">108</sup> נפל לי' אלקפתא<sup data-n=\"3386\">109</sup> וריש גלותא מאן אעיל קדם מלכא קדים, הגם שבמח\"ז זו יש כמה כוונות דאין פי' בגשמיות<sup data-n=\"3387\">110</sup> למטה אלא מדרי' זו ומדרי' זו מי נתעלה למעלה קודם, דאדם אחר יכול להתפלל במח\"ז זו אך לגבי ר\"ח ובניו שבכח תפילתם הי' בכוחם להביא משיחא בלא זמני'<sup data-n=\"3388\">111</sup> ה\"ז ג\"כ מח\"ז ומזה יובן לכל אדם לפ\"ע דקותו כמו\"כ המח\"ז דאפשר שלגבי' הוא מח\"ז לגבי אחר אינו מח\"ז וה\"ז חולה בדקות. ב' חולה שאין בו סכנה היינו מי שהוא משוקע מכף רגלו ועד ראשו<sup data-n=\"3389\">112</sup> ועד בכלל במח\"ז של תאוות היתר איך להשיג התאווה וכשישיג אותה איך יתנהג עמה יעשה כך ויעשה כך, וזה",[["3376","99","<b>מליא כריסא זיני בישא</b>: ראה ברכות לב, א."],["3377","100","<b>בעשותו אחת מכל מצות ה'. . ואשם</b>: ויקרא ד, כז [ושם: בעשותה. . ממצות]. וראה גם שם, יג. כב. ה, יז."],["3378","101","<b>מגשם</b>: אינו ברור בגוכתי\"ק."],["3379","102","<b>עי\"ז</b>: אינו ברור בגוכתי\"ק ואולי כצ\"ל."],["3380","103","<b>חיי החיים</b>: יומא עא, א."],["3381","104","<b>שאין לך דבר שעומד מפני התשובה</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. לקו\"ש בא כרך ו ע' 66 הערה 54."],["3382","105","<b>ראב\"ד. . שיצאה נשמתו</b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."],["3383","106","<b>במקום שבעלי תשובה עומדים</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. תו\"ח שמות ח\"א מא, א. וש\"נ. סה\"מ מלוקט ד' ס\"ע יח."],["3384","107","<b>דמאן דמשכי לי' בחילי יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. תו\"ח שמות ח\"א לז, א. וש\"נ."],["3385","108","<b>ר\"ח יומא חדא הוה בעית לאכוונא</b>: ראה ירושלמי ברכות פ\"ב, סה\"ד."],["3386","109","<b>אלקפתא</b>: ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן ובהערה 370."],["3387","110","<b>דאין פי' בגשמיות</b>: ראה אוה\"ת ואתחנן ע' קנה. פלח הרמון ויקרא ע' קיט ואילך."],["3388","111","<b>להביא משיחא בלא זמני'</b>: ב\"מ פה, ב."],["3389","112","<b>מכף רגלו ועד ראשו</b>: ע\"פ ישעי' א, ו."]]],[2000470389,"הוא חולה ממש אך אין בו סכנה שבקל יכול לדחותם. ג' חולה שיש בו סכנה היינו שמשוקע במח\"ז של תאוות איסור דהרהורי עבירה קשים מעבירה<sup data-n=\"3390\">113</sup> ועי\"ז נעשה בגדים צואים, ובאמת עי\"ז נדחה ממחיצתו של הקב\"ה דמה קדירה<sup data-n=\"3391\">114</sup> שבישל בהם קדירה לרבו לא ימזוג כוס לרבו<sup data-n=\"3392\">115</sup> כ\"ש בבגדים צואים דכתי' אין לבוא אל המלך<sup data-n=\"3393\">116</sup> בלבוש שק, ש\"ק בגימ' ד' מאות<sup data-n=\"3394\">117</sup> והוא לבוש גס דעשי'<sup data-n=\"3395\">118</sup> ולכה\"פ הוא נקי ולכן אין לבוא רק בחצר הפנימי אבל בחצר החיצוני יוכל לכנוס אבל בבגדים הצואים האלו נדחה לגמרי אפי' מחצר החיצוני<sup data-n=\"3396\">119</sup>, וזהו נשמה שנתת בי טהורה היא<sup data-n=\"3397\">120</sup>, היינו שנקי' מכל סיג ופסולת ואינו דבר נוסף על עצמותו כלל רק חלק הוי'<sup data-n=\"3398\">121</sup> כמו שהוא וע\"י המח\"ז האלו מטנף הנשמה ומלביש אותה בלבושים צואים וכ\"ז אפי' במח\"ז של תאוות היתר ומכ\"ש במח\"ז של תאוות איסור הנה אמרז\"ל עבירה מלפפתו<sup data-n=\"3399\">122</sup> ואין מקום שיכנס הרהור תשובה אבל מח\"ז של תאוות היתר רק מלבישים אותה ויש מקום שיכנס הרהור תשובה.\n<b>וזהו</b> ויקח מאבני המקום ולא כל אבני המקום דאותיות מח\"ז של תאוות איסור צריכים לדחות לגמרי וכמארז\"ל כלי חרס שבירתן זהו תקנתן<sup data-n=\"3400\">123</sup> וכמו כ\"ח כ\"ז שראוים קצת למלאכתה אינו בטל מתורת כלי<sup data-n=\"3401\">124</sup> כמו\"כ כאן כ\"ז שיש בהם איזה תאווה לא טוב הדבר רק צריכים לדחותם לגמרי, אך מח\"ז של תאוות היתר בירור אותם, דהנה היצה\"ר בעצם אינו רע<sup data-n=\"3402\">125</sup> רק כח המתאווה ואפשר שיתאווה אלקות<sup data-n=\"3403\">126</sup> וזהו ואהבת בכל לבבך בשני יצריך<sup data-n=\"3404\">127</sup> שגם היצה\"ר יהי' לו אהבה לאלקות וצ\"ל הלא",[["3390","113","<b>דהרהורי עבירה קשים מעבירה</b>: ראה יומא כט, א. מאמרי אדה\"א דברים ח\"א ע' קיד. וש\"נ. נ\"ך ע' פח. וש\"נ. שע\"ת ד, ד ובהערה 29."],["3391","114","<b>קדרה</b>: אוצ\"ל: בגדים."],["3392","115","<b>בגדים שבישל. . כוס לרבו</b>: שבת קיד, רע\"א."],["3393","116","<b>אין לבוא אל המלך</b>: אסתר ד, ב [בדילוג]."],["3394","117","<b>ש\"ק בגימ' ד' מאות</b>: ראה שער רוח הקדש כונת שק. מבוא שערים ש\"ג ח\"ב פ\"ט. מאמרי אדה\"ז תקס\"ה ח\"א ע' פה (נו\"א). ע' פג (נו\"ש). תו\"א וישלח כד, ג. תו\"ח שם קפג, ריש ע\"ב."],["3395","118","<b>לבוש גס דעשי'</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרנב ואילך (נו\"א). ס\"ע תרנד ואילך (נו\"ש)."],["3396","119","<b>ולכן אין לבוא. . החיצוני'</b>: ראה מ\"ש לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן."],["3397","120","<b>נשמה. . טהורה היא</b>: ברכת אלקי נשמה (מברכות ס, ב). וראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 193."],["3398","121","<b>חלק הוי'</b>: האזינו לב, ט. ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ד ד\"ה וככל. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' ד\"ה וככל."],["3399","122","<b>עבירה מלפפתו</b>: סוטה ג, ב."],["3400","123","<b>כלי חרס שבירתן זהו תקנתן</b>: ראה כלים פ\"ב, מ\"א."],["3401","124","<b>כ\"ח. . מתורת כלי</b>: ראה רמב\"ם הל' כלים רפי\"ט."],["3402","125","<b>היצה\"ר בעצם אינו רע</b>: ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' על יד הערה 54. לעיל (בחלק המאמרים) המשך זאת חנוכת המבח פ\"ב."],["3403","126","<b>כח המתאוה. . אלקות</b>: ראה לקו\"ת חוקת נו, סע\"ג ואילך. סה\"מ תרל\"ח ע' קסג. וש\"נ."],["3404","127","<b>ואהבת בכל לבבך בשני יצריך</b>: ואתחנן ו, ה [בדילוג] ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פט\"ז."]]],[2000470390,"היצה\"ר הוא מסית ומדיח איך שייך שיהי' לו אהבה לאלקות, וגם צ\"ל מה שייך ציווי על אהבה<sup data-n=\"3405\">128</sup> הרי אהבה היא מדה שבלב ואיך שייך ע\"ז ציווי, אך הציווי אינה על האהבה כ\"א על ההתבוננות איך דאני הוי' לא שניתי<sup data-n=\"3406\">129</sup> שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה אתה הוא קודם שנבה\"ע<sup data-n=\"3407\">130</sup> ואתה הוא אחר שנבה\"ע דכללות השתל' העולמות הוא רק שם והארה בעלמא שאינו נוגע לעצמיות, ומצד התבוננות זו יבוא לאהבה לאלקות, והנה היצה\"ר בעצם אינו רע רק כח המתאווה ומצד הכח המתאווה אפשר שיתאווה אלקות לכן כשיתבונן בהתבוננות זו גם היצה\"ר יהי' לו אהבה לאלקות, וזהו ויקח מאבני המקום הם אותיות דתאוות היתר וא' ל' רבים שהם רה\"ר טורי דפרודא<sup data-n=\"3408\">131</sup> וישם אותה מצבה ל' יחיד שהוא ביטול, וראי' דאוא\"ס אין שורה במקום<sup data-n=\"3409\">132</sup> ביטל וכ' בסש\"ב<sup data-n=\"3410\">133</sup> אחד האמת שבו שורה אוא\"ס וכ' שם וזוהי מדרי' החכ' א\"כ חכ' הוא ביטול שהוא אחד וכ' לפני אחד מה אתה סופר<sup data-n=\"3411\">134</sup> שבמספר לא יש פחות מאחד וזהו שעשה מאבני רבים אבן אחת, וכמו נפשות ל' רבים שהוא רה\"ר טורי דפרודא ונפש ל' יחיד<sup data-n=\"3412\">135</sup> שהוא ביטל, ויצוק עלי' שמן<sup data-n=\"3413\">136</sup> הוא בחי' חכ'<sup data-n=\"3414\">137</sup> והו\"ע שמחזיר תלמודו של ע' שנה, על ראשו שהוא הכלי לזה כמו מוח שבראש הוא כלי לשכל כמו\"כ הראש הוא כלי להחכ', (ובפ\"א<sup data-n=\"3415\">138</sup> וזהו וישם אות\"ה מצבה<sup data-n=\"3416\">139</sup> אותה ל' נקבה שהוא מקבל להורות שנעשה מקבל להשמן), וזהו אבן בוחן, אבן ישראל, אבן שתי' שממנו הושתה<sup data-n=\"3417\">140</sup> העולם, דהנה אבא יסד ברתא<sup data-n=\"3418\">141</sup> שמקור העולמות צ\"ל מבחי' חכ' וזהו אבן שתי', וזה תלוי באבן בוחן שנבחנו בו ישראל",[["3405","128","<b>ציווי על אהבה</b>: ראה גם סהמ\"צ להצ\"צ ע' קצט ובציונים והערות לשם ע' 404. מאמרי אדה\"א ויקרא ח\"ב ע' תשלז. סה\"מ תרכ\"ו ע' צד. תרכ\"ז ע' עד. תר\"ל ע' קמט. המשך והחרים תרל\"א ע' סו. סה\"מ תרל\"ח ס\"ע רנו. תרמ\"ו ע' תיב. תרנ\"ז ס\"ע קיח ואילך. לעיל ע' סח. לקמן ח\"ב ע' תשטז. סה\"מ תרמ\"א ד\"ה הקבצו ושמעו פ\"ב. וש\"נ."],["3406","129","<b>דאני הוי' לא שניתי</b>: מלאכי ג, ו."],["3407","130","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["3408","131","<b>רה\"ר טורי דפרודא</b>: ראה תניא ספל\"ג ובמ\"מ הגהות והערות קצרות לשם. מאמרי אדה\"א שמות ח\"א ע' רצו דברים ח\"ב ע' תעט ובהנסמן בהנ\"ל. לעיל (בחלק המאמרים) המשך מצה זו רפמ\"ט."],["3409","132","<b>שורה במקום</b>: אוצ\"ל: שורה אלא במקום."],["3410","133","<b>בסש\"ב</b>: ראה שם פל\"ה בהגהה."],["3411","134","<b>לפני אחד מה אתה סופר</b>: ראה ס\"י פ\"א, מ\"ז."],["3412","135","<b>נפשות. . ונפש ל' יחיד</b>: וישלח לו, ו. ויגש מו, כו וברש\"י שם. ויק\"ר פ\"ד, ו. שע\"ת עג, ד ובהערה 87."],["3413","136","<b>ויצוק עלי' שמן</b>: ויצא כח, יח [ושם: ויצוק שמן על ראשה]."],["3414","137","<b>שמן. . חכ'</b>: ראה זהר יתרו פז, ב תרומה קמז, ב ובהגהת הרח\"ו שם. מאורי אור מערכת שמן אות מח וביאיר נתיב שם. מאמרי אדה\"א קונטרסים ע' תקמה. וש\"נ. תו\"א מקץ מ, ד. סה\"מ תרל\"ח ע' כג. וש\"נ. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ט. וש\"נ."],["3415","138","<b>ובפ\"א</b>: ראה לעיל הערה 80."],["3416","139","<b>וישם אות\"ה מצבה</b>: ויצא כח, יב. וראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן על יד הערה 393."],["3417","140","<b>הושתה</b>: ראה לעיל על יד הערה 56: הושתת."],["3418","141","<b>אבא יסד ברתא</b>: ראה זהר רע\"מ פינחס רנו, ב. רמח, א. רנח, א. אגה\"ק ס\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפ הערה ד\"ה מצירופי. קונטרסים ס\"ע תקמז ואילך. תו\"ח שמות ח\"א יב, א."]]],[2000470391,"כשנופל מח\"ז והוא מדחה אותם ה\"ז בחינה ומזה נעשה אבן ישראל, וכתי' גם את העולם נתן בלבו<sup data-n=\"3419\">142</sup> לפ\"ע שמברר בנפשו מברר חלקו בעולם.\n<b>וזהו</b> מזבח אדמה כו' וזבחת עליו את עולותיך כו' והוא רוח האדם העולה למעלה<sup data-n=\"3420\">143</sup> וכמ\"ש אדם כי יקריב מכם<sup data-n=\"3421\">144</sup> דאדם בגימ' מ\"ה<sup data-n=\"3422\">145</sup> צריך ג\"כ הקרבה לבחי' כי לא אדם הוא וזהו עיקר מזבח, אך אם ההכרח שיהי' מזבח אבנים היינו שהוא משוקע במח\"ז של תאוות היתר ואיסור, לא תבנה אתהן גזית דאותיות של תאוות איסור צריכים לדחות לגמרי לכן לא תבנה כו' שלא ישאר מאומה, ואותיות של תאוות היתר צריכים שיתעלו כולם ולכן לא תבנה שלא ישאר מאומה, כי חרבך הנפת<sup data-n=\"3423\">146</sup> עלי' הוא חרב אוכלת<sup data-n=\"3424\">147</sup>, ותחללי'<sup data-n=\"3425\">148</sup> כמ\"ש ולא תחללו את שם קדשי שלא תעשו חלל<sup data-n=\"3426\">149</sup> ומקום ריקן וע\"י המח\"ז נעשה חלל כו' לכן לא תבנה כו', וזהו מזבח אדמה כו' לא יש שום תנאי שהוא עיקר מזבח, אך אם מזבח אבנים כו' בתנאי לא תבנה כו' דאותיות של תאוות איסור צריכים שישבר לגמרי ואותיות של תאוות היתר צריכים שיתעלה לגמרי ולא ישאר מאומה.",[["3419","142","<b>גם את העולם נתן בלבו</b>: קהלת ג, יא [ושם: בלבם]. ראה לקמן הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 74. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אני לדודי הב' על יד הערה 65. ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 72. לקו\"ת במדבר ה, ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקעט. ע' תרמ. אוה\"ת בלק ע' תתקמ."],["3420","143","<b>רוח האדם העולה למעלה</b>: ראה קהלת ג, כא."],["3421","144","<b>אדם כי יקריב מכם</b>: ויקרא א, ב."],["3422","145","<b>דאדם בגימ' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א הערה 14."],["3423","146","<b>כי חרבך הנפת</b>: המשך הכתוב ואם מזבח אבנים."],["3424","147","<b>חרב אוכלת</b>: ע\"פ האזינו לב, מב."],["3425","148","<b>ותחללי'</b>: ע\"פ סיום הכתוב ואם מזבח אבנים."],["3426","149","<b>ולא תחללו את שם קדשי. . חלל</b>: נסמן לעיל (בחלק המאמרים) בהמשך זאת חנוכת המזבח ספט\"ז הערה 410."]]],[2000470392,"<h3>ישקני מנשיקות פיהו</h3>\n<b>ש\"פ תרומה תר\"ם לפ\"ק</b>\n<b>ישקני</b> מנשיקות פיהו<sup data-n=\"3427\">1</sup>, ופירש\"י<sup data-n=\"3428\">2</sup> שלע\"ל יתגלה טעמי תורה, והאריך בזה שהבטיחם אותיתיה כו'<sup data-n=\"3429\">3</sup> תורה כי טעמי תורה לא נתגלו, וזהו שמבקשים שיתגלה טעמי תורה, וצ\"ל דעכשיו ישנם ג\"כ בתורה שהרי לא יהי' מ\"ת עוד הפעם<sup data-n=\"3430\">4</sup>",[["3427","1","<b>ישקני מנשיקות פיהו</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הח' מהמשך זאת חנוכת המזבח פרקים כ-כא שנדפס לעיל בחלק המאמרים (ושם הפתיחא: והנה לע\"ל כתיב בבכי יבואו). וש\"נ."],["3428","2","<b>ישקני. . ופירש\"י</b>: שה\"ש א, ב."],["3429","3","<b>אותיתיה כו'</b>: אוצ\"ל: טעמי' של."],["3430","4","<b>שהרי לא יהי' מ\"ת עוד הפעם</b>: ראה סה\"מ מלוקט א' ע' צז. ע' תסא. שם ה' ע' רעא ושם מציין: ”סה\"מ תרנ\"ו ע' שנו. תרס\"ו ע' כג. שם ע' תקמו. תער\"ב ח\"א ע' שסו. סה\"מ עטר\"ת ע' רצא. תרפ\"ה ע' קצט. ה'תש\"ט ע' 57 (הב') ועוד\". וראה גם מאמרי אדה\"ז תקס\"ב ח\"ב ע' תרפו. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרכה."]]],[2000470393,"רק שעכשיו הם בהעלם ולע\"ל יתגלה מההעלם אל הגילוי וצ\"ל מהו\"ע טעמי תורה שהרי לא יהי' מ\"ת עוד ומ\"מ ה\"ז דבר חדש.\n<b>הענין</b> הוא דהנה כמו שקודם מ\"ת כתי' ויאנחו בנ\"י<sup data-n=\"3431\">5</sup> מן העבודה ויזעקו והוא ע\"ד שארז\"ל מים תחתונים בוכים<sup data-n=\"3432\">6</sup> אנן בעינא למהוי קדם מלכא, דתחילה הי' מים במים<sup data-n=\"3433\">7</sup> ואח\"כ נעשה מים תחתונים, תי' תחתונים מורה שנעשה מקור לתענוגים גשמים וזהו שהם בוכים בעינא למהוי קדם מלכא, כמו\"כ לע\"ל כתי' בבכי יבואו<sup data-n=\"3434\">8</sup> ובתחנונים אובילם. והענין דהנה בכי' מעורר רחמים והוא מדתו של יעקב<sup data-n=\"3435\">9</sup> ורחמים גורם בכי' וז\"ש וישא את קולו ויבך<sup data-n=\"3436\">10</sup> שנשא את קולו לבחי' רחמים פשוטים שלמעלה מסדר השתל' ונק' רחמים רבים רחמים גדולים<sup data-n=\"3437\">11</sup>, וזהו מ\"ש בברכת ק\"ש אבינו אב הרחמן המרחם רחם נא עלינו, ולכאורה הוא יתור ל' הלא כבר אמר הרחמן ומהו אומרו אח\"כ עוד המרחם כו', אך הנה יש ב' מיני רחמים<sup data-n=\"3438\">12</sup> א' רחמים דסדר השתל' והוא מדתו של יעקב ונק' מדה הרי היא במדה וגבול הגם שמכריע בין חסד וגבו' אך היא נותנת מקום למדות הדין ונק' מדה הרי יש בה מדה וגבול, אך יש רחמים שלמעלה מסדר השתל' והוא רחמים דכתר, וזהו אבינו קאי על יעקב שהוא עיקר האב ועוד שהוא בחיר שבאבות<sup data-n=\"3439\">13</sup> אב הרחמן הוא רחמים דסדר השתל' (וכמ\"ש במ\"א ההפרש בין אב הרחמן לאב הרחמים<sup data-n=\"3440\">14</sup> ) ואח\"כ המרחם כו' שיומשך רחמים פשוטים שלמעלה מסדר השתל'.\n<b>וזהו</b> המלך המרומם לבדו מאז<sup data-n=\"3441\">15</sup> כו' אלקי עולם ברחמיך הרבים רחם עלינו וצ\"ל מה שייך המלך המרומם כו' למ\"ש אח\"כ ברחמיך הרבים כו'. אך מ\"ש המלך",[["3431","5","<b>ויאנחו בנ\"י</b>: שמות ב, כג."],["3432","6","<b>מים תחתונים בוכים</b>: ראה הנסמן לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ט הערה 487. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כנשר יעיר קנו על יד הערה 89 ואילך. ד\"ה עטרת תפארת שיבה על יד הערה 109."],["3433","7","<b>דתחילה הי' מים במים</b>: ראה ב\"ר פ\"ה, ב. שה\"א נג, ב הערה 16."],["3434","8","<b>בבכי יבואו</b>: ירמי' לא, ח."],["3435","9","<b>רחמים. . יעקב</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 18."],["3436","10","<b>וישא את קולו ויבך</b>: ויצא כט, יא."],["3437","11","<b>רחמים גדולים</b>: ראה תו\"ח שבהערה הבאה קעא, ב."],["3438","12","<b>ב' מיני רחמים</b>: ראה תו\"ח בשלח ח\"א קעא, א ואילך."],["3439","13","<b>יעקב. . בחיר שבאבות</b>: ראה ע\"ח שער לאה ורחל של\"ב, פ\"ב. לקו\"ת להאריז\"ל תולדות כז, כה. לקוטי שיחות ויחי כרך ג ע' 832 הערה 11."],["3440","14","<b>ההפרש בין אב הרחמן לאב הרחמים</b>: ראה לקו\"ת ר\"ה סב, ד. נשא כג, א. שה\"ש י, סע\"ג ואילך. סה\"מ תרל\"ו ח\"ב ע' שעד. תרל\"ח ע' תלא. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן פ\"כ. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה והנה כובע על יד הערה 18 ואילך. ד\"ה עטרת תפארת שיבה על יד הערה 123. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אשריכם זורעי על כל מים על יד הערה 99 ואילך. ד\"ה עטרת תפארת שיבה על יד הערה 108."],["3441","15","<b>המלך המרומם לבדו מאז</b>: נוסח ברכת יוצר."]]],[2000470394,"המרומם לבדו הוא מה שא\"ס מרומם ונשגב מגדר עולמות רק כמו שהוא לבדו וכללות העולמות הוא רק משם והארה בעלמא שאינו נוגע לעצמיות כלל וכמ\"ש מלך שמו נקרא עליהם<sup data-n=\"3442\">16</sup> כמו שם האדם שאינו נוגע לעצמיות, (אפ\"ל ע\"ד מ\"ש במ\"א בענין קדוש אתה ונורא שמך<sup data-n=\"3443\">17</sup> ואין אלוקה מבלעדיך כמו\"כ כאן המלך המרומם לבדו, ע' בסידור שער יוהכ\"פ<sup data-n=\"3444\">18</sup> וצ\"ע) ולכן אני ה' לא שניתי<sup data-n=\"3445\">19</sup> שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה אתה הוא קודם שנברה\"ע<sup data-n=\"3446\">20</sup> ואתה הוא לאחר שנבה\"ע דכללות השתל' העולמות הוא רק משם והארה בעלמא שאינו נוגע לעצמיות כלל. ומצד בחי' זו ברחמיך הרבים רחם עלינו דהנה הנשמה קודם התלבשותה בגוף כתי' חי ה' אשר עמדתי לפניו<sup data-n=\"3447\">21</sup> שעמדה באהוי\"ר וביטל לאלקות דאין עמידה למעלה אלא בביטל<sup data-n=\"3448\">22</sup> וכמ\"ש ויעמידם לעד לעולם<sup data-n=\"3449\">23</sup> דיש מלאכי' שמוי\"ב אומרים קדוש פעם ג' שאמרו פעם א' קדוש ועמדו ב' אלפים שנה בביטל כו' ועתה עומדים בביטל דקדוש דפעם ג'<sup data-n=\"3450\">24</sup>, וכ\"ש נשמות וירדה למטה בגוף ונה\"ב המעלים ומסתיר, דכמו שהי' למעלה כל נשמה דבוקה בא\"ס חיי החיים<sup data-n=\"3451\">25</sup> ודאפי' נפש דמל' דמל' דעשי'<sup data-n=\"3452\">26</sup> בתוכו מל' דיצי' ובתוכו מל' דבריאה ובתוכו מל' דאצי' ובתוכו חכ' דאצי' שבו שורה אוא\"ס<sup data-n=\"3453\">27</sup>, ועכשיו ירדה להתלבש בגוף ונה\"ב, וזהו שאומרים ברחמי\"ך הרבים דאנו אין אנו יודעים איך גבהה מעלתה קודם התלבשותה בגוף וממילא אין אנו יודעין הירידה אח\"כ, ועוד דעל כל פשעים תכסה אהבה<sup data-n=\"3454\">28</sup> דאהבה שאוהב א\"ע מכסה על הפשעים שאינו רואה הפשע ר\"ל החסרון כלל ואף שיש איזה",[["3442","16","<b>וכמ\"ש מלך שמו נק' עליהם</b>: וכ\"ה גם במאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' נ. סה\"מ תרס\"ג ח\"א ע' סב. ח\"ב ע' לו. המשך תער\"ב ח\"ב ע' תשצ. ראה פיוט אדון עולם. מאמר ד\"ה לכן אמור תקס\"ג נדפס בתו\"ח וארא ח\"א סט, ב ואילך. וש\"נ."],["3443","17","<b>קדוש אתה ונורא שמך</b>: נוסח תפלת העמידה לימים נוראים."],["3444","18","<b>קדוש אתה. . בסידור שער יוהכ\"פ</b>: רנ, ג. ראה גם סה\"מ תרס\"ו ע' שסג."],["3445","19","<b>אני ה' לא שניתי</b>: מלאכי ג, ו. ראה גם לקמן הנחה ד\"ה גל נעול על יד הערה 62."],["3446","20","<b>אתה הוא קודם שנברה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["3447","21","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["3448","22","<b>עמידה. . בביטול</b>: ראה סוטה לט, א. וראה גם לעיל שם ובהערה 61."],["3449","23","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א. וש\"נ. לקמן הנחה ד\"ה הנה אנכי כורת ברית קרוב לתחילתה. ד\"ה סמכוני באשישות פיסקא והנה צ\"ל. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה אחת הא' פיסקא והנה צלה\"ק. ד\"ה אני לדודי (הא') פיסקא והנה עתה. (הב') פיסקא ושרש הענין."],["3450","24","<b>דיש מלאכי' שמוי\"ב אומרים קדוש. . דפעם ג'</b>: ראה גם לעיל הנחה ד\"ה זאת חנוכת המזבח על יד הערה 20. לקמן הנחה ד\"ה ואתה תצוה על יד הערה 16. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כנשר יעיר קנו על יד הערה 39 (בחלק ההנחות) בהנחה שם על יד הערה 46. סה\"מ תרל\"ב ח\"א ע' שכ. תרל\"ח ס\"ע לז ואילך. וש\"נ. דרושי חתונה מכ\"ק אדמו\"ר מהר\"ש ע' נט."],["3451","25","<b>חיי החיים</b>: יומא עא, א."],["3452","26","<b>נפש דמל' דמל' דעשי'</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 11."],["3453","27","<b>נפש דמל'. . שורה אוא\"ס</b>: ראה תניא פי\"ח."],["3454","28","<b>דעל כל פשעים תכסה אהבה</b>: משלי י, יב."]]],[2000470395,"חסרון אינו גדול כ\"כ בעיניו וע\"ד אין אדם רואה חוב לעצמו<sup data-n=\"3455\">29</sup> (וכמו אב לבנו או לאו\"נ<sup data-n=\"3456\">30</sup> וזהו\"ע השוחד ע' מזה בתו\"ח בד\"ה ארדה נא ואראה<sup data-n=\"3457\">31</sup> ) אך למעלה ידוע מעלות הנשמה קודם התלבשותה בגוף וירידתה אח\"כ בהתלבשותה בגוף ואין שייך על כל פשעים תכסה אהבה מבקשים שמשם יומשך רחמים פשוטים, והנה לע\"ל כתי' ברחמים גדולים אקבצך<sup data-n=\"3458\">32</sup> שלע\"ל יומשך בחי' רחמים גדולים הנ\"ל וזהו שלע\"ל יתגלה טעמי תורה.\n<b>והענין</b> דהנה כתי' ובלילה שירה עמו<sup data-n=\"3459\">33</sup> ואמרז\"ל כל העוסק בתורה בלילה<sup data-n=\"3460\">34</sup> הקב\"ה מושך עליו חוט של חסד ביום, וארז\"ל שם בלילה עוה\"ז<sup data-n=\"3461\">35</sup>, דהנה ארז\"ל דוד זמירות קרית לי'<sup data-n=\"3462\">36</sup> הריני מכשילך בדבר שתינוקת של בית רבן יודעים אותן כתי' לבני קהת לא נתן כי עבודת הקדש עליהם בכתף ישאו<sup data-n=\"3463\">37</sup> והוא נשא את הארון בעגלות<sup data-n=\"3464\">38</sup>, וצ\"ל מה הי' החטא שלו, אך הנה דוד בעת צרתו שהי' צר לו מאד בגשמיות הי' משתעשע א\"ע בתורה שהרי כל חיות העולמות תלוי בתורה שאם יארע פסול בתפילין בטל כל ההמשכות<sup data-n=\"3465\">39</sup>, וכן בקרבן שעי\"ז העלאת העולמות<sup data-n=\"3466\">40</sup> אם יארע בו איזה פסול או שיחשוב מחשבת חוץ<sup data-n=\"3467\">41</sup> בטל כל ההמשכה, וא\"כ מאחר שלומד תורה מה תופס מקום אצלו מה שצר לו בגשמיות, אך זהו חיצוניות התורה, ויש עוד בחי' בתורה שעלי' נא' לא ידע אניש ערכה<sup data-n=\"3468\">42</sup> אלקים הבין דרכה<sup data-n=\"3469\">43</sup> והם שעשועי המלך בעצמותו<sup data-n=\"3470\">44</sup> והוא בחי' פנימיות התורה שיר דתורה והוא בחי' טעמי תורה שלגבי בחי' זו כל בחי' התורה שחיות העולמות תלוי בה אינו תופס מקום כלל, ודוד ששיבח את התורה בבחי' חיצוניות שבה לכן נענש<sup data-n=\"3471\">45</sup>, וזהו שאמרז\"ל ג'",[["3455","29","<b>אין אדם רואה חוב לעצמו</b>: ראה שבת קיט, א."],["3456","30","<b>לאו\"נ</b>: לאוהב נאמן."],["3457","31","<b>בתו\"ח בד\"ה ארדה נא ואראה</b>: וירא קא, סע\"א ואילך. קיד, ד."],["3458","32","<b>ברחמים גדולים אקבצך</b>: ישעי' נד, ז [ושם: וברחמים — אבל כ\"ה גם לעיל (בחלק המאמרים) בהמשך זאת חנוכת המזבח כאן ובהערה 518. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אשריכם זורעי על כל מים על יד הערה 100]."],["3459","33","<b>ובלילה שירה עמו</b>: תהלים מב, ט [ושם: עמי]."],["3460","34","<b>כל העוסק בתורה בלילה</b>: חגיגה יב, ב."],["3461","35","<b>וארז\"ל שם בלילה עוה\"ז</b>: להאיכא דאמרי — הובא לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן רפכ\"א."],["3462","36","<b>דוד זמירות קרית לי'</b>: ע\"פ אגה\"ק זה (תניא קס, א). ראה סוטה לה, סע\"א."],["3463","37","<b>לבני קהת לא נתן. . עליהם בכתף ישאו</b>: נשא ז, ט [ושם: ולבני[ednref_207_א]]. בגמ' (במקום סיום הכתוב עליהם בכתף ישאו): וגו'. אבל כ\"ה בע\"י סוטה שם. וראה גם ירושלמי סנהדרין פ\"י, ה\"ב."],["3464","38","<b>נשא את הארון בעגלות</b>: שמואל-א ו, ג."],["3465","39","<b>בתפילין. . ההמשכות</b>: ראה לקמן הנחה ד\"ה ואתה תצוה ובהערה 38."],["3466","40","<b>בקרבן. . העלאת העולמות</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 92."],["3467","41","<b>שיחשוב מחשבת חוץ</b>: ראה לקמן הנחה ד\"ה ואתה תצוה ובהערה 41."],["3468","42","<b>לא ידע אנוש ערכה</b>: איוב כח, יג."],["3469","43","<b>אלקי' הבין דרכה</b>: איוב שם, כג."],["3470","44","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. וש\"נ."],["3471","45","<b>ודוד. . נענש</b>: ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן רפכ\"א. וש\"נ. לקמן הנחה ד\"ה ואתה תצוה על יד הערה 37.\n\n[edn_207_א] אבל כ\"ה גם לקמן בהנחה ד\"ה ואתה תצוה הערה 35."]]],[2000470396,"שעות הראשונות הקב\"ה יושב ועוסק בתורה<sup data-n=\"3472\">46</sup> פי' רז\"ל דהנה כתי' הוי' הוי' פסיק טעמי<sup data-n=\"3473\">48</sup> בינייהו שיש ב' שמות הוי' א' שם הוי' דסדר השתל' ב' שם הוי' שלמעלה מסדר השתל', וזהו הקב\"ה יושב ועוסק בתורה ר\"ל ש' הוי' שלמעלה מסדר השתל' יומשך בתורה<sup data-n=\"3474\">47</sup>.\n<b>וביאור</b> הענין דהנה בתורה יש ד' בחי' טעמים נקודות תגין אותיות, אותיות הם בחג\"ת<sup data-n=\"3475\">49</sup> דהנה אותיות הם כמו כלים<sup data-n=\"3476\">50</sup> שע\"י נוטלין את השכל דאינו שייך שכל בלתי אותיות וכמו עד\"מ הנהר מפני שהוא מלא על כל גדותיו א\"א שישפוך ממנו בכלים קטנים רק בדרך שאיבה אבל בדרך שפיכה אינו שייך מהנהר עצמו רק ע\"י הצינור שהמים נמשך בהצינור ומשם אפשר שיומשך בכלים קטנים, כמו\"כ האותיות הם כלים אל השכל, והנה באותיות יש ך\"ב אותיות וה\"ז כמו עד\"מ גבורות גשמים<sup data-n=\"3477\">51</sup> שנק' גבורות מפני שיורדים טיף טיף ובאמת ה\"ז תגבורת החסדים שאם לא הי' נחלק לטיפין לא הי' העולם יכול לקבלם, וכמו\"כ מה שהאותיות נחלקו זהו תכלית הטוב והחסד ולכן האותיות הם בחג\"ת, ועוי\"ל דהנה האותיות כמו שהם א' ב' ג' ד' אין בהם שום צירוף אך שמצרפן כמו ב ר ו ך ה\"ז תיבת ברוך ומי הוא המצרפן הרי אין זה האותיות וזהו תגבורת החסדים, וכמ\"ש בתניא<sup data-n=\"3478\">52</sup> יש צירופים דעשרה אותיות<sup data-n=\"3479\">53</sup> כו' ועוד זאת עולה על כולנה כח עליון המצרפן ומחברן<sup data-n=\"3480\">54</sup>, ולכן האותיות בחג\"ת, ועוי\"ל שכן אי' בס\"י<sup data-n=\"3481\">55</sup> שיש אותיות דחסד ואותיות דגבו' ואותיות דאמצעים, ומה שנת' במ\"א דאותיות הם במל' זהו אותיות דע\"מ ואותיות דעה\"ד הם בחג\"ת<sup data-n=\"3482\">56</sup>, ותגין הם כתרי אותיות דהנה ארז\"ל כשעלה משה למרום<sup data-n=\"3483\">57</sup> מצא את הקב\"ה יושב וקושר כתרים לאותיות וס\"א<sup data-n=\"3484\">58</sup> תגין לאותיות והכל א' דתגין הוא כתר וכמו דאישתמש בתגא<sup data-n=\"3485\">59</sup> והוא כמ\"ש בעטרה שעטרה לו<sup data-n=\"3486\">60</sup>, ועטרה הוא ע\"ג הראש,",[["3472","46","<b>ג' שעות. . ועוסק בתורה</b>: ראה ע\"ז ג, ב."],["3473","48","<b>הוי' הוי' פסיק טעמי</b>: תשא לד, ו. זהר אד\"ר נשא קלח, רע\"א. ראה אוה\"ת וארא כרך ז' ע' ב'תקסד. סה\"מ תרל\"ח ע' נה. וש\"נ."],["3474","47","<b>פי' רז\"ל. . שלמעלה מסדר השתל' יומשך בתורה</b>: רבינו ז\"ל — ראה לקו\"ת שה\"ש א, ג."],["3475","49","<b>אותיות הם בחג\"ת</b>: ראה בסמוך בפנים בשם ס\"י. פרדס שער האותיות שכ\"ז, פ\"ג."],["3476","50","<b>האותיות. . כלים</b>: נסמן לעיל (בחלק המאמרים) במאמר ד\"ה כמגדל דוד צוארך הערה 33."],["3477","51","<b>גבורות גשמים</b>: תענית ב, א. ראה סידור שחרית סא, ד. שער הסוכות רנז, ד. שער הלולב רסד, ב. מאמרי אדה\"ז הנחות הר\"פ ע' נו. תקס\"ב ח\"א ע' לב. ענינים ע' שפ. אמרי בינה שער הק\"ש נא, א ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'תכח ואילך. סה\"מ תרכ\"ז ס\"ע רמט ואילך. וש\"נ."],["3478","52","<b>בתניא</b>: תיבה זו איננה ברורה."],["3479","53","<b>בתניא יש צירופים דעשרה אותיות</b>: ראה גם לעיל הנחה ד\"ה מזבח אדמה תעשה לי ובהערה 40."],["3480","54","<b>בתניא. . ועוד זאת. . ומחברן</b>: ראה שער היחוד והאמונה פי\"ב."],["3481","55","<b>אי' בס\"י</b>: ראה שם רפ\"ב."],["3482","56","<b>דאותיות הם במל'. . בחג\"ת</b>: ראה גם לקמן הנחה ד\"ה ואתה תצוה על יד הערה 29."],["3483","57","<b>כשעלה משה למרום</b>: ראה מנחות כט, ב. שבת פט, א."],["3484","58","<b>וס\"א</b>: וספרים אחרים? — ראה רש\"י שם. וראה גם תו\"ח שמות ח\"א י, ב. סה\"מ תרכ\"ו ע' קלה."],["3485","59","<b>דאישתמש בתגא</b>: אבות פ\"ד, מ\"ה."],["3486","60","<b>בעטרה שעטרה לו</b>: שה\"ש ג, יא."]]],[2000470397,"כמו\"כ כאן כשיש אותיות והראש של האותיות אח\"כ הוא העטרה, ועל ל' הקבלה הוא מה שת\"ת דאימא נעשה כתר לז\"א<sup data-n=\"3487\">61</sup>, ועם זה יובן בין תגין שהוא כתר לטעמים, דטעמים הוא בחי' כתר<sup data-n=\"3488\">62</sup> ה\"ז כתר עליון גם לחו\"ב דאצי' אבל מה שתגין הוא כתר הוא רק כתר לז\"א אבל בבינה הוא בחי' חג\"ת שהם בחי' אותיות ובינה הוא מקור המקיפי'<sup data-n=\"3489\">63</sup> נעשה מת\"ת דאימא כתר לז\"א, וידוע דתגין בעולם היותר עליון במדרי' הם אותיות ולכן התגין הם תמונות האותיות וע\"ד שאמרז\"ל צדיקים יושבים ועטרותיהם בראשיהם והוא בחי' נשמות החדשות<sup data-n=\"3490\">64</sup> מ\"מ נק' עטרה דלגבי נשמות הישינות הם רק בחי' מקיף עליהם.\n<b>וזהו</b> מ\"ש ומשוש חתן על כלה<sup data-n=\"3491\">65</sup> ישיש עליך אלקיך, חתן הוא בחי' תושב\"כ, וכלה הוא בחי' תושבע\"פ<sup data-n=\"3492\">66</sup>, והנה כל ההשפעה דתושב\"כ לתושבע\"פ הוא רק אותיות כמו ענין השבת בתושב\"כ הם רק איזה פסוקים ובתושבע\"פ נעשה מזה אריכות וכמו דברים הדברים, אלה הדברים<sup data-n=\"3493\">67</sup>, לומדים מזה ל\"ט אבות מלאכות, וכן מבסכות תשבו לומדים מזה כל עניני סוכות<sup data-n=\"3494\">68</sup> ועלמות אין מספר<sup data-n=\"3495\">69</sup>, והנה נת\"ל שהאותיות הם בחג\"ת הנה יש אתוון רברבין ואתוון זעירין ואתוון בינונין<sup data-n=\"3496\">70</sup> והם יסוד בינה ויסוד ז\"א ומל' ורובו של תורה הם אתוון בינונין והוא בחי' ז\"א, וזהו שישים המה מלכות שמונים<sup data-n=\"3497\">71</sup> פלגשים עלמות אין מספר אחת היא יונתי<sup data-n=\"3498\">72</sup>, ששים המה מלכות הוא בחי' אותיות דתורה אחת היא יונתי הוא בחי' רעו\"ד שעי\"ז ממשיכים טעמי תורה שיר של תורה, וזהו מ\"ש טוב טעם ודעת למדני<sup data-n=\"3499\">73</sup> כי במצותיך האמנתי דאמונה הוא למעלה מטו\"ד וכמו\"כ מצות הם ג\"כ כמו אמונה ע\"י המצות באים לבחי' טוב טעם שהוא בחי' טעמי תורה שהם בכתר, הגם שבמ\"א נת' דטעמים הם בחכ'<sup data-n=\"3500\">74</sup>, הנה יש טעם וטוב טעם וטוב טעם הוא בכתר, וזהו\"ע",[["3487","61","<b>שת\"ת דאימא נעשה כתר לז\"א</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, רפ\"ה ורפ\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["3488","62","<b>דטעמים. . כתר</b>: ראה גם לקמן הנחה ד\"ה ואתה תצוה ובהערה 56."],["3489","63","<b>ובינה הוא מקור המקיפי'</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. לקו\"ת להאריז\"ל תהלים סנ\"ג."],["3490","64","<b>צדיקים יושבים ועטרותיהם בראשיהם. . נשמות החדשות</b>: ברכות יז, א. ראה אוה\"ת סוכות ע' א'תשנח."],["3491","65","<b>ומשוש חתן על כלה</b>: ישעי' סב, ה."],["3492","66","<b>חתן. . תושב\"כ וכלה. . תושבע\"פ</b>: ראה ערכי הכנויים לבעל סדה\"ד מערכת חתן. לקו\"ת ברכה צד, ג. צה, ד. מאמרי אדה\"א דרושי חתונה ח\"א ע' טו. וש\"נ. סה\"מ תרל\"ח ע' קנה ואילך."],["3493","67","<b>דברים הדברים אלה הדברים</b>: ויקהל לה, א. שבת צז, ריש ע\"ב וברש\"י שם. וש\"נ. סה\"מ תרל\"ח ע' קמט. וש\"נ."],["3494","68","<b>מבסכות תשבו. . סוכות</b>: אמור כג, מב. ראה גם לקמן הנחה ד\"ה ואתה תצוה על יד הערה 23. אוה\"ת וארא כרך ז' ע' בתקעה [ושם: בסוכות תשבו ולקחתם לכם. . מסכת סוכות]. הובא לעיל [בחלק המאמרים] בהמשך זאת חנוכת המזבח פכ\"ב. תו\"ח ויקהל ח\"ב תכד, ב. וש\"נ."],["3495","69","<b>ועלמות אין מספר</b>: שה\"ש ו, ח."],["3496","70","<b>אתוון. . בינונין</b>: לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן מציין למאו\"א אות א' סנ\"ב."],["3497","71","<b>שישים המה מלכות שמונים</b>: שה\"ש ו, ח [ושם: ושמונים]."],["3498","72","<b>אחת היא יונתי</b>: שם ו, ט. ראה לקו\"ת פ' ראה לא, ד. שה\"ש מא, ג ואליך."],["3499","73","<b>טוב טעם ודעת למדני</b>: תהלים קיט, סו."],["3500","74","<b>דטעמים הם בחכ'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. לקו\"ת חוקת נז, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' א'יט. מאמרי אדה\"א ויקרא ח\"ב ר\"ע תתלד. וש\"נ. דברים ח\"ד ע' א'תע. וש\"נ. לקמן הנחה ד\"ה ואתה תצוה ובהערה 28."]]],[2000470398,"רננא דאורייתא<sup data-n=\"3501\">75</sup> שהוא בחי' טעמי תורה, וזהו ומשוש חתן על כלה ישיש עליך אלוקיך ומשוש חתן על כלה הוא בחי' אותיות התורה עי\"ז ישיש כו' יתגלה לע\"ל טעמי תורה שזהו ישיש ב\"פ יש<sup data-n=\"3502\">76</sup> דהנה קנה חכ' קנה בינה בגימ' יש<sup data-n=\"3503\">77</sup> והוא פעם א' יש וישיש הוא ב\"פ יש והוא מחצה העליון דכתר, (פ\"ג<sup data-n=\"3504\">78</sup>, ומשוש חתן כו' הוא תגין שזה יש, ואפ\"ל דהנה משוש הוא ג\"כ כתר אך הוא כתר דתגין שמת\"ת דאימא כו' וזה יש בתורה שנתגלה עכשיו וע\"י יגיעה יכולים להשיג בחי' תגין וכמו ר\"ע שהי' דורש<sup data-n=\"3505\">79</sup> על כל קוץ כו' ועי\"ז יתגלה לע\"ל בחי' כתר עליון שהוא כתר גם לחו\"ב דאצי', וזהו שנת\"ל דאמרז\"ל דלילה הוא עוה\"ז דע\"י עסק התורה בעוה\"ז זוכה שיתגלה לע\"ל בחי' טעמי תורה).\n<b>ונקודות</b> הם בחכ'<sup data-n=\"3506\">80</sup> דהנה הנקודות מנהיגים האותיות כשנקוד נקודה זו אומרים התיבה כך וא\"ל באו\"א, וכמ\"ש לפי שכלו יהולל איש<sup data-n=\"3507\">81</sup> שהשכל מנהיג את המדה, וזהו\"ע נקודה בהיכלא נקודה חכ' בהיכלא בינה<sup data-n=\"3508\">82</sup>, ומה שנת' בלקו\"ת<sup data-n=\"3509\">83</sup> נקודה בהיכלא הוא למעלה מטו\"ד וא\"כ ה\"ז כמו טעמים, י\"ל מה שהוא למעלה מטו\"ד היינו לגבינו שאין אנו משיגים אבל בחכ' ה\"ז מושג אבל בחי' טעמים גם בחכ' אינו מושג דכולם בחכ' עשית<sup data-n=\"3510\">84</sup> לגבי א\"ס גם חכ' נחשבת כעשי' גשמיות<sup data-n=\"3511\">85</sup> וא\"כ שניהם אמת שהוא בחי' חכ' ומ\"מ למעלה מטו\"ד לגבינו, וטעמים הם בכתר דזרקא מקף שופר<sup data-n=\"3512\">86</sup> אינם מנהיגים את האותיות ולא נתגלו לנו שהם למעלה מהשגה, וצריכים להמשיך בחי' זו בתורה, וזהו על שלא ברכו בתורה תחילה<sup data-n=\"3513\">87</sup> ר\"ל",[["3501","75","<b>רננא דאורייתא</b>: ראה זהר בהקדמה ח, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקעא וע' תקפא. תקע\"א ע' ג. תו\"ח בראשית ד, א ובהערה 7."],["3502","76","<b>ישיש ב\"פ יש</b>: ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה והוא כחתן על יד הערה 4. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 14. אוה\"ת חנוכה ח\"ב ע' רצו. בהעלותך ע' שמח. ע' תיח. ישעי' ע' תתנז. ע' תתסח. סה\"מ תרל\"ג ח\"א ע' רסא. תרל\"ד ע' כו. המשך תער\"ב ח\"א ע' רכ. סה\"מ תש\"ז ע' 152. ד\"ה וישלח יעקב תשי\"ח. ראה גם סה\"מ תרל\"ב ח\"א ע' קנט וע' שח. תרנ\"ז ע' רצז."],["3503","77","<b>קנה חכ' קנה בינה. . יש</b>: משלי ד, ה. ראה פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ג [ירושלים תש\"מ תקעא, סע\"א]. שער יוה\"כ שכ\"ז, פ\"ה. שער הפסוקים משלי ס\"ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרס. תקע\"א ע' עה. מאמרי אדה\"א דברים ח\"א ע' טז. וש\"נ."],["3504","78","<b>פ\"ג</b>: פעם ג'? ראה גם לעיל הנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["3505","79","<b>תגין וכמו ר\"ע שהי' דורש</b>: ראה מנחות כט, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפב. אוה\"ת וארא כרך ז ע' ב'תקנח. סה\"מ תרכ\"ז ע' קכח. וש\"נ. תרל\"ח ע' קנט."],["3506","80","<b>ונקודות הם בחכ'</b>: פרדס שער הנקודות שכ\"ח, פ\"ו. מאו\"א מערכת נקודות ס\"ל."],["3507","81","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."],["3508","82","<b>נקודה בהיכלא. . בינא</b>: מאו\"א שם. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה עטרת תפארת שיבה הערה 9."],["3509","83","<b>שנת' בלק\"ת</b>: פ' ראה יח, א ואילך."],["3510","84","<b>דכולם בחכ' עשית</b>: תהלים קד, כד."],["3511","85","<b>חכ' נחשבת כעשי' גשמיות</b>: ראה תניא פ\"ב בהגהה. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ח ובהערה 142."],["3512","86","<b>דזרקא מקף שופר</b>: ראה זהר בראשית כד, א. ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תסט."],["3513","87","<b>שלא ברכו בתורה תחילה</b>: ב\"מ פה, ב. נדרים פא, א. ראה גם לק\"ת פ' ראה כט, א. אוה\"ת ואתחנן ס\"ע רנב ואילך. דרך חיים פא, א. סה\"מ תרכ\"ט ע' רצ. וש\"נ. תרל\"ג ח\"ב ע' תלו ואילך. וש\"נ."]]],[2000470399,"שלא המשיכו המשכות אוא\"ס בתורה והיינו בחי' טעמי תורה, והנה ע\"י תפלה ממשיכים בחי' טעמי תורה ולכן מקדימים תחילה ברכת ק\"ש אבינו אב הרחמן כו' בברכה שני' ובברכה ראשונה המלך המרומם לבדו מאז כו' ברחמיך הרבים רחם עלינו ואח\"כ בק\"ש למס\"נ באחד<sup data-n=\"3514\">88</sup> ואח\"כ יש בכוחו בשמ\"ע לצוות ברוך אתה הוי' שיומשך משם הוי' וזהו שיתגלה טעמי תורה.\n<b>וזהו</b> ישקני מנשיקות פיהו שמבקשים שלע\"ל יתגלה טעמי תורה דעכשיו לא נתגלו נקודות<sup data-n=\"3515\">89</sup> תגין אותיות אבל טעמי תורה לא נתגלו שהם בהעלם ומבקשים שלע\"ל יתגלו מהעלם אל הגילוי, וכמו שקודם מ\"ת כתי' ויאנחו בנ\"י מן העבודה והוא ע\"ד מים תחתונים בוכים אנן בעינא למהוי קדם מלכא וכמו\"כ על לע\"ל כתי' בבכי יבואו בתחנונים<sup data-n=\"3516\">90</sup> אובילם שהוא בחי' רחמים פשוטים דכתר ועי\"ז יתגלה לע\"ל טעמי תורה.",[["3514","88","<b>למס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["3515","89","<b>לא נתגלו נקודות</b>: אוצ\"ל: נתגלו נקודות לא נתגלו רק נקודות."],["3516","90","<b>בתחנונים</b>: בירמי' לא, ח: ובתחנונים [כדלעיל על יד הערה 8 — ראה גם סה\"מ תרל\"ח ע' תלא]."]]],[2000470400,"<h3>ואתה תצוה</h3>\n<b>ש\"פ תצוה תר\"ם לפ\"ק</b>\n<b>ואתה</b> תצוה<sup data-n=\"3517\">1</sup> את בנ\"י ויקחו אליך שמן זית זך כתית למאור להעלות נר תמיד<sup data-n=\"3518\">2</sup> כו' מחוץ לפרוכת יערוך אותו אהרן מערב ועד בקר<sup data-n=\"3519\">3</sup>, למה במ\"ש מחוץ לפרוכת כתי' מערב ועד בקר ותחילה כתי' נר תמיד, גם צ\"ל מ\"ש ואת\"ה תצוה תי' ואתה מיותר שהרי הוא מדבר עם משה ומה צ\"ל ואתה, והענין דהנה ארז\"ל על שלא ברכו בתורה תחילה<sup data-n=\"3520\">4</sup> אין ר\"ל שלא ברכו כלל שזה אינו שייך לומר אלא שלא המשיכו המשכת אוא\"ס בתורה, דע\"י התפלה<sup data-n=\"3521\">5</sup> ממשיכים בחי' טעמי תורה, דהנה תפלה הו\"ע יהי רצון שיומשך רצון חדש<sup data-n=\"3522\">6</sup> שאם נגזר על א' ח\"ו מיתה או עוני יש",[["3517","1","<b>ואתה תצוה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הט' וסיום ההמשך זאת חנוכת המזבח פרקים כב-כג שנדפס לעיל בחלק המאמרים (ושם הפתיחא: וז\"ע שארז\"ל על שלא ברכו בתורה). וש\"נ."],["3518","2","<b>ואתה תצוה את בנ\"י. . תמיד</b>: תצוה כז, כ."],["3519","3","<b>מחוץ לפרוכת. . ועד בקר</b>: שם כז, כא [בדילוג. ושם: עד]."],["3520","4","<b>שלא ברכו בתורה תחילה</b>: ב\"מ פה, ב. נדרים פא, א. ראה גם לק\"ת פ' ראה כט, א. אוה\"ת ואתחנן ס\"ע רנב ואילך. דרך חיים פא, א. סה\"מ תרכ\"ט ע' רצ. וש\"נ. תרל\"ג ח\"ב ע' תלו ואילך. וש\"נ."],["3521","5","<b>דע\"י התפלה</b>: ראה גם מאמר ד\"ה תורה צוה תקס\"ז נדפס במאמרי אדה\"ז תקס\"ו ע' שעב."],["3522","6","<b>תפלה. . רצון חדש</b>: ראה גם לעיל\n(בחלק המאמרים) מאמר ד\"ה כמגדל דוד צוארך ובהערה 58."]]],[2000470401,"בכח התפלה להפך, וכמשארז\"ל מט\"ט קושר כתרים<sup data-n=\"3523\">7</sup> לקונה<sup data-n=\"3524\">8</sup> מתפלותיהן של ישראל והו\"ע העטרה שע\"ג הראש, והיינו שנמשך רצון חדש וממילא נהפך הרצונות פרטים ולכן יש בכח התפלה להפך הגזירה שנגזר ח\"ו, הגם דאותיות הם דומם אך שרש הדומם הוא גבוה<sup data-n=\"3525\">9</sup> במדרי' יותר, (דשרש הדומם הוא נגד מדבר<sup data-n=\"3526\">10</sup>, וידוע דמדבר הוא בכתר<sup data-n=\"3527\">11</sup> דבר בחכ' ומדבר בכתר, וזהו דשרש המל' ברדל\"א<sup data-n=\"3528\">12</sup> ) אך צ\"ל מפני מה גבוה מעלות התפלה כ\"כ שמהפך כל הרצונות.\n<b>והענין</b> דהנה כתיב לב מלכים אין חקר<sup data-n=\"3529\">13</sup> וכשהדיוט צריך שיפנה לב המלך לבקשתו מביא לו דבר חדש היינו ציפור המדברת<sup data-n=\"3530\">14</sup> ולזה נפנה לב המלך וממילא נפנה לבקשתו ג\"כ, הגם שהאדם מדבר בטוב יותר מהציפור ומדבר בשכל והציפור אין שישוב<sup data-n=\"3531\">15</sup> לשאלו דבר מה שלא למדו אותו ואפי' כשמדבר דבר שיש בו שכל ה\"ה אינו יודע השכל והאדם מדבר בשכל, מ\"מ אין זה דבר חדש דמי ידבר אם לא האדם שה\"ה מדבר, אך הציפור היא בעצם חי ר\"ל שעצם מעלתו הוא מה שהוא חי וכשעושין בו מעלה יתירה מה שאין בו בעצם זהו דבר ולזה יפנה לב המלך, וכמו\"כ למעלה הגם דמלאכי' בטלים בתכלית לאלקות דיש מלאכים שאמרו קדוש פ\"א ועמדו ב' אלפים שנה בביטול כו' ועתה הם עומדים בהביטול דקדוש דפעם ג'<sup data-n=\"3532\">16</sup>, אך מי יהי' בטל אם לא מלאך א' דכלום יצה\"ר יש בהם<sup data-n=\"3533\">17</sup> ועוד הגם שיש להם גוף<sup data-n=\"3534\">18</sup> ה\"ה מב' יסודות הדקים וכמ\"ש עושה מלאכיו רוחות<sup data-n=\"3535\">19</sup> משרתיו אש לוהט אבל נשמה שירדה למטה בגוף ונה\"ב המעלים ומסתיר ומ\"מ הוא בטל לאלקות זהו דבר חדש ולכן ע\"י תפילה ממשיכים רצון חדש, ולכן ממשיכי' ע\"י התפלה בחי' טעמי תורה",[["3523","7","<b>מט\"ט קושר כתרים</b>: ראה זהר בראשית לז, ב. סה\"מ תש\"ח ע' 202 בהערה."],["3524","8","<b>לקונה</b>: אוצ\"ל: לקונו."],["3525","9","<b>שרש הדומם הוא גבוה</b>: ראה לקו\"ת ברכה צט, א. ד."],["3526","10","<b>הדומם. . המדבר</b>: ראה גם תו\"א בראשית ד, א. תו\"ח שם כא, א ואילך. לקו\"ת שבהערה הבאה."],["3527","11","<b>דמדבר הוא בכתר</b>: ראה תו\"א יתרו קט, א. לקו\"ת חוקת נח, א."],["3528","12","<b>דשרש המל' ברדל\"א</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ב. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ד הערה 64."],["3529","13","<b>לב מלכים אין חקר</b>: משלי כה, ג [ושם: ולב]."],["3530","14","<b>צפור המדברת</b>: מובא בלקו\"ת במדבר כ, א: וכמ\"ש בלק\"א בשם המגיד נ\"ע. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רפח. תו\"ח וישלח קצ, א ובהערה 5. פלח הרמון ויקרא ע' קטו. וש\"נ[ednref_208_א]."],["3531","15","<b>אין שישוב</b>: אוצ\"ל: אין שייך שישיב."],["3532","16","<b>דיש מלאכי' שאמרו קדוש. . דפעם ג'</b>: ראה גם לעיל הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 24."],["3533","17","<b>דכלום יצה\"ר יש בהם</b>: ע\"פ שבת פט, א."],["3534","18","<b>שיש להם גוף</b>: ראה תו\"א בראשית ד, ב. לקו\"ת בהר מא, ב. מאמרי אדה\"א בראשית ע' קיב. וש\"נ. קונטרסים ע' רצב (ושם: אמ\"ר). וש\"נ. שע\"ת ו, ב. סה\"מ תרל\"ח ע' סד. וש\"נ. לקמן הנחה ד\"ה הנה אנכי כורת ברית על יד הערה 14. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה וכל שיח השדה על יד הערה 44. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כנשר יעיר קנו על יד הערה 40. ד\"ה וכל שיח השדה על יד הערה 56. (בחלק ההנחות) הנחה ד\"ה כנשר יעיר קנו על יד הערה 49."],["3535","19","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד.\n\n[edn_208_א] <b>ובהערה שם נדפס תרל\"ג ח\"ב ע' תקיד. וצ\"ל</b>: ע' תקיב."]]],[2000470402,"דהנה הטעמים הם ע\"ג האותיות וה\"ה ג\"כ בחי' עטרה ע\"ג הראש (צ\"ע הלא נת\"ל<sup data-n=\"3536\">20</sup> שהעטרה ע\"ג הראש הם התגין, ומה שממשיכים עי\"ז בחי' טעמים יובן בלא זה שהרי הטעמים הם בכתר) וע\"י תפילה ממשיכים יהי' רצון שהוא ג\"כ בחי' עטרה ע\"ג הראש (שהוא בחי' כתר כנ\"ל) וא\"כ ממשיכים ע\"י תפלה בחי' טעמי תורה.\n<b>וזהו</b> שבתושבע\"פ לא יש פי' וביאור על טעמי תורה<sup data-n=\"3537\">21</sup> דרובו של תושבע\"פ הוא על האותיות של תושב\"כ כמו מס' שבת בתושב\"כ הוא בקיצור נמרץ<sup data-n=\"3538\">22</sup> ובתושבע\"פ נעשה מזה כל מס' שבת ומס' עירובין ששייך ג\"כ לשבת וכן סוכה מפסוק בסכת תשבו<sup data-n=\"3539\">23</sup> וכמו מ\"ט דר\"מ אמר קרא<sup data-n=\"3540\">24</sup>, וכן יש ביאור על תגין וכמ\"ש קוצותיו תלתלים ואמרז\"ל שר\"ע הי' דורש על כל קוץ וקוץ תילי תילים של הלכות<sup data-n=\"3541\">25</sup>, וכן נקודות יש אם למקרא יש אם למסורת<sup data-n=\"3542\">26</sup> ואפי' נקודות שאינם נוגעים להאותיות דורשין ג\"כ כמו למה נקוד על איה<sup data-n=\"3543\">27</sup>, אבל על טעמים לא יש פי' וביאור, והוא מפני שתורה הוא השגה והבנה וטעמי תורה הם למעלה מהשגה לכן אינו שייך שיהי' ע\"ז פי' וביאור בתושבע\"פ, הגם שנת' במ\"א דטעמים בחכ' ונקודות בינה ותגין ז\"א ואותיות מל'<sup data-n=\"3544\">28</sup>, הנה יש ב' בחי' אותיות אותיות דע\"מ הם במל' בדבר ה' שמים נעשו<sup data-n=\"3545\">30</sup> ואותיות התורה ואותיות התפילה הם בז\"א<sup data-n=\"3546\">29</sup>. דהנה תפילה הוא ג\"כ ואני תפלה<sup data-n=\"3547\">31</sup> שהוא התקשרות לא\"ס עצומ\"ה.\n<b>וביאור</b> הענין דהנה אמרז\"ל א\"ל הקב\"ה למשה דוד<sup data-n=\"3548\">32</sup> זמירות קרית<sup data-n=\"3549\">33</sup> לי<sup data-n=\"3550\">34</sup> הריני מכשילך בדבר שתינוקות של בית רבן יודעין אותו כתי' לבני קהת לא נתן",[["3536","20","<b>נת\"ל</b>: לעיל הנחה ד\"ה ישקני מנשיקות פיהו על יד הערה 60 ואילך."],["3537","21","<b>שבתושבע\"פ. . על טעמי תורה</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' קה. ח\"ד ע' א'תע. ובהנסמן בהנ\"ל. שמות ח\"א ע' לב וע' ע."],["3538","22","<b>שמס' שבת. . בקיצור נמרץ</b>: ראה גם אוה\"ת וארא כאן ע' ב'תקעה. סה\"מ תרל\"ח ע' קנו. לעיל (בחלק המאמרים) בההמשך כאן רפכ\"ב על יד הערה 611."],["3539","23","<b>סוכה מפסוק בסכת תשבו</b>: אמור כג, מב. מ. ראה גם לעיל הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 68."],["3540","24","<b>מ\"ט דר\"מ אמר קרא</b>: כתובות מ, ב. ועוד."],["3541","25","<b>קוצותיו תלתלים. . הלכות</b>: שה\"ש ה, יא. ראה ערובין כא, סע\"ב. מנחות כט, ב. לעיל (בחלק המאמרים) בההמשך כאן רפכ\"ב ובהערה 614."],["3542","26","<b>יש אם למקרא. . למסורת</b>: קדושין יח, ב."],["3543","27","<b>למה נקוד על איה</b>: ב\"מ פז, א."],["3544","28","<b>דטעמים בחכ'. . ואותיות מל'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. לקו\"ת חוקת נז, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' א'יט. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן פכ\"ב ובהערה 622."],["3545","30","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["3546","29","<b>אותיות דע\"מ הם במל'. . בז\"א</b>: ראה גם לעיל הנחה ד\"ה ישקני מנשיקות פיהו על יד הערה 56."],["3547","31","<b>ואני תפלה</b>: תהלים קט, ד. ראה גם סה\"מ תרכ\"ז ע' עב."],["3548","32","<b>א\"ל הקב\"ה למשה דוד</b>: בסוטה לה, א במד\"ר פ\"ד, כ תנחומא פינחס ח: אמר לו הקב\"ה. בילקוט המכירי תהלים קיט, יז: א\"ל הקב\"ה לדוד."],["3549","33","<b>דוד זמירות קרית</b>: ע\"פ אגה\"ק ד\"ה זה. (תניא קס, א). הובא גם בשם רז\"ל בסה\"מ תרכ\"ז ע' מד [ושם: בסוטה דל\"ה סע\"א) ע' רצה ע' תסד תרכ\"ח ע' קעא תרכ\"ט ע' תה[ednref_209_ב] תרל\"ב ח\"א ע' קעד. תרל\"ג ח\"ב ע' תקנד. תרל\"ד ע' מב. ראה בהערה שלפנ\"ז."],["3550","34","<b>לי</b>: אוצ\"ל: לי' להו.\n\n[edn_209_ב] <b>ושם</b>: דל\"ה ע\"ב — וכנראה שצ\"ל כמו בסה\"מ תרכ\"ז: ע\"א."]]],[2000470403,"כי עבודת הקודש עליהן בכתף ישאו<sup data-n=\"3551\">35</sup> והוא נשא את הארון בעגלה<sup data-n=\"3552\">36</sup> וצ\"ל מה הי' החטא של דוד שנענש<sup data-n=\"3553\">37</sup> ע\"ז ולמה נענש דוקא בשכחה, ובזה דוקא ששכח לישא את הארון בכתף ונשאו בעגלות, והענין דדוד שיבח את התורה במה שכל חיות העולמות תלוי בתורה דהנה תפילין הם המשכה<sup data-n=\"3554\">38</sup> מלמעלמ\"ט ואם יארע פסול בהתפילין בטל כל ההמשכה וכן קרבן הוא העלאה<sup data-n=\"3555\">39</sup> מלמטלמ\"ע אימתי כשהוא כתיקונה אבל כשיחשוב הכהן<sup data-n=\"3556\">40</sup> איזה מחשבת חוץ<sup data-n=\"3557\">41</sup> בטל כל ההמשכה והעלאה, והמשכה זהו חיות כל העולמות, ודוד שהי' צר לו מאד בגשמיות הי' משתעשע מאחר שכל חיות כללות העולמות תלוי בתורה והוא לומד תורה וא\"כ אינו תופס מקום כל עניני גשמיות, וזהו שהי' מעדן עצמו כתולעת<sup data-n=\"3558\">42</sup> בעת שלמד תורה שהרגיש התענוג שיש בתורה ולא הי' תופס מקום אצלו כל התענוגי העוה\"ז, אך הנה בחי' זו הוא בחי' חיצוניות שבתורה אך הנה יש עוד בחי' פנימיות התורה שעלי' נא' לא ידעה<sup data-n=\"3559\">43</sup> אלקים הבין דרכה<sup data-n=\"3560\">44</sup> פי' כשמשיגים נו\"ן שערי בינה<sup data-n=\"3561\">45</sup> אז יכולים להבין הדרך של תורה, וכתי' ואהי' אצלו אמון<sup data-n=\"3562\">46</sup> אצלו דוקא ועל ל' הקבלה הוא שעשועי המלך בעצמותו<sup data-n=\"3563\">47</sup> שלגבי בחי' זו כל בחי' חיצוניות התורה שחיות העולמות תלוי בה אינו תופס מקום כלל, ומפני ששיבח את התורה בחיצוניות לכן נפל בשכחה שהוא מאחוריים וחיצוניות והוא מדה נגד מדה<sup data-n=\"3564\">48</sup>, והעיקר הי' ששכח לישא את הארון ונשאו בעגלות דהנה על הארון<sup data-n=\"3565\">49</sup> כתי' כתובים משני עבריהם<sup data-n=\"3566\">50</sup> מזה ומזה הם כתובים ואי' בירושלמי שהיו כתובים מכל צדדיהן<sup data-n=\"3567\">51</sup> ולא הי' בחי' אחור כלל לכן צריכים לשאת אותם בכתף כדי לחברם באחורים ולא יהי' שכחה, אך העונש שלו הי' צ\"ל שיפול בשכחה מדה כנגד מדה ואם לא הי' שוכח לשאת את הארון בעגלה לא הי' נופל בשכחה לכן שכח לשאת את הארון בכתף ונשאו בעגלה. ובעבודה ענין השכחה",[["3551","35","<b>לבני קהת לא נתן. . עליהן בכתף ישאו</b>: נשא ז, ט [ושם: ולבני. עליהם]. ראה גם לעיל הנחה ד\"ה ישקני מנשיקות פיהו הערה 37."],["3552","36","<b>נשא את הארון בעגלה</b>: שמואל-א ו, ג."],["3553","37","<b>דוד שנענש</b>: ראה בהבא לקמן לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח רפכ\"א. וש\"נ. לעיל הנחה ד\"ה ישקני מנשיקות פיהו על יד הערה 45."],["3554","38","<b>תפילין הם המשכה</b>: ראה תו\"א יתרו עא, ב. מאמרי אדה\"ז תקס\"ט ע' קסא. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ושאבתם מים פ\"א (ובהערה 10. (בחלק ההנחות) הנחה הנ\"ל על יד הערה 39."],["3555","39","<b>קרבן הוא העלאה</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 92."],["3556","40","<b>כשיחשוב הכהן</b>: ראה רמב\"ם הל' פסולי המוקדשין רפי\"ד."],["3557","41","<b>איזה מחשבת חוץ</b>: ראה רמב\"ם שם רפי\"ג. לעיל הנחה ד\"ה ישקני מנשיקות פיהו על יד הערה 41. סה\"מ תר\"ל ס\"ע שטו. תרל\"ב ח\"א ע' קנב. תרל\"ד ע' מב. תער\"ב ח\"א ע' שנב."],["3558","42","<b>ודוד. . מעדן עצמו כתולעת</b>: ראה מוע\"ק טז, ב."],["3559","43","<b>לא ידעה</b>: איוב כח, יג [ושם: לא ידע אנוש ערכה]."],["3560","44","<b>אלקי' הבין דרכה</b>: איוב שם, כג."],["3561","45","<b>נו\"ן שערי בינה</b>: ר\"ה כא, ב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה נעשה אדם פ\"ב ובהערה 17."],["3562","46","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["3563","47","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. וש\"נ."],["3564","48","<b>מדה נגד מדה</b>: ראה שבת קה, ב. סוטה ח, ב."],["3565","49","<b>הארון</b>: אוצ\"ל: הלוחות."],["3566","50","<b>כתובים משני עבריהם</b>: תשא לב, טז."],["3567","51","<b>כתובים מכל צדדיהן</b>: ראה ירושלמי שקלים פ\"ו, סה\"א. ראה גם סהמ\"צ להצ\"צ ע' 80 ואילך."]]],[2000470404,"הוא מ\"ש לא תשכח<sup data-n=\"3568\">52</sup> דהנה עמלק פעל קרירות<sup data-n=\"3569\">53</sup> בנש\"י ויש בזה כמה מדרי' יש שהקרירות כ\"כ עד שאינו עושה כלל ויש שהקרירות הוא רק שעושה את המצוה דרך מצות אנשים מלומדה, והנה מהקרירות אפשר שיפול בשכחה שישכח לגמרי דהנה כל נשמה היא חלק אלוקה ממעל ממש<sup data-n=\"3570\">54</sup> אך כששוכח הרי בטל לגמרי וזהו שמזהירין לא תשכח ולא די במה שא' זכור<sup data-n=\"3571\">55</sup> אמר עוד לא תשכח שלא יפול בשכחה.\n<b>והנה</b> מובן מכל הנ\"ל שיש ב' מדרי' בתורה, והנה אותיות דע\"מ הם במל' ואותיות (דחיצוניות) התורה הם בז\"א, ומאחר שאותיות הם בז\"א הנה טעמים בכתר<sup data-n=\"3572\">56</sup>, הגם שנת' במ\"א שטעמים בחכ' אך בטעמים יש ג\"כ ב' מדרי' א' טעם הגלוי היינו שמושג ומובן הטעם והוא חכ' דאצי' ב' טעם הכמוס<sup data-n=\"3573\">57</sup> ונק' סדכ\"ס<sup data-n=\"3574\">58</sup> דסתימין הם או\"א<sup data-n=\"3575\">59</sup> וזה סתים גם מסתימין וכמו רעווא ורעדכ\"ר<sup data-n=\"3576\">60</sup> רזא ורזא דרזין<sup data-n=\"3577\">61</sup>, וזהו\"ע שתוק כך עלה במח'<sup data-n=\"3578\">62</sup> שאינו עקשות ח\"ו אלא יש בזה טעם אלא שאינו מושג וזהו שטעמים הם בכתר. והנה ג' מדרי' נקודות תגין אותיות הם בחי' אירוסין וטעמים הוא בחי' נישואין, והנה אירוסין יש בזה תנאים וזהו לחם עני לחם עני כתי'<sup data-n=\"3579\">63</sup> דהנה יצ\"מ הי' בחיפזון וכמ\"ש כי בחיפזון יצאת<sup data-n=\"3580\">64</sup> מארץ מצרים אבל לע\"ל כי בחיפזון לא תלכו<sup data-n=\"3581\">65</sup> ובמנוסה לא תלכון כי הולך לפניכם ה' דוה' הוא וב\"ד<sup data-n=\"3582\">66</sup> ולכן יש בזה תנאים אם בחוקתי תלכו<sup data-n=\"3583\">67</sup> כו' וא\"ל כו' אבל בנישואין לא יש שום תנאי, וענין החיפזון שהי' במצרים הוא דהנה במצרים כתי' כי ברח העם<sup data-n=\"3584\">68</sup> היינו שברחו מהרע",[["3568","52","<b>לא תשכח</b>: תצא כה, יט."],["3569","53","<b>עמלק פעל קרירות</b>: תצא כה, יח. ראה רש\"י ילקוט שמעוני ולק\"ט שם. פס\"ר ופסדר\"כ פ' זכור. תנחומא תצא ט. לקו\"ת שמ\"ע פז, ג. אוה\"ת פ' זכור ס\"ע א'תשצה ואילך. חוקת ס\"ע תשפב. סה\"מ תרל\"ב ח\"א ע' קיט. המשך מים רבים תרל\"ו פקי\"ט. סה\"מ תש\"ט ע' 40 (הב'). שיחת שבה\"ש תרצ\"ב (נדפס ברשימות חוברת ז' ע' 52)."],["3570","54","<b>חלק אלוקה ממעל ממש</b>: ראה איוב לא, ב. תניא רפ\"ב. סידור ר' יעקב קאפיל בהקדמת הכותב ע' ג. מאמרי אדה\"א ויקרא ח\"ב ע' שעג. וש\"נ. תו\"ח וארא ח\"א נא, ד. וש\"נ. סה\"ש תש\"נ ע' 381."],["3571","55","<b>שא' זכור</b>: תצא כה, יז."],["3572","56","<b>טעמים בכתר</b>: ראה פרדס שער הטעמים שכ\"ט, פ\"ה. שיעור קומה — להנ\"ל — מערכת טעמים ספ\"ז. ע\"ח שער טנת\"א ש\"ה, פ\"ה. שער העקודים ש\"ו, פ\"ב (מ\"ב). מאו\"א מערכת טעמים סי\"ח. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פכ\"א."],["3573","57","<b>טעם הכמוס</b>: ראה ביאוה\"ז נשא פח, ב ואילך."],["3574","58","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["3575","59","<b>דסתימין הם או\"א</b>: ראה ת\"ז ת\"י (כה, ב)."],["3576","60","<b>ורעדכ\"ר</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. תו\"ח בראשית לו, ג הערה 23. תצוה ח\"ב שעו, ג."],["3577","61","<b>ורזא דרזין</b>: לשון הזהר בכ\"מ. ראה זהר בראשית מה, ב."],["3578","62","<b>שתוק כך עלה במח'</b>: מנחות כט, ב. ראה ביאוה\"ז שם. לקו\"ת בחוקתי מו, ג. שלח מח, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תתטז. וש\"נ. סה\"מ תרכ\"ט ע' רנג. וש\"נ. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה וזהו שרש ענין יונתי על יד הערה 72."],["3579","63","<b>לחם עני לחם עני כתי'</b>: כנראה שהעיין (הב') נקוד קמץ — פ' ראה טז, ג. פסחים קטו, סע\"ב."],["3580","64","<b>כי בחפזון יצאת</b>: פ' ראה שם."],["3581","65","<b>כי בחפזון לא תלכו</b>: ישעי' נב, יב [ושם: לא בחפזון תצאו]."],["3582","66","<b>דוה' הוא וב\"ד</b>: (בשלח יג, כא). וירא יט, כד. ב\"ר פנ\"א, ב. ירושלמי ברכות פ\"ט, ה\"ה."],["3583","67","<b>אם בחוקתי תלכו</b>: בחוקותי כו, ג."],["3584","68","<b>כי ברח העם</b>: בשלח יד, ה. ראה תניא פל\"א."]]],[2000470405,"שהרע הי' עדיין בתוקף ולכן הי' החיפזון לברוח מן הרע אבל לע\"ל כתי' ואת רוח הטומאה אעביר מן הארץ<sup data-n=\"3585\">69</sup> לכן כי בחיפזון לא תצאו כו', ובד\"כ יצ\"מ הי' משם אלקים<sup data-n=\"3586\">70</sup> ולכן הי' בלילה<sup data-n=\"3587\">71</sup> והו\"ע סיהרא לית לה מגרמה כלום<sup data-n=\"3588\">72</sup> אבל לע\"ל כתי' והי' לעת ערב יהי' אור<sup data-n=\"3589\">73</sup>, וזהו שלע\"ל יתגלה בחי' טעמי תורה והו\"ע נישואין.\n<b>והנה</b> עפ\"ז יובן מ\"ש ואתה תצוה כו' דהנה כל מה שנת\"ל בענין העלאות הנרות<sup data-n=\"3590\">74</sup>, נר הוא הנשמה וכמ\"ש נר הוי' נשמת אדם<sup data-n=\"3591\">75</sup> צריכים להעלאות הנשמות הנה הוא עבודת אהרן שהי' מעלה נש\"י מלמטלמ\"ע אבל עבודת משה הי' להמשיך המשכת מ\"ד<sup data-n=\"3592\">76</sup> מלמעלמ\"ט וזהו שמשה הוא שושבינא דמלכא<sup data-n=\"3593\">77</sup> מתניתא מלכתא<sup data-n=\"3594\">78</sup> כמו מלך שגוזר אומר שע\"י תורה ממשיכים מלמטלמ\"ע<sup data-n=\"3595\">79</sup>, הגם שהמצות גבהה מעלתם על מעלת התורה דתורה הוא בחי' שערות [וכמ\"ש קוצותיו תלתלים ] ומצות הם תרי\"ג ארחין דגוגלתא<sup data-n=\"3596\">80</sup>, אך למטה התורה למעלה מהמצות שהמצות נתלבשו בדברים גשמים אבל תורה אפי' למטה היא ג\"כ חכ', וזהו שביקש אעברה נא ואראה<sup data-n=\"3597\">81</sup> את הארץ שרצה להמשיך בארץ ג\"כ מלמעלמ\"ט ולא יהיו צריכים להעלאה מלמטלמ\"ע, וזהו שכתי' כאן תמיד ואח\"כ כתי' מערב ועד בקר דהנה בבי\"ע יש שינוים ויוכל להפסק אבל באצי' דאיהו וחיוהי חד<sup data-n=\"3598\">82</sup> אינו שייך שם שום הפסק, ועוד י\"ל מעלות התורה על המצות, דהנה מצות הם דוקא בזמן כמו מצה שממשיכים קטנות אבא<sup data-n=\"3599\">83</sup> ה\"ז דוקא בפסח אבל בשאר השנה אינו ממשיך כלום, וכמו\"כ שבת מוחין דאבא יו\"ט מוחין דאימא<sup data-n=\"3600\">84</sup> סוכות מקיפים",[["3585","69","<b>ואת רוח הטומאה. . הארץ</b>: זכרי' יג, ב."],["3586","70","<b>יצי\"מ הי' משם אלקים</b>: ראה מדרש שבהערה הבאה. לעיל הערה 66."],["3587","71","<b>יצי\"מ. . הי' בלילה</b>: לעיל (בחלק המאמרים) בההמשך כאן ספכ\"ב (והוא לשון האוה\"ת כאן): ”נמשך יציאתם בבחי' לילה ע' במד\"ר בא ספי\"ט\", ו. וראה גם תו\"ח בא ח\"א קטו, ב ובהנסמן שם. סה\"מ תרס\"ג ח\"ב ע' קמה בשולי היריעה (באותיות המחשבה)."],["3588","72","<b>סיהרא לית לה מגרמה כלום</b>: ראה זהר בראשית לג, ב. תולדות קלה, סע\"ב. ויחי רלו, ב. רמט, ב. ויקהל רטו, א. בחוקותי קיג, ב. מאמרי אדה\"ז הקצרים ע' שפג."],["3589","73","<b>והי' לעת ערב יהי' אור</b>: זכרי' יד, ז."],["3590","74","<b>משנת\"ל בענין העלאות הנרות</b>: ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"י. פי\"א."],["3591","75","<b>נר הוי' נשמת אדם</b>: משלי כ, כז. ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ד ואילך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא'."],["3592","76","<b>מ\"ד</b>: ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן פכ\"ג הערה 647."],["3593","77","<b>שמשה הוא שושבינא דמלכא</b>: ראה זהר רע\"מ ויקרא כ, א. מצורע נג, ב. רע\"מ שופטים ערה, ב. תו\"ח שמות ח\"א יא, ג הערה 510."],["3594","78","<b>מתניתא מלכתא</b>: כתובות סא, ב."],["3595","79","<b>מלמטלמ\"ע</b>: אוצ\"ל: מלמעלמ\"ט."],["3596","80","<b>דתורה. . שערות. . ומצות. . ארחין דגולגלתא</b>: ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א פיסקא וביאור הענין."],["3597","81","<b>אעברה נא ואראה</b>: ואתחנן ג, כה. ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרסח ואילך. תקס\"ד ע' רא ואילך וע' רד. לקו\"ת ואתחנן ג, ג-ד. שע\"ת קד, ב ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' רעא."],["3598","82","<b>דאיהו וחיוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["3599","83","<b>מצה. . קטנות אבא</b>: ראה סידור סדר הגדה חצר, סע\"א ואילך. תו\"ח בא ח\"א צד, ד הערה 393."],["3600","84","<b>שבת מוחין דאבא יו\"ט מוחין דאימא</b>: ראה פע\"ח שער מקראי קדש ש\"כ, פ\"א. לקו\"ת צו יא, ד. בחוקותי מז, ג. שע\"ת צח, ב (בשם הע\"ח). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מד. סה\"מ תרכ\"ז ע' תפט. וש\"נ."]]],[2000470406,"דבינה<sup data-n=\"3601\">85</sup> הכל בזמן דוקא, ואי' ברשב\"א שהמצות תלוים בג' דברי'<sup data-n=\"3602\">86</sup> זמן ומקום וכלים היינו כלי המקדש, אבל תורה כל העוסק בתורת עולה<sup data-n=\"3603\">87</sup> כאילו הקריב עולה הגם שאין עכשיו בהמ\"ק וכן הלומד הלכות פסח בסוכות ממשיך המשכות אוא\"ס<sup data-n=\"3604\">88</sup>, וזהו שכתי' כאן נר תמיד שהתורה אינו תלוי בזמן אבל המצות הם תלוים בזמן לכן מערב ועד בקר, וזהו ואתה הקרב אליך<sup data-n=\"3605\">89</sup> את אהרן אחיך, דהנה והו\"ע<sup data-n=\"3606\">90</sup> העלאה באצי' וע\"ד רוצה ה' את יריאיו<sup data-n=\"3607\">91</sup> דאהרן הוא יר\"ע<sup data-n=\"3608\">92</sup>, וכשנתעלה מבי\"ע לאצי' נעשה ג\"כ כמו באצי' וזהו מערב עד בקר והוא הזמן שצריכים לנר וביום אינו צריכים לנר אך מ\"מ אינו תמיד, ומפני מה יש כח זה באהרן זהו שכ' מאת בנ\"י<sup data-n=\"3609\">93</sup> את הם אותיות מאל\"ף ועד תי\"ו והו\"ע אותיות התורה וישראל נותנין הכח שיתעלה ע\"י האותיות, ובאותיות יש ב' מדרי' אתוון דוכרין ואתוון נוקבין<sup data-n=\"3610\">94</sup>, וזהו ואתה תצוה, תצוה הוא ל' צוותא<sup data-n=\"3611\">95</sup> וחיבור והו\"ע ההמשכה מלמעלמ\"ט וסדר ההמשכה ויקחו אליך שתחילה צריכים להמשיך המשכת מ\"ד באצי' ואח\"כ יומשך למטה ג\"כ וזהו ע\"י כח התורה ודוקא דיבור התורה וכמ\"ש ודברת בם<sup data-n=\"3612\">96</sup> (עי\"ל ודברת ל' הנהגה<sup data-n=\"3613\">97</sup> ) מפני שתורה היא למעלה ממקום וזמן.",[["3601","85","<b>סוכות מקיפים דבינה</b>: ראה ביאוה\"ז אמור פ, ב. הנסמן בתו\"ח בא ח\"א קיד, א. מאמרי אדה\"א דברים ח\"ד ע' א'שנו ובהנסמן שם. סה\"מ תרכ\"ז ע' תכא. וש\"נ. לקמן מאמר ד\"ה להבין שרש ענין מקיפים דבינה."],["3602","86","<b>ברשב\"א שהמצות תלוים בג' דברי'</b>: ראה לעיל (בחלק המאמרים) בההמשך כאן פכ\"ג ובהערה 658."],["3603","87","<b>כל העוסק בתורת עולה</b>: ראה מנחות קי, א. לקו\"ש מסעי כרך יח ע' 413. וש\"נ. ערב פסח כרך לב ע' 37. וש\"נ."],["3604","88","<b>הלומד הלכות פסח בסוכות ממשיך המשכות אוא\"ס</b>: ראה לעיל (בחלק המאמרים) בההמשך כאן ובהערה 660."],["3605","89","<b>ואתה הקרב אליך</b>: תצוה כח, א."],["3606","90","<b>והו\"ע</b>: תיבה זו איננו ברורה."],["3607","91","<b>רוצה ה' את יריאיו</b>: תהלים קמז, יא."],["3608","92","<b>דאהרן הוא יר\"ע</b>: ראה גם המשך מים רבים תרל\"ו פ\"נ שהוא בחי' מקור היראה. אוה\"ת תצוה כרך ז ע' ב'תשנו ס\"ו."],["3609","93","<b>מאת בנ\"י</b>: תצוה כז, כא."],["3610","94","<b>אתוון דוכרין ואתוון נוקבין</b>: ראה ס\"י פ\"ג, מ\"ה ואילך. זהר ויצא קנט, א. תו\"א בשלח סג, ד. סד, ג. מאמרי אדה\"א שמות ח\"א ע' רב. וש\"נ."],["3611","95","<b>תצוה הוא ל' צוותא</b>: ראה גם תו\"א תצוה כאן בהמאמר פב, א."],["3612","96","<b>ודברת בם</b>: ואתחנן ו, ז."],["3613","97","<b>ודברת ל' הנהגה</b>: ראה גם תו\"א בראשית א, סע\"א (הועתק בסה\"מ תרל\"ח ע' רכה). מאמרי אדה\"א בראשית ע' תיט. וש\"נ. תו\"ח פקודי ח\"ב תס, ב. וש\"נ."]]],[2000470407,"<h3>בן פורת יוסף</h3>\n<b></b><b>יום ד' פ' תצוה תר\"ם לפ\"ק על בר מצוה של אחי רמ\"מ שי'</b>\n<b></b>יום ד' פ' תצוה.. על בר מצוה של אחי רמ\"מ שי'\n<b>בן</b> פורת<sup data-n=\"3614\">1</sup> יוסף<sup data-n=\"3615\">2</sup>, ופי' בת\"א ברי דיסגי יוסף, וצ\"ל מה שייך דיסגי על יוסף. והענין דהנה כתי' אלה תולדות יעקב יוסף<sup data-n=\"3616\">3</sup> וצ\"ל שהו\"ל ראובן<sup data-n=\"3617\">4</sup> שהוא הבכור<sup data-n=\"3618\">5</sup> והו\"ל לכתוב כולם כסדרן ומהו אומרו רק יוסף. והענין הוא דהנה יעקב הי' בריח התיכון<sup data-n=\"3619\">6</sup> המבריח מן הקצה אל הקצה דהנה כתי' מקצה השמים ועד קצה השמים<sup data-n=\"3620\">7</sup> הרי יש בשמים קצה וקצה<sup data-n=\"3621\">8</sup> ויעקב הוא המחברם, דהנה כתי' אתה ה' לבדיך<sup data-n=\"3622\">9</sup> אתה עשית שמים וארץ, אתה ה' לבדיך הוא מה שא\"ס הוא מרומם ונשגב מגדר עולמות והוא לבדיך, אתה עשית כו' את חסר ה'<sup data-n=\"3623\">10</sup> שהוא בחי' מל' (וכמ\"ש דבר את עמנו ונשמעה<sup data-n=\"3624\">11</sup> אי'<sup data-n=\"3625\">12</sup> במדרש<sup data-n=\"3626\">13</sup> א\"ל משה התשתם את כוחי כנקבה) וכמ\"ש מל' מל' כל עולמים<sup data-n=\"3627\">14</sup> שכל הוא<sup data-n=\"3628\">15</sup> רק משם והארה בעלמא שאינו נוגע לעצמיות רק מלך שמו נקרא עליהם<sup data-n=\"3629\">16</sup> וזהו אתה עשית שמים וארץ שגם שמים הוא מבחי' מל', ובשמים זה יש קצה וקצה ואי' בזהר שהם בינה ויסוד ז\"א<sup data-n=\"3630\">17</sup> ובכהאריז\"ל אי' שהם עיגולים ויושר<sup data-n=\"3631\">18</sup>, והענין דהנה כתי' מלכותך מל' כל עולמים, מלכותך הוא מל' דא\"ס ומשם אפ\"ל מקור על עולמות דאתה ה' לבדיך אינו שורש שיהי' מקור אפי' לבחי' עיגולים שהוא בחי' עתיק בכלל רק מל' דא\"ס הוא שיהי' מקור על עיגולים (והנה ביושר שייך",[["3614","1","<b>בן פורת יוסף</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב. ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\nלמאמר זה ראה מאמר ד\"ה זה שנדפס באוה\"ת בראשית ח\"ב ע' שצה ואילך. שם ע' 770 ואילך. פלח הרמון ויחי קלו, ד. מאמרי אדה\"ז תקס\"ח ח\"ב ס\"ע תרעז ואילך. סה\"מ עזר\"ת ע' קיז ואילך.\nאודות תאריך יום הולדתו ראה בהכותרת כאן. (לעיל בחלק המאמרים) מאמר ד\"ה נעשה אדם ובהערה 1."],["3615","2","<b>בן פורת יוסף</b>: ויחי מט, כב."],["3616","3","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב."],["3617","4","<b>אלה תולדות. . ראובן</b>: ראה ב\"ר פפ\"ד, ו. אדר\"נ פ\"ב, ה."],["3618","5","<b>ראובן שהוא הבכור</b>: ויצא כט, לב. וישלח לה, כג. ויגש מו, ח. ויחי מט, ג. ועוד."],["3619","6","<b>יעקב הי' בריח התיכון</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["3620","7","<b>מקצה השמים ועד קצה השמים</b>: ואתחנן ד, לב [ושם: ולמקצה]. אבל כ\"ה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 5."],["3621","8","<b>יש בשמים קצה וקצה</b>: ראה זהר ויקהל ריא, סע\"א. אוה\"ת כאן ע' שצה. וש\"נ."],["3622","9","<b>אתה ה' לבדיך</b>: נחמי' ט, ו [בדילוג. ושם: השמים. הארץ]."],["3623","10","<b>אתה. . חסר ה'</b>: ראה מאמרי אדה\"ז תקס\"ח כאן ע' תרעח. אוה\"ת כאן ס\"ע 790. פלח הרמון כאן קלז, א. סה\"מ תרכ\"ז ע' פב וע' שצו. וש\"נ."],["3624","11","<b>דבר את עמנו ונשמעה</b>: יתרו כ, טז [ושם: אתה]. באוה\"ת כאן מביא: וע' בפרש\"י בחומש פ' ואתחנן ע\"פ [ה, כד] ואת תדבר אלינו. בפלח הרמון כאן מביא: ואם ככה את עושה לי [בהעלותך יא, טו]."],["3625","12","<b>אי'</b>: אוצ\"ל: ואי'."],["3626","13","<b>במדרש</b>: ראה רש\"י שבהערה 11."],["3627","14","<b>מל' מל' כל עולמים</b>: תהלים קמה, יג."],["3628","15","<b>שכל הוא</b>: אוצ\"ל: שכל הבריאה הוא."],["3629","16","<b>מלך שמו נק' עליהם</b>: ראה גם לעיל הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 16."],["3630","17","<b>קצה וקצה. . בינה ויסוד ז\"א</b>: ראה זהר ויקהל ריא, סע\"א ובמקדש מלך שם. אוה\"ת כאן ע' שצה."],["3631","18","<b>ובכהאריז\"ל אי' שהם עיגולים ויושר</b>: ראה גם אוה\"ת כאן (ע' 776) ע' שפט בהקיצור. פלח הרמון כאן קלו, ד. סה\"מ עזר\"ת כאן."]]],[2000470408,"מעלה ומטה) וזהו כל עולמים, כ\"ל בגימ' חמישים<sup data-n=\"3632\">19</sup> שאפי' נו\"ן אלפים יובלות<sup data-n=\"3633\">20</sup> הם מבחי' מל', (ויושר הוא הקו בכלל) והנה ביושר שייך מעלה ומטה, וזהו שיעקב הוא בריח התיכון המבריח מן הקצה אל הקצה שממשיך המשכות הקו מאוא\"ס וזהו יעקב ל' יבקע<sup data-n=\"3634\">21</sup> אז יבקע כשחר אורך<sup data-n=\"3635\">22</sup> דהנה עיגולים הוא העלם ונק' חושך כמ\"ש ישת חשך סתרו<sup data-n=\"3636\">23</sup> ובקיעת החושך הוא שממשיך המשכות הקו. וזהו היושבי בשמים<sup data-n=\"3637\">24</sup> לכאו' היו\"ד הוא מיותר וכמ\"ש יושב בשמים ישחק<sup data-n=\"3638\">25</sup>, אתה קדוש יושב<sup data-n=\"3639\">26</sup> תהלות ישראל ומה נא' כאן היושבי, אך הנה יו\"ד הוא ראשית הקו, וישיבה הו\"ע המשכה כמו שאומרים שהוא יושב עמהם שנמשך עמהם וזהו היושבי בשמים שממשיך מראשית הקו שיומשך בשמים. ולפי פי' הזהר שהוא בינה צ\"ל דהתגלות עתיק בבינה<sup data-n=\"3640\">27</sup> ובינה מקור המקיפים<sup data-n=\"3641\">28</sup> והוא ג\"כ בחי' עיגולים.\n<b>ובעבודה</b> הנה כתי' הקל קול יעקב<sup data-n=\"3642\">29</sup> קלא קדמאה חסר ו' קלא בתראה מלא ו' והוא קול של תורה וקול של תפלה, דהנה תפלה הוא העלאה מלמטלמ\"ע וזהו\"ע סולם<sup data-n=\"3643\">30</sup> מוצב ארצה<sup data-n=\"3644\">31</sup> וראשו מגיע השמימה (י\"ל ע\"ד מי יעלה לנו השמימה<sup data-n=\"3645\">32</sup> ) ולכן מתחילין בהודו ואח\"כ פסוד\"ז לזמר עריצים<sup data-n=\"3646\">33</sup> ואח\"כ ברכת",[["3632","19","<b>כ\"ל בגימ' חמישים</b>: ראה מאו\"א מערכת היכל אות יא. לקו\"ת מטות פה, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ד ע' כז ואילך."],["3633","20","<b>נו\"ן אלפים יובלות</b>: ראה ש\"ך ר\"פ בהר. שיחת שמחת ביה\"ש תרצ\"ב[ednref_210_א]. המלך במסיבו ח\"ב ע' רמ. מאמרי אדה\"א בראשית ע' רסו. וש\"נ. סה\"מ תרל\"ח ע' תלד. וש\"נ. לקמן הנחה ד\"ה וירא העם וינועו על יד הערה 78. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כנשר יעיר קנו על יד הערה 24. (בחלק ההנחות) בהנחה שם על יד הערה 28."],["3634","21","<b>יעקב ל' יבקע</b>: ראה ע\"ח שער הארת המוחין של\"ב, פ\"א. סה\"מ תש\"ט ע' 58. וש\"נ. תו\"ח וישלח קפה, ב הערה 17. אוה\"ת כאן ע' 778."],["3635","22","<b>אז יבקע כשחר אורך</b>: ישעי' נח, ח. ראה זהר אמור קד, א שיעקב אומר פסוק זה. הערה בתו\"ח ואוה\"ת שנסמן לפנ\"ז."],["3636","23","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["3637","24","<b>היושבי בשמים</b>: תהלים קכג, א. ראה זהר ואתחנן רסה, ב. אוה\"ת תהלים כרך ג ע' א'שלה. סה\"מ תרכ\"ז ע' קעד. תרכ\"ט ע' לו. סה\"מ עזר\"ת כאן ס\"ע קיט."],["3638","25","<b>יושב בשמים ישחק</b>: תהלים ב, ד."],["3639","26","<b>אתה קדוש יושב</b>: שם כב, ד [ושם: ואתה]."],["3640","27","<b>דהתגלות עתיק בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. תו\"ח לך פא, ב. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["3641","28","<b>ובינה מקור המקיפי'</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. לקו\"ת להאריז\"ל תהלים סנ\"ג."],["3642","29","<b>הקל קול יעקב</b>: תולדות כז, כב. ראה סידור שער התפלה יט, סע\"א ואילך. מאמרי אדה\"א בראשית ע' שמח. וש\"נ. תו\"ח מקץ רכז, ב ובהערות 32-4."],["3643","30","תפלה. . סולם ראה זח\"א בהשמטות רסו, ב. ח\"ג תוספת שו, ב. ת\"ז תמ\"ה פג, א."],["3644","31","<b>סולם מוצב ארצה</b>: ויצא כח, יב. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויאמר כו' לך לך על יד הערה 76 ואילך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויאמר כו' לך לך על יד הערה 97 ואילך."],["3645","32","<b>מי יעלה לנו השמימה</b>: נצבים ל, יב. ראה גם לקמן ח\"ב (בחלק המאמרים) שם ובהערה 91."],["3646","33","<b>פסדו\"ז לזמר עריצים</b>: ע\"פ ישעי' כה, ה. ראה זהר וילך רפד, א. לקו\"ת פקודי ח, א. בחוקותי מז, ד. מאמרי אדה\"ז תקע\"א ע' רצז. מאמרי אדה\"א דברים ח\"ב ע' תח ואילך. הנחות תקע\"ז ע' שדמ. וש\"נ. לקמן ח\"ב בהמאמר (על יד הערה 95 ואילך) ובהנחה (על יד הערה 119 ואילך) שבהערה 31.\n\n[edn_210_א] נדפסה ברשימות חוב' ז ע' 19 הערה ה."]]],[2000470409,"ק\"ש איך ששרפי' אומרים קדוש ואופנים אומרים ברוך<sup data-n=\"3647\">34</sup> ואח\"כ מס\"נ דק\"ש ואח\"כ תפלה והוא הכל העלאות מלמטלמ\"ע והו\"ע החבור מטומע\"ל וכמו יעקב שהי' בריח התיכון המבריח מן הקצה אל הקצה שהי' מחבר מעלה ומטה וגם חסד וגבו' כמו\"כ התפלה הוא החיבור מלמטלמ\"ע וכמ\"ש ואני תפלה<sup data-n=\"3648\">35</sup> ל' הטופל כלי חרס<sup data-n=\"3649\">36</sup> וכמ\"ש אלקים אל דמי לך ואל תחרש<sup data-n=\"3650\">37</sup>, למען יזמרך כבוד<sup data-n=\"3651\">38</sup> ולא ידום נהורא תתאה קארי תדיר<sup data-n=\"3652\">39</sup> לנהורא עילאה ולא שכיך, ותורה הוא המשכה מלמעלמ\"ט וזהו הקול בוא\"ו שהוא המשכה וא\"כ תורה ותפלה הם המחברי' מלמעלמ\"ט ומטלמ\"ע.\n<b>אך</b> הנה מה שיעקב הוא בריח התיכון המבריח מן הקצה אל הקצה הכל באצי' גופא אך כדי שיומשך לבי\"ע זהו דוקא ע\"י יוסף (ע' בבה\"ז<sup data-n=\"3653\">40</sup> על מאה\"ז ח\"א דרמ\"ט<sup data-n=\"3654\">41</sup> ע\"ב שפירא דיוסף דמי לשפורא דרחל) וכמ\"ש ויוסף הוא המשביר לכל עם הארץ<sup data-n=\"3655\">42</sup> שממשיך בארץ ג\"כ, ואזי<sup data-n=\"3656\">43</sup> שכל מה שנמשך בארץ מתוסף ריבוי ברכה ברבוי יותר, וכמו זריעה שזורעין גרעין אחד וממנו נצמח כמה וכמה וכמארז\"ל כלום אדם זורע כור<sup data-n=\"3657\">44</sup> להוציא ממנו כמה כורים וכמ\"ש ויזרע יצחק בארץ ההיא וימצא מאה שערים ויברכהו ה'<sup data-n=\"3658\">45</sup> וזהו הי' ברכה (לכאורה מיותר מ\"ש וזה הי' ברכה. ואפ\"ל כידוע שענין הברכה הוא להמשיך עד למטה מטה דאפשר שישאר למעלה באצי', והאבות עבודתם הי' ברוחניות ע' בתו\"ח בד\"ה ויאמר ה' אל אברם לך לך<sup data-n=\"3659\">46</sup>, א\"כ מה שנמשך למטה הוא ברכה שהוא ג\"כ כמו יוסף וצ\"ע) שניתוסף שלא בערך, והנה אנו רואין שהגרעין אין בו שום טעם וריח כלל וממנו נצמח האילן עם ענפים ופירות ועלים, וכמו\"כ הנה ארז\"ל זרע הקב\"ה התורה והמצות<sup data-n=\"3660\">47</sup> כדי להנחילן",[["3647","34","<b>ששרפי' אומרים קדוש ואופנים אומרים ברוך</b>: ראה גם (לקמן ח\"ב בהמאמר שבהערה 31 ובהנחה שם) לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ג. וש\"נ."],["3648","35","<b>ואני תפלה</b>: תהלים קט, ד."],["3649","36","<b>תפלה ל' הטופל כלי חרס</b>: כלים פ\"ג, מ\"ה. ראה לקמן הנחה ד\"ה גן נעול הב' על יד הערה 10. לקמן ח\"ב (בחלק ההנחות) הנחה ד\"ה שובה ישראל הב' על יד הערה 82. תו\"א תרומה עט, סע\"ד. סה\"מ תש\"ט ע' 79 (הב') בהערה. תרל\"ח ע' רמב. וש\"נ."],["3650","37","<b>אלקים אל דמי לך ואל תחרש</b>: תהלים פג, ב [ושם: אל תחרש — אבל כ\"ה גם לקמן הנחה ד\"ה אז ישיר משה על יד הערה 6]."],["3651","38","<b>למען יזמרך כבוד</b>: תהלים ל, יג."],["3652","39","<b>נהורא תתאה קארי תדיר</b>: ראה זהר היכלות פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב."],["3653","40","<b>בבה\"ז</b>: ויחי כט, ד. ולהצ\"צ שם ע' קסח ואילך (אוה\"ת ויחי כרך ה ע' תתקצד ואילך). וראה גם לקמן הנחה ד\"ה אי' וכו' נו\"כ על יד הערה 31. (בחלק ההנחות) בהנחה שם על יד הערה 27. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה עטרת תפארת שיבה ובהערה 35."],["3654","41","<b>דרמ\"ט</b>: אוצ\"ל: דרט\"ז."],["3655","42","<b>ויוסף הוא המשביר לכל עם הארץ</b>: מקץ מב, ו [בדילוג]."],["3656","43","<b>ואזי</b>: תיבה זו איננה ברורה."],["3657","44","<b>כלום אדם זורע כור</b>: ראה פסחים פז, ב. תו\"א בשלח סא, א. מאמרי אדה\"א דברים ח\"ד ע' א'תלד. תו\"ח שמות מ, ג ובהנסמן בהנ\"ל."],["3658","45","<b>ויזרע יצחק. . ויברכהו ה'</b>: תולדות כו, יב [בדילוג]."],["3659","46","<b>בתו\"ח. . לך לך</b>: פד, ג ואילך."],["3660","47","<b>זרע הקב\"ה התורה והמצות</b>: לעיל (בחלק המאמרים) בהמשך מצה זו על יד הערה 1822 מציין: במד\"ר ס\"פ שלח. וש\"נ. ראה גם לקמן הנחה ד\"ה הנה אנכי כורת ברית על יד הערה 38 ואילך. (בחלק ההנחות) בהנחה שם על יד הערה 34 ואילך. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אשריכם זורעי על כל מים על יד הערה 122."]]],[2000470410,"לישראל לעוה\"ב דע\"י מצות ממשיכים המשכות אלקות כמו ע\"י תפילין מוחין דאבא<sup data-n=\"3661\">48</sup> ואינם בערך כלל לגבי מוחין דאבא וכמו\"כ שבת הוא מוחין דאבא יו\"ט מוחין דאימא<sup data-n=\"3662\">49</sup> מצה קטנות אבא<sup data-n=\"3663\">50</sup> שהכל אינו בערך כלל, וזהו הציבה לך ציונים<sup data-n=\"3664\">51</sup> שהם רק ציון וסימן למצות של מעלה ומ\"מ ממשיכים ע\"י האורות העליונים וה\"ז כמו זריעה שהצמיחה מזה אינו בערך, והנה הצמיחה היא בארץ דוקא שאם לא יזרע בארץ היינו אלו יצוייר שיזרע בשמים לא יצמח כלל כ\"א דוקא בארץ דכח זה ניתן בארץ דוקא, וזהו ענין הפלוגתא ארץ קדמה או שמים<sup data-n=\"3665\">52</sup>, ולכאו' והלא השמים הוא רוחני יותר ומס' הוא קדם, אך מפני שיש יתרון המעלה בארץ על השמים היינו כח הצמיחה הוא בארץ דוקא. וכמו\"כ יובן בנמשל דהנה כתי' כי תהי' אתם ארץ חפץ<sup data-n=\"3666\">53</sup> היינו ארץ המוכשר לזריעה דדוקא ישראל כשמניח תפילין<sup data-n=\"3667\">54</sup> ממשיך מוחין דאבא אבל התפילין כשמונחים על השולחן הם תשמישי מצוה<sup data-n=\"3668\">55</sup> או כשמניחם<sup data-n=\"3669\">56</sup> מי שלא",[["3661","48","<b>תפילין מוחין דאבא</b>: ראה לקוטי הש\"ס מהאריז\"ל לברכות ו, א[ednref_211_ב] פע\"ח שער התפילין שער ד, פ\"ט שער הכוונות שם דרוש ו שו\"ע האריז\"ל הל' תפילין סי\"א מ\"ח מס' תיקון תפילין פט\"ו, מ\"א-ב: ממוחין דאמא. . רש\"י וממוחין[ednref_212_ג] דאבא. . ר\"ת. ראה גם מאמרי אדה\"ז תקס\"ו ריש ע' ריח. מאמרי אדה\"א בראשית ע' צט: במקיפי' דאבא. נ\"ך ס\"ע תקנח: ממקיפים דחו\"ב. המשך תער\"ב ח\"א ע' תצג."],["3662","49","<b>שבת. . דאבא יו\"ט מוחין דאימא</b>: ראה פע\"ח שער מקראי קדש ש\"כ, פ\"א. לקו\"ת צו יא, ד. בחוקותי מז, ג. שע\"ת צח, ב (בשם הע\"ח). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מד. סה\"מ תרכ\"ז ע' תפט. וש\"נ."],["3663","50","<b>מצה. . קטנות אבא</b>: ראה סידור סדר הגדה חצר, סע\"א ואילך. תו\"ח בא ח\"א צד, ד הערה 393."],["3664","51","<b>הציבה לך ציונים</b>: ירמי' לא, כ [ושם: הציבי]."],["3665","52","<b>הפלוגתא ארץ קדמה או שמים</b>: ראה חגיגה יב, א."],["3666","53","<b>כי תהי' אתם ארץ חפץ</b>: מלאכי ג, יב."],["3667","54","<b>דדוקא כשישראל מניח תפילין</b>: ראה תו\"א שמות נג, ד (ובהנסמן בריש המאמר שם). יתרו סח, ב. ע, ד. עב, ב. בהערות הבאות."],["3668","55","<b>התפילין. . תשמישי מצוה</b>: וכ\"ה בהמשך מים רבים תרל\"ו פצ\"ח ס\"ע קד.\nאבל לקמן ח\"ב (בחלק המאמרים) המשך יונתי פט\"ו (ובשני ההנחות שם) מאמר ד\"ה והנה כובע על יד הערה 97 (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה למה קדמה שמע לוהי' אם שמוע על יד הערה 33. ש\"א נו, א מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' סו סה\"מ תרכ\"ט ע' קמח תרל\"ב ח\"א ע' קעח ע' רח תרל\"ג ח\"א ע' נג ח\"ב ע' שמו ע' שעא ע' תג ס\"ע תקצט תרל\"ה ח\"ב ע' שסז: תשמישי[ednref_213_ד] קדושה[ednref_214_ה]. ראה שו\"ע אדה\"ז הל' תפילין סמ\"ב, ס\"ו."],["3669","56","<b>התפילין כשמונחים על השולחן. . או כשמניחם</b>: ראה גם מאמר ד\"ה הבאים ישרש תשמ\"ג נעתק בחלקו במ\"מ לתו\"א שם.\n\n[edn_211_ב] הועתק לשונו באוה\"ת ואתחנן ע' שלב סה\"מ תרכ\"ז ע' קיא [ושם בסופו: בשער הכללים מע\"ח. בלקוטי הש\"ס: בשער הכללים בע\"ח].\n\n[edn_212_ג] <b>בלקוטי הש\"ס שם</b>: הנה\"י.\n\n[edn_213_ד] הלשון תשמישי קדושה על תפילין — פע\"ח שער הציצית ש\"ג, פ\"ג בהגהה ג. פ\"ה בתוך ד\"ה מהחברים*. שער הכונות ענין הציצית דרוש ה. משנת חסידים מס' הנחת תפילין בסופה.\n\n[edn_214_ה] <b>בשיחת שבת פ' שלח ש\"מ תמוז תשי\"ב (תורת מנחם התועדויות כרך ו ע' 17)</b>: שהרי התפילין הם ”תשמישי קדושה\". וב”שיחות קודש\" (כרך ג ע' 322): ותפילין הם תשמישי קדושה (וגוף הקדושה). אמנם בשיחה המקורית נרשם: ותפילין הוא דבר שבקדושה (קדושה ליין).\nולהעיר שבדפו\"ר דהפע\"ח הנה הגהה ג וכן ד\"ה ”מהחברים\" ועד סיום הפרק ליתא שם."]]],[2000470411,"נצטווה עליהם<sup data-n=\"3670\">57</sup> אינו ממשיך כלום כ\"א ישראל דוקא ולכן זמן הנחת תפילין הם לי\"ג שנה ויום אחד<sup data-n=\"3671\">58</sup> שאז נעשה ישראל ובכוחו להמשיך מוחין דאבא שישראל הם ארץ חפץ ולכן בהם דוקא הזריעה, ועי\"ז אח\"כ הצמיחה שלא בערך, וזהו דוקא ע\"י יוסף שהוא הממשיך למטה. וזהו ואלה תולדות יעקב יוסף ר\"ל הגילוי של יעקב הוא יוסף דיעקב הוא מבריח מן הקצה אל הקצה אך כ\"ז באצי' וכדי שיומשך למטה זהו ע\"י יוסף (וזהו מ\"ש יוסף בן שבע עשרה שנה<sup data-n=\"3672\">60</sup> מספר טו\"ב<sup data-n=\"3673\">61</sup> שהוא<sup data-n=\"3674\">62</sup> יסוד<sup data-n=\"3675\">59</sup> השפעה למטה).\n<b>וזהו</b> בן פורת יוסף ברי דיסגי יוסף שהוא הממשיך למטה ועי\"ז ניתוסף ריבוי שלא בערך לכן ת\"א ברי דיסגי שמפרש פורת ל' פרי' ורבי'<sup data-n=\"3676\">63</sup>, וזהו ויקח משה את עצמות יוסף<sup data-n=\"3677\">64</sup> מפני שהי' צ\"ל מ\"ת למטה בארץ דוקא וזהו דוקא ע\"י יוסף כנ\"ל לכן לקח עצמות יוסף ר\"ל שהעצמיות של יוסף לקח וזהו פורת בגימ' ה' פעמים קול<sup data-n=\"3678\">65</sup> כמו שתורה ניתנה בה' קולות<sup data-n=\"3679\">66</sup>, וזהו מה שברך אותם וידגו לרב בקרב הארץ<sup data-n=\"3680\">67</sup>, וזהו בן פורת יוסף ברי דיסגי יוסף דהנה יעקב הוא בריח התיכון המבריח מן הקצה אל הקצה אך באצי' דוקא וכדי שיומשך למטה זהו ע\"י יוסף דוקא וזהו אלה תולדות יעקב יוסף שהגילוי של יעקב הוא הוא<sup data-n=\"3681\">68</sup> המשביר לכל עם הארץ ועי\"ז ניתוסף בריבוי כנ\"ל לכן ת\"א ברי דיסגי יוסף.",[["3670","57","<b>התפילין. . מי שלא נצטווה עליהם</b>: בהמשך מים רבים שם: מי שאינו מצווה כלל. בתו\"א שם סה\"מ תרכ\"ז ע' רפח תרל\"ב שם ע' קעח: עכו\"ם. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שכה. ש\"א צב, או ובהנסמן במ\"מ לשם. לקמן הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 165. (בחלק ההנחות) הנחה ד\"ה הנה אנכי כורת ברית סוף פיסקא וביאור הענין. וראה גם סה\"מ תרל\"ח ע' תיא: דוקא לאחר שיקבל עליו שם ישראל."],["3671","58","<b>לי\"ג שנה ויום אחד</b>: ראה שו\"ע אדה\"ז הל' תפילין סל\"ז, ס\"ג. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה נעשה אדם בסופו."],["3672","60","<b>יוסף בן שבע עשרה שנה</b>: המשך הכתוב אלה תולדות יעקב וישב לז, ב."],["3673","61","<b>שבע עשרה. . מספר טו\"ב</b>: ראה לקו\"ת להאריז\"ל ר\"פ וישב. מאמרי אדה\"א בראשית ע' רצד. שעה\"י קלד, ב ובהנסמן בהנ\"ל. אוה\"ת כאן ע' שצג."],["3674","62","<b>טו\"ב שהוא יסוד</b>: ראה זהר נח ס, א. מאמרי אדה\"א קונטרסים ע' רכד. וש\"נ."],["3675","59","<b>יוסף. . יסוד</b>: ראה זהר רע\"מ פינחס רלו, א. פרדס שעה\"כ שכ\"ג, פ\"י מערכת יוסף. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה עטרת תפארת שיבה ובהערה 42."],["3676","63","<b>פורת ל' פרי' ורבי'</b>: בנוסף לת\"א שהובא ברש\"י כאן. ראה אגדת בראשית פפ\"ב."],["3677","64","<b>ויקח משה את עצמות יוסף</b>: בשלח יג, יט. ראה גם אוה\"ת כאן ע' ת. בשלח כרך ז ע' ב'תרסג. פלח הרמון כאן ע' 274. סה\"מ עזר\"ת כאן ע' קכב."],["3678","65","<b>פורת בגימ' ה' פעמים קול</b>: בפלה\"ר כאן: פרת חסר וי\"ו. פע\"ח שער יוה\"כ שכ\"ז, פ\"ג. שער הכוונות ענין יוה\"כ פ\"א. מאו\"א מערכת פרת סל\"ו. אוה\"ת כאן ע' 800. ע' 822. יתרו ע' תתקנט. תרומה ס\"ע א'תפו. ע' א'תפז (פורת). סה\"מ עזר\"ת כאן.\nהשייכות דבן פורת לנהר פרת — ראה אוה\"ת כאן ע' שצא. ע' ת ואילך. ע' תט."],["3679","66","<b>שתורה ניתנה בה' קולות</b>: ברכות ו, ב. ראה גם לקוטי שיחות כרך ו' ע' 107 ואילך ובהנסמן שם. תו\"א יתרו עד, ג. מאמרי אדה\"ז על מארז\"ל ע' א. מאמרי אדה\"א דברים ח\"ב ע' תב. וש\"נ."],["3680","67","<b>וידגו לרוב בקרב הארץ</b>: ויחי מט, טז."],["3681","68","<b>הוא הוא</b>: כ\"ה בגוכתי\"ק."]]],[2000470412,"<h3>בן פורת יוסף</h3>\n<b>יום הנ\"ל</b>\n<b>בן</b> פורת יוסף<sup data-n=\"3682\">1</sup> בן פורת עלי עין<sup data-n=\"3683\">2</sup>, בן פורת יוסף ברי דחכים יוסף<sup data-n=\"3684\">3</sup>, בן פורת עלי עין קאי על לע\"ל<sup data-n=\"3685\">4</sup>, והנה צ\"ל תחילה ההפרש בין ימוהמ\"ש ובין לע\"ל, דהנה כתי' ונגלה כבוד ה'<sup data-n=\"3686\">5</sup> וראו כל בשר כו' היינו שלע\"ל יהי' גילוי אלקות ולא נא' מהיכן יהי' הגילוי, והענין דהנה כל מה שממשיכים עתה ע\"י עבודה כנ\"ל<sup data-n=\"3687\">6</sup> וכמ\"ש היושבי בשמים<sup data-n=\"3688\">7</sup> והו\"ע בן פורת יוסף עכשיו הוא רק להוסיף אורות באצי'<sup data-n=\"3689\">8</sup> ולע\"ל יומשך למטה נמצא שלימוהמ\"ש לא יהי' דבר חדש כ\"א מה שממשיכים עתה יומשך לע\"ל בגילוי, וה\"ז שייך להעבודה של עכשיו, וזהו ושם נעשה לפניך כמצות רצוניך<sup data-n=\"3690\">9</sup> שעיקר המצות יהיו לע\"ל דעיקר הכוונה הוא שיומשך למטה ועכשיו אינו רק להוסיף אורות באצי' ולע\"ל יומשך למטה לכן אז יהי' עיקר המצות וה\"ז עד\"מ כמו מי שיש לו אוצר ה\"ה אצלו לא בגלוי כ\"א בתיבה או בשק<sup data-n=\"3691\">10</sup> ואינו נראה לשום אדם ומ\"מ הרי ישנו בהעלם, כמו\"כ יובן בענין העבודה דעכשיו שהוא רק להוסיף אורות באצי' והוא בהעלם ולע\"ל יומשך מהעלם אל הגילוי, וזהו ונגלה כבוד הוי' וראו כל בשר, ונגלה, שיומשך מהעלם אל הגילוי, וזהו כי עין בעין יראו<sup data-n=\"3692\">11</sup> בשוב ה' ציון, היינו עין דיחו\"ע ועין דיחו\"ת<sup data-n=\"3693\">12</sup>, יחו\"ע הוא איך שכולו קמי' כלא חשיב<sup data-n=\"3694\">13</sup> ולמעלה הוא היש האמיתי ולמטה אין, ויחו\"ת הוא ביטל היש לאין וע\"י האתכפיי' והו\"ע עשי' ל' כפיי'<sup data-n=\"3695\">14</sup> והכרח עי\"ז עין בעין שיומשך מיחו\"ע ליחו\"ת וזה יהי' לימוהמ\"ש, וזהו בן פורת יוסף ברי",[["3682","1","<b>בן פורת יוסף</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב. ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\nלמאמר זה ראה אוה\"ת ויחי ח\"ב ע' 800 ואילך (נ\"א) ס\"ע תב ואילך. ע' תב ואילך (נ\"ב). ע' שפז. פלח הרמון ויחי קלו, ד. סה\"מ עזר\"ת ע' קכב."],["3683","2","<b>בן פורת. . עלי עין</b>: ויחי מט, כב."],["3684","3","<b>ברי דחכים יוסף</b>: וכ\"ה בסמוך."],["3685","4","<b>בן פורת עלי עין. . לע\"ל</b>: ראה בהדרושים שבריש המאמר. המשך תער\"ב ח\"א ע' תנט."],["3686","5","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["3687","6","<b>כנ\"ל</b>: ראה הנחה שלפנ\"ז."],["3688","7","<b>היושבי בשמים</b>: תהלים קכג, א."],["3689","8","<b>עכשיו. . להוסיף אורות באצי'</b>: ראה פע\"ח בהקדמה. ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש יא כלל טז. מאמרי אדה\"א דברים ח\"ד ע' א'תסז. וש\"נ. תו\"ח בשלח ח\"א קנו, ב הערה 312."],["3690","9","<b>ושם נעשה לפניך כמצות רצוניך</b>: מוסף ליו\"ט [בדילוג]. ראה גם לקמן הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 73. לעיל (בחלק המאמרים) המשך מצה זו רפס\"ג[ednref_215_א]. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פי\"ב. ד\"ה ובשביעית יצא לחפשי חנם. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי על יד הערה 73. ד\"ה עטרת תפארת שיבה על יד הערה 114. ד\"ה אוסרי לגפן תקס\"ד נדפס בתו\"ח ויחי רלו, א. רלח, ד. מאמרי אדה\"א שמות ח\"א ע' רכו. וש\"נ. תו\"ח שמות ח\"א כב, ג. וש\"נ. סה\"מ תרל\"ג ח\"א ע' קצה. עת\"ר ע' רטז ואילך."],["3691","10","<b>אוצר. . בתיבה או בשק</b>: ראה לקו\"ת דברים א, ב. תו\"ח ויצא קסה, ג ובהערה 49. ש\"א נה, ב ובהערה 8. סה\"מ תרכ\"ט ס\"ע רכח. וש\"נ."],["3692","11","<b>כי עין בעין יראו</b>: ישעי' נב, ח. ראה לקו\"ת פ' ראה כג, ד."],["3693","12","<b>דיחו\"ע. . דיחו\"ת</b>: זהר בהקדמה יב, א."],["3694","13","<b>שכולו קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["3695","14","<b>עשי' ל' כפיי'</b>: ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 505. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי על יד הערה 25. מאמרי אדה\"ז תקס\"ו ע' קפו. מאמרי אדה\"א ויקרא ח\"ב ע' תשסא ואילך. אוה\"ת בחוקותי כרך ד ע' א'קסט. סה\"מ תרל\"ו ח\"ב ע' רפט. תרל\"ח ע' רנה. וש\"נ.\n\n[edn_215_א] ואולי כן צ\"ל בסה\"מ מלוקט ד' ע' רמא הערה 45."]]],[2000470413,"דחכים יוסף. אבל לע\"ל כתי' בן פורת עלי עין שהוא למעלה מהעין דיחו\"ע, דמה שנמשך מיחו\"ע ליחו\"ת זהו באתעדל\"ת אתעדל\"ע<sup data-n=\"3696\">15</sup> לפ\"ע הביטול היש דיחו\"ת לפ\"ע זה נמשך מיחו\"ע אבל לע\"ל עלי עין אתדל\"ע שאין אתעדל\"ת מגיע לשם, וזה אינו שייך להמשיך ע\"י עבודה רק מתנה, אך מתנה אינו נותנין רק למי ששוה<sup data-n=\"3697\">16</sup> כמ\"כ כאן אחר שע\"י המשיך מיחו\"ע ליחו\"ת נמשך אח\"כ בחי' עלי עין שלמע' מיחו\"ע, וזהו ע\"ד פתחי לי כחודה של מחט<sup data-n=\"3698\">17</sup> ואני אפתח להם<sup data-n=\"3699\">18</sup> כפתחו של אולם הגם שאינו בערך כלל מ\"מ עי\"ז אפתח להם כפתחו של אולם, כמו\"כ כאן הגם שאינו בערך כלל מ\"מ ע\"י מה שממשיכים מבחי' יחו\"ע ליחו\"ת נמשך אח\"כ בחי' עלי עין.",[["3696","15","<b>באתעדל\"ת. . אתעדל\"ע</b>: ראה זהר לך פח, א. מאמר ד\"ה לרוקע נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קצד [ובמקביליו ובהנסמן במ\"מ לשם]. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. תו\"ח שמות ח\"א מא, א ובהערה 189."],["3697","16","<b>מתנה. . למי ששוה</b>: ראה מגילה כו, ב. גיטין נ, ב. ב\"מ טז, א. ב\"ב קנו, א."],["3698","17","<b>פתחי לי כחודה של מחט</b>: ראה ס' חרדים בהקדמה. לקו\"ש ויקהל ח\"א ע' 191 הערה 17. תו\"א מג\"א צד, ג. סה\"מ תרל\"ח ע' תסד. וש\"נ."],["3699","18","<b>להם</b>: אוצ\"ל: לכם."]]],[2000470414,"<h3>כי הנה יוצר הרים</h3>\n<b></b><b>בס\"ד י' א' על חתונת נ\"א רד\"ב</b>\nי' א' על חתונת נ\"א רד\"ב\n<b>כי</b> הנה יוצר הרים<sup data-n=\"3700\">1</sup> ובורא רוח ומגיד לאדם מה שיחו<sup data-n=\"3701\">2</sup>, ועל סמך פסוק זה נתקן ברכת יוצר האדם<sup data-n=\"3702\">3</sup> וצ\"ל והלא אדם בגימ' מ\"ה<sup data-n=\"3703\">4</sup> ומה שייך יצירה ע\"ז<sup data-n=\"3704\">5</sup>, וכן צ\"ל",[["3700","1","<b>כי הנה יוצר הרים</b>: הנחת[ednref_216_א] כ\"ק אדמו\"ר מהורש\"ב[ednref_217_ב].\nראה מאמר ד\"ה זה בסה\"מ תרל\"א (נמצא בדפוס[ednref_218_ג]) תרל\"ב ח\"ב ע' תקנד[ednref_219_ד] תרל\"ד ע' לו[ednref_220_ה] ובהנסמן בהנ\"ל. קונט' דרושי חתונה תרמ\"ב (קה\"ת תשמ\"א — יודפס בע\"ה בסה\"מ תרמ\"ב) ד\"ה להבין שרש ענין הברכה דיוצר האדם ע' ז[ednref_221_ו].\nבהכותרת: י' [ יו\"ד] א' [ אדר, או יום א' בשבוע] על חתונת נ\"א רד\"ב. לע\"ע לא נתברר אודות מי המדובר. אחר תיבת רד\"ב נכתבה עוד תיבה ונמחקה."],["3701","2","<b>כי הנה. . מה שיחו</b>: עמוס ד, יג."],["3702","3","<b>ועל סמך פסוק זה. . יוצר האדם</b>: ברכה שלישית דנשואין. ראה גם מאמרי אדמו\"ר מהר\"ש דרושי חתונה ס\"ע סו. וראה גם (בנוסף להערה 1) בענין יוצר הרים ויוצר האדם סידור קלד, סע\"א. מאמרי אדה\"א דרושי חתונה ח\"א ע' שח."],["3703","4","<b>אדם בגימט' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א הערה 14."],["3704","5","<b>ומה שייך יצירה ע\"ז</b>: בסה\"מ תרל\"ב כאן: שהוא שם מ\"ה במילוי אלפין, ואיך אפ\"ל יצירה על שם מ\"ה דאיהו אלקות בעצם.\n\n[edn_216_א] ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n[edn_217_ב] נדפס מכאן — בלי המ\"מ — במאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' קמו ואילך.\n\n[edn_218_ג] נדפס גם במאמרי אדמו\"ר מהר\"ש שם ע' יז ואילך. ראה שם ע' סד ואילך.\n\n[edn_219_ד] נדפס גם בדרושי חתונה שם ע' קלח ואילך.\n\n[edn_220_ה] נדפס גם במאמרי אדמו\"ר מהר\"ש שם ע' כ ואילך.\n\n[edn_221_ו] <b>נדפס גם בדרושי חתונה שם ע' קסב ואילך. </b>\n<b>ז) מובא גם בשם החייטא בכ\"מ ומהם</b>: תו\"א בראשית ה, ד. תו\"ח הנ\"ל. לקו\"ת פ' ראה לא, אב. סהמ\"צ להצ\"צ ס\"ע נו. ס\"ע ע. אוה\"ת פסח כרך ג' ע' תשצו. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' קלה. סה\"מ תרל\"ב ח\"ב ע' תקסז. תרל\"ד ע' לח. תרל\"ו ע' רסג. ע' שמו. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויאמר לך לך על יד הערה 87 (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 114. סה\"מ תרמ\"ג ע' לאג. המשך תער\"ב ח\"א ס\"ע שטו. ע' שיט. ח\"ב ע' א'עב. סה\"מ תר\"פ ע' קכח. קונט' חנוך לנער ע' 37 (ובהוצאה שני' ע' 47). לקוטי ביאורים לשעה\"י קפה, ד."]]],[2000470415,"מ\"ש לפני לא נוצר אל<sup data-n=\"3705\">6</sup>, איך יעלה על הדעת שנוצר כו' שצ\"ל שלא נוצר. והענין דהנה כתי' חייב אדם לברך<sup data-n=\"3706\">7</sup> מאה ברכות בכ\"י שנא' ועתה ישראל<sup data-n=\"3707\">8</sup> מה ה' אלקיך שואל מעמך א\"ת מה אלא מאה<sup data-n=\"3708\">9</sup>, וצ\"ל אומרו א\"ת<sup data-n=\"3709\">10</sup> מה והרי כתי' מה, ולהבין זה צ\"ל תחילה ההפרש בין ברכה לתפלה<sup data-n=\"3710\">11</sup>, ברכה הוא שממשיכים מה שיש בשרש ומקור ולא דבר חדש אלא מה שכבר ישנו בשרש ומקור לא יתעכב שם ויומשך למטה וזהו מ\"ש איש אשר כברכתו<sup data-n=\"3711\">12</sup> ברך אותו<sup data-n=\"3712\">13</sup>, פי' כברכתו איך שהוא בשרש ומקור, וזהו מ\"ש ואולם אחיו הקטן<sup data-n=\"3713\">14</sup> יגדל ממנו ולמה לא היפך זאת אלא דענין הברכה הוא להמשיך מה שיש בשרש ומקור ולא דבר חדש, ותפלה הוא להמשיך דבר חדש יהי רצון שיומשך רצון חדש.\n<b>וביאור</b> ענין הברכה הנה כתי' ברוך ה' אלקי ישראל<sup data-n=\"3714\">15</sup> מן העולם ועד העולם, פי' מעלדאת\"כ לעלדאת\"ג<sup data-n=\"3715\">16</sup> הגם יש<sup data-n=\"3716\">17</sup> כמה וכמה עולמות<sup data-n=\"3717\">18</sup> אך בד\"כ הם ב' עולמות עלמדאת\"כ ועלדאת\"ג, ויובן ב' עולמות אלו בנפש האדם שיש בלבושים מח'<sup data-n=\"3718\">19</sup> ודיבור<sup data-n=\"3719\">20</sup>, דיבור הוא כשמשכיל איזה השכלה ורוצה לגלות ההשכלה לזולתו מגלה לו בדיבור שהו\"ע גילוי העלם העצמי לגבי זולתו, ומח' הוא מגלה גילוי העלם העצמי לגבי עצמו, דכשנופל לו איזה ברק המבריק<sup data-n=\"3720\">21</sup> הרי גם בעצמו אינו יודע ההשכלה רק שיודע שיש שם איזה השכלה אבל מהו ההשכלה אינו יודע עדיין",[["3705","6","<b>לפני לא נוצר אל</b>: ישעי' מג, י. ראה גם אוה\"ת שמות ע' לט וע' מה ואילך. קונט' דרושי חתונה כאן בסופו (ע' יא). סה\"מ תרל\"ח ע' קצג. סה\"מ מלוקט ד' ע' פב. וש\"נ."],["3706","7","<b>חייב אדם לברך</b>: מנחות מג, ב."],["3707","8","<b>ועתה ישראל</b>: עקב י, יב."],["3708","9","<b>א\"ת מה אלא מאה</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' קכז."],["3709","10","<b>וצ\"ל אומרו א\"ת</b>: ראה גם סה\"מ תרל\"ב וקונט' דרושי חתונה כאן. תרל\"ח ע' פז וע' ריב. המשך מים רבים תרל\"ו ע' רכח. סה\"מ מלוקט ה' ע' שמא."],["3710","11","<b>ההפרש בין ברכה לתפלה</b>: ראה לקו\"ת פ' ראה יט, א. מאמרי אדה\"ז תקס\"ח ח\"ב ע' תשז ואילך. הדרושים שבהערה 1. וש\"נ. סה\"מ תרל\"ח ע' רי."],["3711","12","<b>איש אשר כברכתו</b>: ויחי מט, כח. ראה מאמרי אדה\"ז תקס\"ח שם ע' תשח. סה\"מ תרס\"ט ע' צד ואילך. בהערה שלפנ\"ז. וראה גם המשך תער\"ב ח\"ב ע' תשלז. לקו\"ש לך כרך י ע' 38 ואילך."],["3712","13","<b>אותו</b>: [וכ\"ה בסה\"מ תרס\"ט ותער\"ב שם]. בויחי שם: אותם."],["3713","14","<b>ואולם אחיו הקטן</b>: ויחי מח, יט."],["3714","15","<b>ברוך ה' אלקי ישראל</b>: תהלים קו, מח דהי\"א טז, לו. בלקו\"ת פ' ראה יט, ב מציין זח\"א ויצא קנח, ב. ראה גם לקמן ח\"ב (בחלק ההנחות) הנחה ד\"ה ביום השמיני עצרת על יד הערה 78. תו\"ח שמות ח\"א יח, ג. וש\"נ."],["3715","16","<b>מעלדאת\"כ לעלדאת\"ג</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך."],["3716","17","<b>יש</b>: אוצ\"ל: שיש. במאמרי אדמו\"ר מהר\"ש דרושי חתונה כאן ע' קמו הדפיסו בפנים בלי שום הערה: שיש."],["3717","18","<b>כמה וכמה עולמות</b>: ראה זהר אד\"ר נשא קכח, ב. תרל\"ח ע' כג וע' כד."],["3718","19","<b>עלמדאת\"כ ועלדאת\"ג. . מח' ודיבור</b>: ראה (בנוסף להערה 1) שער היחוד והאמונה פי\"א. לעיל (בחלק המאמרים) המשך מצה זו פרק ג\"ן. תו\"ח בשלח ח\"א קמג, ד. וש\"נ."],["3719","20","<b>בנפש. . בלבושים מח' ודיבור</b>: ראה תניא פ\"ד."],["3720","21","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לקמן הנחה ד\"ה מצה זו על יד הערה 64. ד\"ה אז ישיר משה על יד הערה 13. ד\"ה וביום הביכורים על יד הערה 31. ד\"ה כי טובים דודיך מיין על יד הערה 39. (בחלק ההנחות) הנחה ד\"ה וביום הביכורים על יד הערה 43. (לעיל (בחלק המאמרים) המשך מצה זו ספ\"ל. לקמן ח\"ב המשך יונתי רפ\"ד. וש\"נ. תו\"ח בשלח ח\"א קצז, ב. וש\"נ. סה\"מ תרל\"ח ע' פא. וש\"נ. פלח הרמון אמור ע' של."]]],[2000470416,"ואח\"כ כשחושב באותיות המח' אז יודע ההשכלה א\"כ ה\"ז גילוי העלם העצמי לגבי עצמו, וה\"ז כמו אותיות הדיבור לגבי זולתו, דלזולתו אינו ידוע ההשכלה שחושב רק זה הוא יודע שחושב איזה השכלה וכמו\"כ אותיות המח' בתחילה כשנופל לו הברק המבריק אינו יודע כלל מהו ההשכלה וע\"י בא<sup data-n=\"3721\">22</sup> לו ההשכלה לידי גילוי, א\"כ הם שוים אלא שאותיות המח' הם מגלים לעצמו ואותיות הדיבור מגלים לזולתו, והנה האותיות מאחר שהם מגלים את השכל מוכרח לומר שהם למעלה מהשכל, וזהו מה דאי' דשרש האותיות מקדמות השכל<sup data-n=\"3722\">23</sup>, דברק המבריק בכלל שכל יחשב וקדמות השכל הוא למעלה מהברק המבריק, ואותיות הדיבור מאחר שמגלים העלם העצמי לגבי זולתו שרשם למעלה מאותיות המח'<sup data-n=\"3723\">24</sup>, נמצא אותיות המח' ואותיות הדיבור שניהם שרשם למעלה מהשכל ובזה או' המח' הם גילוי ההעלם העצמי לגבי עצמו ואו' הדיבור הם גילוי העלם העצמי לגבי זולתו, ובזה מאחר דאו' הדיבור מגלים לזולתו שרשם למעלה מאותיות המח', וכמו\"כ למעלה עלמדאת\"כ ועלדאת\"ג, עלמדאת\"כ הוא שמכוסה מזולתו, אבל שם הוא בגילוי<sup data-n=\"3724\">25</sup> דאל\"כ אינו שייך שיקרא בשם עלמי\"ן, אך דוקא להמהווה העולם הוא בגילוי, אבל לגבי זולתו הוא מכוסה ונעלם וזהו עלמא סתימין דלא אתגלין, ועלדאת\"ג הוא גילוי לגבי זולתו.\n<b>והנה</b> ברה\"ע הי' בב', ואי' דך\"ו דורות<sup data-n=\"3725\">26</sup> הי' האלף קורא תגיר<sup data-n=\"3726\">27</sup> על שלא הי' ברה\"ע באלף עד מ\"ת שהי' באלף, ואי' בזוהר הטעם שלא הי' ברה\"ע באלף, דאלף ר\"ת ארור<sup data-n=\"3727\">28</sup>, ולפ\"ז צ\"ל למה הי' מ\"ת באלף, וצ\"ל דהנה אלף הוא בחי' פלא<sup data-n=\"3728\">29</sup> עליון אשר שם כחשיכא כאורה<sup data-n=\"3729\">30</sup> לא די שהחושך שוה לאור אלא גם האור שוה",[["3721","22","<b>וע\"י בא</b>: אוצ\"ל: וע\"י המח' בא."],["3722","23","<b>דשרש האותיות מקדמות השכל</b>: ראה אגה\"ק ס\"ה (קז, ב). לקמן הנחה ד\"ה מצה זו פיסקא ויותר. ד\"ה אז ישיר משה על יד הערה 26. (לעיל בחלק המאמרים) המשך מצה זו פ\"ב. תו\"א מג\"א צא, ב. לקו\"ת בחוקותי מו, ב. פלח הרמון בחוקותי ע' תמא. וש\"נ. סה\"מ תרל\"ח ע' כא. וש\"נ. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע ובהערה 62."],["3723","24","<b>ואותיות הדבור. . מאותיות המח'</b>: ראה גם סה\"מ תרל\"ב כאן ע' תקנה. תרל\"ח ע' כב ובהנסמן שם."],["3724","25","<b>עלמדאת\"כ. . שם הוא בגילוי</b>: ראה גם סה\"מ תרל\"ב כאן. תרל\"ח ע' קלט."],["3725","26","<b>ברה\"ע. . דך\"ו דורות</b>: ב\"ר פ\"א, י. תנחומא — באבער — יתרו טז. וש\"נ."],["3726","27","<b>תגיר</b>: אוצ\"ל: תגר."],["3727","28","<b>בזוהר. . דאלף ר\"ת ארור</b>: ויגש רה, ב. ראה (בנוסף להערה 1) לקו\"ת פ' ראה יט, ב. ביאוה\"ז להצ\"צ כרך ב ע' תשיח ואילך. סה\"מ תרל\"ח ע' קכז. תש\"ג ע' 95. לקו\"ש בראשית כרך טו ע' 1. וש\"נ. שמח\"ת כרך יט ע' 383 בשולי היריעה."],["3728","29","<b>אלף. . פלא</b>: ראה ת\"ז ת\"ע (קלה, א). הקדמת הראב\"ד לס\"י נתיב הא'."],["3729","30","<b>כחשיכא כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. סידור סדר הגדה רצז, רע\"ד. עט\"ר דרוש לעשי\"ת ע' נא. סה\"מ תרכ\"ז ע' תצד. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויאמר כו' לך לך על יד הערה 54. ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 138. ד\"ה אשריכם זורעי על כל מים על יד הערה 107."]]],[2000470417,"לחשך, כל נהוראין מתחשכאן קמי'<sup data-n=\"3730\">31</sup>, וע\"ד כ\"ע אע\"ג דאיהו אור צח אור מצוחצח אוכם הוא קדם עה\"ע<sup data-n=\"3731\">32</sup>, ומשם אפשר שיומשך גם למקום שאינו ראוי, ולא יהי' כמ\"ש יאר ה' פניו אליך ינהר ה' שכינתא לוותך<sup data-n=\"3732\">33</sup>, אלא יומשך גם למקום שאינו ראוי, לכן הי' ברה\"ע בב' [דכתי' בחכ' יבנה בית<sup data-n=\"3733\">34</sup> יבנה בי\"ת<sup data-n=\"3734\">35</sup> ] שהוא בחי' חכ'<sup data-n=\"3735\">36</sup>, ומצד החכ' יומשך למקום הראוי דוקא, וזהו שכ' בחייט דבחכ' יש קצת דין<sup data-n=\"3736\">37</sup> דזה שיומשך למקום הראוי דוקא הוא קצת דין, ואח\"כ הי' מ\"ת באלף, דאחר שהי' ברה\"ע בב' גם מאלף יומשך למקום הראוי דוקא, וזהו א\"ת מ\"ה אלא מאה דמה שיבא לבחי' מ\"ה יומשך הא' ג\"כ למקום הראוי דוקא. דהנה חכ' הוא כח מ\"ה<sup data-n=\"3737\">38</sup> ואי' בפרד\"ס<sup data-n=\"3738\">40</sup> מ\"ה הוא התייחסו אל הכתר<sup data-n=\"3739\">39</sup>, וכתר הוא שמשפיע בבחי' בינה, וכשיהי' בחי' מ\"ה אזי גם הא' יומשך למקום הראוי, דזהו לפני לא נוצר אל, אל הוא גילוי כמ\"ש חסד אל כל היום<sup data-n=\"3740\">41</sup>, אל ה' ויאר לנו<sup data-n=\"3741\">42</sup>, לפני לא נוצר אל, לפני בחי' [מ\"ה] לא הי' גילוים, וזהו יוצר האדם, אדם בגימ' מ\"ה, יוצר האדם דהגילוי הוא בבחי' מ\"ה. וזהו כי הנה יוצר הרים ובורא רוח ומגיד לאדם מה שיחו, שיחו הוא דיבור<sup data-n=\"3742\">43</sup>, מה שיחה שגם בשיחה",[["3730","31","<b>כל נהוראין מתחשכאן קמי'</b>: ראה זהר בראשית כג, א."],["3731","32","<b>כ\"ע. . קדם עה\"ע</b>: ראה ת\"ז ת\"ע קלה, ב. מאמרי אדה\"א דברים ח\"ג ע' תתיא. וש\"נ. המשך והחרים תרל\"א ע' סט. סה\"מ תרל\"ד ע' רמז. המשך תער\"ב ח\"א ע' כא."],["3732","33","<b>יאר ה' פניו. . לוותך</b>: נשא ו, כה ובת\"א."],["3733","34","<b>בחכ' יבנה בית</b>: משלי כד, ג."],["3734","35","<b>יבנה בי\"ת</b>: בסה\"מ תרל\"ב כאן ע' תקנז מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' קסה: בשם הת\"ז. ראה גם מאמרי אדה\"א קונטרסים ע' ריב וע' ריז. ביאוה\"ז להצ\"צ כרך ב ע' תשיג."],["3735","36","<b>בי\"ת. . חכ'</b>: ראה זהר בראשית לא, ריש ע\"ב. תו\"ח לך פח, ג הערה 12."],["3736","37","<b>שכ' בחייט דבחכ'. . דין</b>: ראה שערי אורה שער ט (צב, ב). מערכת אלקות פ\"ד מערכת שמות המדות ד\"ה השני' בסופה ובפי' החייט שם. פרדס שער מהות והנהגה ש\"ח, פ\"ה. פ\"ו. שער המכריעין ש\"ט, פ\"ה. ע\"ח שער א\"א שי\"ג, פ\"ו. מבו\"ש ש\"ג ח\"ב פ\"ו בשם המערכת. מאמרי אדה\"א נ\"ך ע' שיג. וש\"נ. תו\"ח בראשית לא, ד ובהערה 40. אוה\"ת שמות כרך ז ע' ב'תקכהז."],["3737","38","<b>חכ' הוא כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א."],["3738","40","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 267."],["3739","39","<b>ואי' בפרד\"ס מ\"ה. . הכתר</b>: ראה גם שעה\"כ שכ\"ג, פ\"ח מערכת חכמה. סה\"מ תרל\"ב כאן ע' תקנח. המשך וככה תרל\"ז פכ\"ה. פל\"ב. לקמן הנחה ד\"ה וירא העם וינועו על יד הערה 66."],["3740","41","<b>חסד אל כל היום</b>: תהלים נב, ג."],["3741","42","<b>אל ה' ויאר לנו</b>: תהלים קיח, כז. ראה אגה\"ק ס\"ז (קיב, א). סה\"מ תרל\"ח ע' קעד. וש\"נ."],["3742","43","<b>שיחו הוא דיבור</b>: מצו\"צ עמוס כאן."]]],[2000470418,"יהי' בחי' מ\"ה צ\"ל תחילה יוצר הרים, הרים הם בחי' טורי חשוכא<sup data-n=\"3743\">44</sup> מדות שלמעלה מהחכ', שיומשך בחי' א' בבחי' מ\"ה ואזי יומשך בבחי' הדיבור ג\"כ וכמ\"ש שיחו בכל נפלאותיו<sup data-n=\"3744\">45</sup>, שבבחי' שיחו יומשך בחי' נפלאותיו, פלא עליון, וזהו כי הנה יוצר הרים ובורא רוח ומגיד לאדם מה שיחו, תחילה צריך להמשיך לבחי' מ\"ה כדי שיומשך למקום הראוי וכמו שביקש משה ונפלינו אני ועמך<sup data-n=\"3745\">46</sup> שאפי' מבחי' פלא עליון יהי' רק אני ועמך שיומשך למקום הראוי דוקא עד שיומשך גם בבחי' שיחו הוא בחי' הדיבור.",[["3743","44","<b>טורי חשוכא</b>: ראה זהר פינחס רמט, ב. סה\"מ תרל\"ח ע' קצז. וש\"נ."],["3744","45","<b>שיחו בכל נפלאותיו</b>: דבהי\"א טז, ט."],["3745","46","<b>ונפלינו אני ועמך</b>: תשא לג, טז. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויובן כו' הני ששה ועשרים הודו על יד הערה 133 שמציין בלקו\"ת בד\"ה מצה זו [צו יב, סע\"ג]. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 137. ד\"ה למה קדמה שמע לוהי' אם שמוע על יד הערה 23. אוה\"ת תשא כרך ח ע' ג'קטז ואילך. סה\"מ תר\"ל ע' קז. תרל\"ב ח\"א ע' קכח."]]],[2000470419,"<h3>אי' כו' נביאים כתובים</h3>\n<b></b><b>יום ה' פ' תשא תר\"ם לפ\"ק חג הפורים</b>\nיום ה' פ' תשא חג פורים\n<b>אי'</b> בירושלמי ובמדרש<sup data-n=\"3746\">3</sup> נביאים וכתובים<sup data-n=\"3747\">1</sup> עתידים להבטל ומגילת אסתר לא תיבטל<sup data-n=\"3748\">2</sup>, וצ\"ל והלא בנביאים וכתובים יש גילוים יותר עליונים מבמג\"א ומפני מה יבטלו הם ומג\"א לא תבטל. והענין דהנה ארז\"ל אסתר ירקרקות היתה<sup data-n=\"3749\">4</sup> אלא שחוט של חסד משוך עלי', וגם צ\"ל מהו\"ע החוט של חסד. והענין דהנה כתי' שקר החן והבל היופי אשה יראת ה' היא תתהלל וארז\"ל<sup data-n=\"3750\">5</sup> שקר זה דורו של משה והבל היופי זה דורו של יהושע, אשה יראת ה' היא תתהלל יש בזה ב' דרשות א' זה דורו של חזקיהו, ב' שקר החן זה דורו של משה ויהושע והבל היופי דורו של חזקי' אשה יראת ה' היא תתהלל זה דורו של ר\"י בר<sup data-n=\"3751\">6</sup> אילעי.",[["3746","3","<b>ובמדרש</b>: עד\"ז הובא גם לקמן (בחלק ההנחות) בהנחה כאן."],["3747","1","<b>אי' בירושלמי ובמדרש נביאים וכתובים</b>: דרוש זה נמצא לפנינו בשתי הנחות א) הנחת<sup data-n=\"e222\">*</sup> כ\"ק אדמו\"ר מהורש\"ב והיא הנדפסת פה. ב) הנחה אחרת מדרוש זה ונדפסה לקמן (בחלק ההנחות).\nלמאמר זה ראה סה\"מ תרכ\"ז ע' קפז ואילך וע' קפט ואילך. וש\"נ. תרכ\"ח ע' קד ואילך. ד\"ה ולקחתם לכם תרל\"ב (קה\"ת תש\"נ ע' 5 ואילך — יודפס בע\"ה בסה\"מ תרל\"א).\nלהתחלת וסיום המאמר ראה תו\"א מג\"א צ, ד. צב, א. מאמרי אדה\"ז הנחות הר\"פ ע' קכה. ש\"א נז, א ואילך. סה\"מ תרכ\"ז כאן ע' קצד. וש\"נ. תרכ\"ח כאן ע' קטז."],["3748","2","<b>אי' בירושלמי. . אסתר לא תיבטל</b>: ראה שם מגילה פ\"א, ה\"ה."],["3749","4","<b>אסתר ירקרקות היתה</b>: ראה מגילה יג, א."],["3750","5","<b>שקר החן והבל היופי. . וארז\"ל</b>: משלי לא, ל. ראה סנהדרין כ, א. ילקוט שמעוני שמואל-א כה, מד (רמז קלו)."],["3751","6","<b>בר</b>: לקמן: ב\"ר. ואולי גם כאן צ\"ל כן."],["e222","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470420,"<b>וביאור</b> הענין דהנה כתי' אם לא תדעי לך היופי בנשים<sup data-n=\"3752\">*7</sup>, וצ\"ל מהו\"ע היופי, צ\"ל מתחילה מה שנק' ישראל פעמים בשם רחל<sup data-n=\"3753\">7</sup> ופעמים בשם אסתר<sup data-n=\"3754\">8</sup> דהנה כתי' ורחל היתה<sup data-n=\"3755\">9</sup> יפת תואר ויפת מראה, יפת תואר הוא שחתוך האברים הם כדבעי למהוי כל אבר לפ\"ע, ויפת מראה<sup data-n=\"3756\">10</sup> הוא שזיו קלסתר פנים הוא יפה, ואפשר שיהי' יפה תואר ואינו יפה מראה, ואפשר שזיו קלסתר פנים יהי' כדבעי אבל אינו יפה תואר, כמו\"כ יובן בנמשל יפה תואר הו\"ע מ\"ע דרמ\"ח פקודין רמ\"ח אברין דמלכא<sup data-n=\"3757\">11</sup> וזהו שהמצות יהיו כדבעי למהוי היינו מפני אשר ציוה ה' ולא בקרירות, מצות אנשים מלומדה<sup data-n=\"3758\">12</sup>, ויפה מראה הו\"ע מל\"ת דשמי עם י\"ה שס\"ה<sup data-n=\"3759\">13</sup> והוא בחי' חכ'<sup data-n=\"3760\">14</sup> וכתי' חכמת אדם תאיר פניו<sup data-n=\"3761\">15</sup>, וענין יפה תואר לא נא' טוב תואר<sup data-n=\"3762\">16</sup> אלא יפה מהו\"ע היופי, דהנה רמ\"ח פקודין רמ\"ח אברין דמלכא מספר דרמ\"ח הוא דז\"א בעל ט\"ס טפ\"ט פ\"א רת\"ס רמ\"ג ה\"ח<sup data-n=\"3763\">17</sup> המגדילים רמ\"ח. והנה המדות הם נולדים מהשכל וכשממשיכים מחכ' במדות עי\"ז נעשה התכללות המדות וזהו היופי, דגוון אינו<sup data-n=\"3764\">18</sup> יופי כ\"כ אלא כשיש התכללות מכמה גוונים<sup data-n=\"3765\">19</sup> אז יש בזה יופי, כמו\"כ יובן למעלה כשנעשה התכללות המדות חסד שבגבו' גבו'<sup data-n=\"3766\">20</sup> שבחסד ה\"ז יפה תואר, ויפה מראה הוא דהנה המדות הם רק נולדים מן השכל ומתנהגים ע\"פ השכל אבל שרשם למעל' מהמוחין<sup data-n=\"3767\">21</sup> (דז\"א בעתיקא אחיד ותליא<sup data-n=\"3768\">22</sup> או\"א במזלא אתכלילו ע' בתו\"ח בד\"ה",[["3752","*7","<b>אם לא תדעי לך היופי בנשים</b>: וכ\"ה לקמן — שה\"ש א, ח [ושם: היפה]."],["3753","7","<b>שנק' ישראל. . רחל</b>: ראה זהר וארא כט, ב. ב\"ר פע\"א, ב. תניא פמ\"ה. תו\"א מג\"א צד, ד."],["3754","8","<b>שנק' ישראל. . אסתר</b>: ראה תו\"א שם צג, ד. צד, רע\"ד. מאמרי אדה\"א נ\"ך ע' תצג. וש\"נ."],["3755","9","<b>ורחל היתה</b>: ויצא כט, יז."],["3756","10","<b>יפת תואר. . ויפת מראה</b>: ראה רש\"י ויצא שם. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קסט וע' 11 ואילך. תו\"ח ויצא קעד, ג ואילך. דרושים שבהערה 1."],["3757","11","<b>דרמ\"ח פקודין רמ\"ח אברין דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["3758","12","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 16. לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 508. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אני לדודי הא' על יד הערה 17. והב' על יד הערה 139. ד\"ה ובחודש השביעי הא' על יד הערה 13. והב' על יד הערה 28. (בחלק ההנחות) הנחה ד\"ה אני לדודי הא' על יד הערה 18. ד\"ה כנשר יעיר קנו על יד הערה 39. תניא פל\"ט (נג, ב). תו\"ח ויחי רמב, ג הערה 44. תצוה ח\"ב שלח, ג."],["3759","13","<b>דשמי עם י\"ה שס\"ה</b>: ראה לקמן הנחה ד\"ה ר' אבהו פתח והמה כאדם ובהערה 124."],["3760","14","<b>מל\"ת. . חכ'</b>: ראה סה\"מ תרכ\"ז כאן ע' קפח. וש\"נ. דרושים שבהערה 1."],["3761","15","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["3762","16","<b>טוב תואר</b>: מלכים-א א, ו."],["3763","17","<b>דז\"א בעל ט\"ס. . ה\"ח</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"ו. תו\"א מקץ לז, סע\"ד ואילך. שע\"ת מב, ב ובהערה 13."],["3764","18","<b>דגוון אינו</b>: אוצ\"ל: דגוון אחד אינו."],["3765","19","<b>התכללות מכמה גוונין</b>: בסמוך מביא ב' מדות. וראה גם אגה\"ק סי\"ב קיז, ב. מאמרי אדה\"א דברים ח\"ב ע' תקג.\nבדרושים שבהערה 1 מביא ג' גוונין. וראה גם לקו\"ת שה\"ש יד, א. תו\"ח בראשית מ, א ובהערה 6. לעיל (בחלק המאמרים) המשך מצה זו פמ\"ט."],["3766","20","<b>שבגבו' גבו'</b>: אוצ\"ל: שבגבו' וגבו'."],["3767","21","<b>המדות. . שרשם למעל' מהמוחין</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע שלא ואילך. סה\"מ תרל\"ח ע' שע. וש\"נ."],["3768","22","<b>דז\"א בעתיקא אחיד ותליא</b>: ראה זהר אד\"ז האזינו רצב, א. לעיל (בחלק המאמרים) המשך מצה זו פי\"ח ובהערה 543."]]],[2000470421,"בראשית ברא ב'<sup data-n=\"3769\">23</sup>, ובד\"ה ויאמר ה' הן כל הארץ שפה<sup data-n=\"3770\">24</sup> אחת<sup data-n=\"3771\">25</sup> כו'), וכשממשיכים מא\"ס דלאו מכאמ\"כ<sup data-n=\"3772\">26</sup> אז נעשה יופי בחכ' ג\"כ, וזהו יפה מראה.\n<b>וזהו</b> ורחל היתה יפת תואר ויפת מראה, דרחל הוא בחי' עלמא דאתגלייא<sup data-n=\"3773\">27</sup>, דהנה יעקב הוא בריח התיכון<sup data-n=\"3774\">28</sup> המבריח מן הקצה אל הקצה והעיקר הכוונה שיומשך בעלמא דאתגלייא, וזהו ע\"י רחל דוקא לכן ויאהב יעקב את רחל<sup data-n=\"3775\">29</sup> הגם שלאה הי' גבוה במדריגה מרחל<sup data-n=\"3776\">30</sup>, אך העיקר הכוונה נעשה ע\"י רחל לכן יוסף שנולד מן רחל כתי' אלה תולדות יעקב יוסף<sup data-n=\"3777\">31</sup> הגילוים של יעקב הוא יוסף, אך הנה כ\"ז הוא בזמן שבהמ\"ק<sup data-n=\"3778\">32</sup>, אבל בזמן הגלות אז נק' ישראל בשם אסתר והוא שמעלים ומסתיר ואינו נראה גילוי אלקות, וזהו אם לא תדעי לך היופי* בנשים שאינו בחי' יפה תואר ויפה מראה, אל יאמר נואש אלא ההסתר ג\"כ אלקות וכמ\"ש אכן אתה אל מסתתר<sup data-n=\"3779\">33</sup> שכח ההסתר ג\"כ אלקות, וזהו שקר החן והבל היופי אשה כו' שקר החן זו דורו של משה שהי' אז ניסים דיצ\"מ וקרי\"ס מעצמו שלא ע\"י אתעדל\"ת וזה חן, שקר החן, והבל היופי דורו של יהושע, דהנה כתי' הבל הבלים אמר קהלת<sup data-n=\"3780\">34</sup> הבל הבלים הכל הבל, ז' הבלים נגד ז' ימי בראשית, והוא ג\"כ ז' מדות, וזהו הבל היופי, אשה יראת ה' היא תתהלל זו דורו של ר\"י ב\"ר אילעי שלמדו תורה במס\"נ ועי\"ז מגיעים למדריגה היותר עליונה.\n<b>וזהו</b> אסתר ירקרקות היתה אלא שחוט של חסד משוך עלי', שע\"י ההסתר מגיעים למדרי' היותר עליונה, ולכן הנביאים והכתובים<sup data-n=\"3781\">35</sup> עתידים להבטל ומג\"א לא",[["3769","23","<b>בתו\"ח בד\"ה בראשית ברא ב'</b>: ראה שם יא, ד. יב, ג."],["3770","24","<b>בתו\"ח. . ובד\"ה ויאמר. . שפה אחת</b>: כ\"ה בגכתי\"ק."],["3771","25","<b>ויאמר ה' הן כל הארץ שפה אחת</b>: בתו\"ח: ויהי כל הארץ שפה אחת. . ויאמר ה' הן עם אחד ושפה אחת."],["3772","26","<b>דלאו מכאמ\"כ</b>: ת\"ז בהקדמה יז, ב."],["3773","27","<b>דרחל. . עלמא דאתגלייא</b>: ראה זהר סתרי תורה ויצא קנב, א. וארא כט, ב. ע\"ח שער מוחין דצלם שכ\"ג, פ\"ד."],["3774","28","<b>יעקב הוא בריח התיכון</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["3775","29","<b>ויאהב יעקב את רחל</b>: ויצא כט, יח. ראה תו\"א ויצא כב, ד ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' 6. תו\"ח ויצא קסח, ג ואילך. לעיל (בחלק המאמרים) המשך מצה זו רפכ\"א על יד הערה 652."],["3776","30","<b>שלאה הי' גבוה במדריגה מרחל</b>: ראה הערה 27."],["3777","31","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב. ראה גם לעיל הנחה ד\"ה בן פורת יוסף הא' ובהערה 40."],["3778","32","<b>שבהמ\"ק</b>: אוצ\"ל: שבהמ\"ק הי' קיים."],["3779","33","<b>אכן אתה אל מסתתר</b>: ישעי' מה, טו. ראה גם לקמן הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 147. (בחלק ההנחות) בהנחה כאן על יד הערה 28. לקמן ח\"ב (בחלק ההנחות) ד\"ה שובה ישראל [הא' והב' על יד הערות 103. 108]. המשך מים רבים תרל\"ו פכ\"ה. פע\"ח [ומציין לד\"ה מי כמוכה — סה\"מ תרכ\"ט ע' קסג. וש\"נ]. פקנ\"ט. סה\"מ תרכ\"ז ס\"ע תקג."],["3780","34","<b>הבל הבלים אמר קהלת</b>: קהלת א, ב. קה\"ר וילקוט שמעוני עה\"פ. שוח\"ט רפצ\"ב."],["3781","35","<b>ולכן הנביאים והכתובים</b>: ראה להבא לקמן תו\"א מג\"א צ, ד. צב, א. מאמרי אדה\"ז הנחות הר\"פ ע' קכה. ש\"א נז, א. סה\"מ תרכ\"ז כאן ע' קצד. וש\"נ. תרכ\"ח כאן ע' קטז. (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 36 ואילך."]]],[2000470422,"תבטל, דהנה על לע\"ל כתי' ואמרו ביום ההוא<sup data-n=\"3782\">36</sup> הנה אלקינו זה, זה הוא גילוי, והוא, הו\"ע ההסתר ולע\"ל ואמרו ביום ההוא, שהוא הסתר הנה אלקינו זה שיהי' גילוי, והנה כתי' ואנכי הסתר אסתיר<sup data-n=\"3783\">37</sup> פני ביום ההוא שיש מדרי' שגם לע\"ל יהי' מוסתר ונעלם לכן נביאים וכתובים עתידים להבטל, דנביאים הוא גילוי עלמדאת\"כ בעלמדאת\"ג ועכשיו שעלמדאת\"כ מכוסה ואינו מאיר ומתגלה וע\"י נביאים נמשך מעלדאת\"כ בעלדאת\"ג כ\"ז גילוי, אבל לע\"ל שיתגלה בחי' עלדאת\"כ לא יהי' צריכים לנביאים וכ\"ש לכתובים דשרגא בטיהרא מאי אהני<sup data-n=\"3784\">38</sup> אבל מג\"א לא תבטל דבחי' זו יהי' מוסתר גם לע\"ל וצריכים להמשיך משם לכן לא תבטל וזהו נביאים כתובים עתידים להבטל אבל מג\"א לא תבטל.",[["3782","36","<b>ואמרו ביום ההוא</b>: וכ\"ה בסמוך — ישעי' כה, ט [ושם: ואמר]."],["3783","37","<b>ואנכי הסתר אסתיר</b>: וילך לא, יח."],["3784","38","<b>דשרגא בטיהרא מאי אהני</b>: חולין ס, ב."]]],[2000470423,"<h3>ויהי בימי אחשורוש</h3>\n<b>בהנ\"ל</b>\n<b>ויהי</b> בימי<sup data-n=\"3785\">1</sup> אחשורוש<sup data-n=\"3786\">2</sup>, ואי' מדר'<sup data-n=\"3787\">3</sup> ע\"פ ויאמר המן למלך<sup data-n=\"3788\">4</sup> אחשורוש<sup data-n=\"3789\">5</sup>, המן מדה\"ד, אחשורוש<sup data-n=\"3790\">6</sup> למי שאחרית וראשית שלו, וצ\"ל והלא אי' במדרש אין ויהי אלא<sup data-n=\"3791\">7</sup> כו' ומה שייך זה בבחי' מי שאחרית וראשית שלו, והענין דהנה אי' בזהר תי'<sup data-n=\"3792\">8</sup> וי יו\"ד",[["3785","1","<b>ויהי בימי אחשורוש</b>: דרוש זה נמצא לפנינו בשתי הנחות א) הנחת* כ\"ק אדמו\"ר מהורש\"ב והיא הנדפסת פה. ב) הנחה אחרת מדרוש זה ונדפסה לקמן (בחלק ההנחות).\nלמאמר זה (להתחלתו) ראה מאמר ד\"ה זה באוה\"ת מג\"א [מהדורת תש\"נ] ע' ג. (לפיסקא וזהו) לקו\"ת שה\"ש ו, ב. (לפיסקא ולכן) סה\"מ תרכ\"ז ע' קצב. תרכ\"ח ע' קח ואילך.\nבהכותרת: בהנ\"ל — אולי פי' ביום הנ\"ל. והשווה הכותרת לקמן בחלק ההנחות."],["3786","2","<b>ויהי בימי אחשורוש</b>: אסתר א, א."],["3787","3","<b>מדר'</b>: וכ\"ה גם בסה\"מ מלוקט ה' ע' קצג. (בהבא לקמן מובא בשם: אגדה). ראה מאו\"א מערכת אחשורוש אות קפב[ednref_223_א] הועתק באוה\"ת כאן [ושם: בהגדה]. ערה\"כ לבעל סה\"ד מערכת אחשורוש ושם מציין: סרל\"ח[ednref_224_ב] בשם הרקאנטי [ויצא כט, י] ובס' מחיר יין [לרמ\"א אסתר א, יד]. וראה גם של\"ה פ' ויצא רצא, א בהג\"הה."],["3788","4","<b>ויאמר המן למלך אחשורוש</b>: אסתר ג, ח."],["3789","5","<b>למלך אחשורוש</b>: תיבות אלו נמצאים ברקאנטי מחיר יין ובשל\"ה. ובמאו\"א ליתא."],["3790","6","<b>אחשורוש למי שאחרית וראשית שלו</b>: ראה גם אוה\"ת מג\"א כאן. סה\"מ תרס\"ט ע' קנד ואילך. סה\"מ מלוקט שם."],["3791","7","<b>אי' במדרש אין ויהי אלא</b>: באוה\"ת מג\"א כאן: ובגמ' פ\"ק דמגילה ד\"י ע\"ב כ\"מ שנא' ויהי בימי אינו אלא לשון צער. אבל בסה\"מ תרס\"ט ס\"ע קמב דאי' במד\"ר. ראה פתיחתא דאסת\"ר יא ילקוט שמעוני לך יד, א רמז עב (מהדורת ירושלים תשל\"ג ע' 275. וש\"נ) [ושם: צרה — ובקהלת יעקב מערכת ויהי מביא מפ\"ק דמגילה: צרה]. אגדתא דאסתר בתחלתה. זהר וירא קיט, ב. (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 6."],["3792","8","<b>תי'</b>: תיבת.\n\n[edn_223_א] וכן צ\"ל במאו\"א שם.\n\n[edn_224_ב] <b>ויש לעיין פיענוח הר\"ת. אולי צ\"ל</b>: סדל\"ח ס' דרושים לכל חפציהם."]]],[2000470424,"הוא השפעה (ע' זח\"ג דרט\"ו ע\"א<sup data-n=\"3793\">9</sup> יו\"ד הוא ברית שהוא יסוד ע' במק\"מ שם ובפי' הרמ\"ז דרי\"ד ע\"ב וע' בק\"י<sup data-n=\"3794\">10</sup> ע' יו\"ד), וכאשר הוא\"ו נוטל היו\"ד ה\"ז וי (ע' בזח\"ג דע\"ד ע\"ב ובמק\"מ שם, וע' בפרד\"ס<sup data-n=\"3795\">11</sup> בערכי הכינוים ע' וי ובק\"י ע' וי). וזהו ע\"ד מ\"ש בנביאים פעמים הוי<sup data-n=\"3796\">13</sup> ופעמים<sup data-n=\"3797\">14</sup> אוי<sup data-n=\"3798\">12</sup>, והוא ע\"ד מ\"ש אנכי הסתר אסתיר<sup data-n=\"3799\">15</sup> פני ביום ההוא (ע' בפרד\"ס ע' אוי), דהנה אי' בזהר קוב\"ה בגלותא סליק לעילא ולעילא<sup data-n=\"3800\">16</sup>, לעילא הוא כשנסתלק בבינה וזהו הסתיר בה\"א לעילא ולעילא הוא כשנסתלק בכתר וזהו אסתיר באל\"ף ומשם אפשר שיהי' וי שאינו תופס מקום כלל אם צדקת מה תתן לו<sup data-n=\"3801\">17</sup> ורבו פשעיך מה תעשה לו אם חטאת מה תפעל בו<sup data-n=\"3802\">18</sup> ומה מידך יקח<sup data-n=\"3803\">19</sup>.\n<b>וזהו</b> המלך מהודו ועד כוש<sup data-n=\"3804\">20</sup>, ואי' פלוגתא בגמ' ח\"א הודו בסוף העולם וכוש בסוף העולם וח\"א הודו וכוש כי הדדי נינהו וכמו שמלך על הודו וכוש כן מלך על כל העולם. דהודו הו\"ע הודאה שלמעלה מהשגה ואינו שייך שישיג כ\"א הודאה לבד, וכוש הוא אלביש שמים קדרות ושק אשים כסותו<sup data-n=\"3805\">21</sup>, וזהו שאמר שהם מסוף העולם ועד סוף העולם<sup data-n=\"3806\">22</sup>, וח\"א כי הדדי נינהו דכוש הוא כמ\"ש ישת חשך סתרו<sup data-n=\"3807\">23</sup> וכמ\"ש הלא כבני כושיים<sup data-n=\"3808\">24</sup> כמו שאומרים על מי שהוא לבן ביותר כושי<sup data-n=\"3809\">25</sup>",[["3793","9","<b>ע\"א</b>: באוה\"ת כאן: ב'."],["3794","10","<b>בק\"י</b>: בקהלת יעקב."],["3795","11","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה גם לעיל המשך זאת חנוכת המזבח ובהערה 267."],["3796","13","<b>בנביאים. . הוי</b>: מלכים-א יג, כ. ראה מדרש תהלים — באבער — א, ח עשרים הוי כתוב בישעי' (ובהנסמן שם). הוספה לתהלים (קה\"ת) תשט\"ו ע' 4 ואילך. נדפס גם באוה\"ת נ\"ך כרך ב ע' תתקיא."],["3797","14","<b>בנביאים. . אוי</b>: ישעי' ג, ט. יא. ועוד."],["3798","12","<b>ע\"ד. . הוי ופעמים אוי</b>: ראה זהר אחרי שם דע\"ד סע\"ב ואילך. אוה\"ת שה\"ש כרך ב ע' תשד. סה\"מ תרכ\"ז ע' רצה. וש\"נ."],["3799","15","<b>אנכי הסתר אסתיר</b>: לקמן ואנכי[ednref_225_ג], ואולי גם כאן צ\"ל כן — וילך לא, יח. ראה גם סה\"מ תרכ\"ז שם."],["3800","16","<b>קוב\"ה. . לעילא ולעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 10. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע על יד הערה 46. מאמרי אדה\"א קונטרסים ע' שסג. וש\"נ. תו\"ח שמות ח\"א לט, סע\"א ואילך ובהערה 72. סה\"מ תרע\"ח ע' שסז."],["3801","17","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["3802","18","<b>ורבו. . אם חטאת מה תפעל בו</b>: איוב שם, ו [בהיפך הסדר — ראה גם סה\"מ תרל\"ח ע' תיג. וש\"נ]."],["3803","19","<b>ומה מידך יקח</b>: סיום הכתוב אם צדקת [ושם: או מה — ראה גם לקמן הנחה ד\"ה סמוכים לעד על יד הערה 11. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה עשה צדקה ומשפט על יד הערה 71. ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 14. ד\"ה אשריכם זורעי על כל מים על יד הערה 106. סה\"מ תרל\"ח שם. וש\"נ]."],["3804","20","<b>המולך מהודו ועד כוש</b>: אסתר א, א. ראה מגילה יא, א. לקו\"ת שה\"ש ו, ב."],["3805","21","<b>אלביש שמים. . כסותו</b>: ישעי' נ, ג [ושם: כסותם]."],["3806","22","<b>שהם מסוף. . סוף העולם</b>: ראה הלשון לעיל בפנים."],["3807","23","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["3808","24","<b>הלא כבני כושיים</b>: עמוס ט, ז."],["3809","25","<b>שאומרים על. . לבן ביותר כושי</b>: בלקו\"ת שה\"ש כאן מציין לרש\"י בהעלותך [יב, א] ולזהר תרומה דק\"ל ריש ע\"א [ומעתיק לשונו].\n\n[edn_225_ג] ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה איתא וכו' נו\"כ על יד הערה 34. בהנחה כאן על יד הערה 9."]]],[2000470425,"כמו\"כ כאן מפני הריבוי אור נק' כו\"ש וא\"כ כי הדדי נינהו, וכמו שמלך מהודו ועד כוש כן מסוף כו', ומצד בחי' זו אפשר שיהי' וי, וזהו שאחשורוש נתן תחילה הטבעת להמן ואח\"כ נתן למרדכי<sup data-n=\"3810\">26</sup> והוא מפני שאינו נוגע כלל, ומה שהי' הגאולה הוא ע\"י המס\"נ שלמדו תורה במס\"נ וזהו מה ראו על ככה<sup data-n=\"3811\">27</sup> ומה הגיע אליהם שהו\"ע המס\"נ דמתוך ההסתר יכולים לבוא למדרי' היותר עליונה.\n<b>ולכן</b> כל מגילות<sup data-n=\"3812\">28</sup> אסתר הכל ברמז ולא יש שם הוי' בכל מג\"א<sup data-n=\"3813\">29</sup> רק בר\"ת כמו י'בוא ה'מלך ו'המן ה'יום הוי' בר\"ת<sup data-n=\"3814\">30</sup> ואח\"כ י'בוא ה'מלך ו'המן<sup data-n=\"3815\">31</sup> י' ה' ו' בר\"ת והוא שהגביה את המן<sup data-n=\"3816\">32</sup> כדי שיהי' משם אורידך נאום ה'<sup data-n=\"3817\">33</sup>, ברמז יש הכל במג\"א כמו מרדכי מירא דכיא<sup data-n=\"3818\">34</sup>, וזהו ואנכי הסתר אסתיר פני שהו\"ע ההסתר אך העיקר הוא מתוך ההסתר יכולים לבוא למדרי' היותר עליונה, וזהו וקיבלו היהודים את אשר החלו לעשות<sup data-n=\"3819\">35</sup> במ\"ת הי' רק התחלה ובימי אחשורוש הי' גמר הקבלה<sup data-n=\"3820\">36</sup>, והוא ע\"י המס\"נ, וזהו ויהי בימי אחשורוש<sup data-n=\"3821\">37</sup> מי שאחרית וראשית שלו ומצד מקום זה אינו תופס מקום כלל ואפ\"ל וי כנ\"ל, אך ע\"י המס\"נ היתה הגאולה וזהו וקיבלו היהודים את אשר החלו לעשות שמ\"ת הי' רק ההתחלה ואח\"כ ע\"י המס\"נ הי' גמר הקבלה כו'.",[["3810","26","<b>שאחשורוש נתן. . הטבעת להמן. . למרדכי</b>: אסתר ג, י. ח, ב."],["3811","27","<b>מה ראו על ככה</b>: אסתר ט, כו [ושם: ומה]."],["3812","28","<b>מגילות</b>: אוצ\"ל: מגילת."],["3813","29","<b>ולא יש שם הוי' בכל מג\"א</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 29. מאמרי אדה\"ז תקס\"ה ח\"א ע' שצז ואילך. אוה\"ת מג\"א [מהדורת תש\"נ] ע' דש ואילך. ע' רעח. סה\"מ תרכ\"ח ע' קח ואילך. תו\"א מג\"א ק, ב. קכא, רע\"ג. מאמרי אדה\"א נ\"ך ע' שנט. ע' תצג. אגרת פורים תרפ\"ט (נדפס ברשימות חוב' ו' ע' 8 ואילך). סה\"מ מלוקט ה' ע' קצ. לקו\"ש פורים כרך כא ע' 201 ובהערות שם."],["3814","30","<b>י'בוא ה'מלך ו'המן ה'יום הוי' בר\"ת</b>: אסתר ה, ד ובמנות הלוי שם. פע\"ח שער הפורים שי\"ט, פ\"ו. מ\"ח מסכת אדר פ\"ז, מ\"ה. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקלא. וש\"נ. נ\"ך ע' שעא. ע' תקה. אוה\"ת מג\"א [מהדורת תש\"נ] ע' קצ. סה\"מ תרכ\"ז ע' קצב. תרכ\"ח שם. תש\"ט ע' 58."],["3815","31","<b>י'בוא ה'מלך ו'המן</b>: אסתר שם, ח. ראה גם סה\"מ תרכ\"ז ותרכ\"ח שם. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 29."],["3816","32","<b>שהגביה את המן</b>: ראה תו\"א מג\"א צג, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע שפב ואילך. תקס\"ה ח\"א ע' תג ואילך. מאמרי אדה\"א נ\"ך ע' שעא. ע' תקה ואילך. ע' תקיא ואילך."],["3817","33","<b>משם אורידך נאום ה'</b>: עובדי' א, ד."],["3818","34","<b>מרדכי מירא דכיא</b>: ראה חולין קלט, ב."],["3819","35","<b>וקיבלו היהודים. . לעשות</b>: אסתר ט, כג [ושם: וקבל[ednref_226_ד]]. ראה שבת פח, א. תו\"א מג\"א צו, ג. הנסמן בסה\"מ תרכ\"ז כאן ע' קצב. לקמן הנחה ד\"ה צאינה וראינה על יד הערה 33. (בחלק ההנחות) בהנחה כאן על יד הערה 36. לעיל (בחלק המאמרים) המשך מצה זו רפכ\"ו."],["3820","36","<b>ובימי אחשורוש הי' גמר הקבלה</b>: ראה סה\"מ מלוקט ג' ע' סז בשולי הגליון."],["3821","37","<b>וזהו ויהי בימי אחשורוש</b>: ראה גם סה\"מ תרס\"ט ע' קנה.\n\n[edn_226_ד] ראה גם בסמוך בפנים. לקמן הנחה ד\"ה צאינה וראינה על יד הערה 33. לעיל (בחלק המאמרים) המשך מצה זו על יד הערה 871."]]],[2000470426,"<h3>הנה אנכי כורת ברית</h3>\n<b>ש\"פ תשא תר\"ם לפ\"ק</b>\n<b>הנה</b> אנכי כורת ברית<sup data-n=\"3822\">1</sup> נגד כל עמך אעשה נפלאות אשר לא נבראו בכל הארץ<sup data-n=\"3823\">2</sup> כו', ומקשים וכ\"מ מרמב\"ן אומרו אעשה נפלאות והלא לא היו נפלאות עוד גדולים מהראשונים והלא עיקר הנפלאות היו קודם מ\"ת<sup data-n=\"3824\">3</sup>, יצי\"מ וקרי\"ס ומן ומ\"ת, גם צ\"ל אומרו אשר לא נבראו בכל הארץ משמע שהי' קודם נבראו<sup data-n=\"3825\">4</sup> בארץ מה שייך נפלאות לבריאה<sup data-n=\"3826\">5</sup>, ומה שייכו' לארץ<sup data-n=\"3827\">6</sup>. והנה להבין כ\"ז צ\"ל תחילה מהו הכריתות ברית שהי' עם משה והלא כבר הי' כריתות ברית עם אברהם וכמ\"ש ביום ההוא כרת ה' את אברם ברית לזרעך אתן את הארץ<sup data-n=\"3828\">7</sup>, וענין הכריתות ברית הוא הגם שהשכל יחייב שיהי' באופן אחר מ\"מ יהי' כך וכך<sup data-n=\"3829\">8</sup>, ומה צריכים עוד כריתות או שדי הראשון או שאינו צריכים גם השני. והנה צ\"ל תחילה ענין ירידת הנשמה דלכאורה הוא ירידה שאינו מושג העלי' דהנה הנשמה כמו שהי' למעלה כתיב חי הוי' אשר עמדתי לפניו<sup data-n=\"3830\">9</sup> שעמדה באהוי\"ר וביטול לאלקות דאינו שייך עמידה למעלה כ\"א בביטול וכמו שרפים עומדים<sup data-n=\"3831\">10</sup>, ויעמידם לעד לעולם<sup data-n=\"3832\">11</sup>, וירדה למטה בגוף ונה\"ב המעלים ומסתיר ה\"ז ירידה גדולה ועצומה ומהו העלי'. והענין דהנה כתי' ואנשי קדש תהיון לי<sup data-n=\"3833\">12</sup> שע\"י מצות נכלל בקדש העליון.\n<b>והנה</b> צ\"ל תחילה עבודת המלאכים ולכאו' מה שייך גבי מלאכים עבודה דכלום יצה\"ר יש בהם<sup data-n=\"3834\">13</sup> ועוד הגם שיש להם גוף<sup data-n=\"3835\">14</sup> ה\"ה מב' יסודות וכמ\"ש עושה",[["3822","1","<b>הנה אנכי כורת ברית</b>: ממאמר זה ישנם שתי הנחות: א) הנחת<sup data-n=\"e227\">*</sup> כ\"ק אדמו\"ר מהורש\"ב והיא הנדפסת כאן. ב) הנחה אחרת ממאמר זה והיא נדפסה לקמן (בחלק ההנחות).\nמאמר ד\"ה זה בסה\"מ פר\"ת ע' שא ואילך (והנחה שם ע' שיד ואילך) בחלקו מיוסד על מאמר ד\"ה זה. וראה גם הדרושים שבהערה 3."],["3823","2","<b>הנה אנכי. . בכל הארץ</b>: תשא לד, י."],["3824","3","<b>ומקשים. . מ\"ת</b>: בסה\"מ פר\"ת כאן: והקשה הרמב\"ן. ראה גם רקאנטי כאן. אוה\"ת תשא ע' ב'ז. כרך ח ע' ג'קטז. פלח הרמון תשא ע' רצו. סה\"מ תר\"ל ע' קב. תרנ\"ד ע' קעג."],["3825","4","<b>נבראו</b>: אוצ\"ל: שנבראו."],["3826","5","<b>מה שייך נפלאות לבריאה</b>: ראה גם אוה\"ת תשא ופלה\"ר סה\"מ פר\"ת שם."],["3827","6","<b>ומה שייכו' לארץ</b>: ראה גם אוה\"ת תשא סה\"מ פר\"ת (ובהנחה שם) שם."],["3828","7","<b>ביום ההוא. . לזרעך אתן את הארץ</b>: לך טו, יח [ושם: לאמר לזרעך נתתי — ראה גם לקמן קרוב לסיום המאמר. סה\"מ פר\"ת ע' שב. ע' דש. ע' שיד. מאמרי אדה\"א דברים ח\"א ע' ג]."],["3829","8","<b>הכריתות ברית. . יהי' כך וכך</b>: ראה תו\"א לך יג, ג ואילך. בהדרושים שבהערה 3. הנסמן במאמרי אדה\"א דברים ח\"א ע' רפט."],["3830","9","<b>חי הוי' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["3831","10","<b>שרפים עומדים</b>: ישעי' ו, ב. ראה גם לעיל שם. וש\"נ."],["3832","11","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א. וש\"נ."],["3833","12","<b>ואנשי קדש תהיון לי</b>: משפטים כב, ל. ראה לקו\"ת בהעלותך ל, סע\"ג ואילך. יו\"כ סט, ב."],["3834","13","<b>דכלום יצה\"ר יש בהם</b>: ע\"פ שבת פט, א."],["3835","14","<b>שיש להם גוף</b>: ראה לקו\"ת בהר מא, ב. מאמרי אדה\"א בראשית ע' קיב. וש\"נ. לעיל הנחה ד\"ה ואתה תצוה ובהערה 18."],["e227","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470427,"מלאכיו רוחות<sup data-n=\"3836\">15</sup> משרתיו אש שהם ב' יסודות הדקין, ועבודה הוא כמו עורות עבודין<sup data-n=\"3837\">16</sup> היינו להפוך ממה שהי' קודם, ומלאכים הבריאה שלהם היא שיהי' בטל א\"כ מה שייך גביהם עבודה, ומצינו עבודה במלאכים דמלאכים אומרים קדוש ועומדים אח\"כ ד' שעות בביטל, די\"ב שעות הוה יומא<sup data-n=\"3838\">18</sup> אומרים ג\"פ קדוש<sup data-n=\"3839\">17</sup>, וזהו עבודה שלהם ולכאו' עבודה<sup data-n=\"3840\">19</sup> במלאכים, והענין דהנה כתי' בדבר ה' שמים נעשו<sup data-n=\"3841\">20</sup> וברוח פיו כל צבאיו<sup data-n=\"3842\">21</sup>, כל צבאיו הם מרוח פיו, דהנה מחו\"ד הם ב' לבושי הנפש<sup data-n=\"3843\">22</sup> אך הדבור הוא נפרד, הגם שגם הדיבור אינו נפרד באמת אפי' במשל וראי' שע\"י הדיבור נעשה הזולת מחובר ע\"י ואינו שייך לומר שהוא עצמו נפרד והוא מחבר זולתו, ויש בזה אריכות דברים ונתב' במ\"א (בד\"ה וככה<sup data-n=\"3844\">23</sup> ע' פרק פ'<sup data-n=\"3845\">24</sup> ), אך נראה כמו שהוא נפרד, ומלאכים נתהוו ע\"י הדיבור<sup data-n=\"3846\">25</sup> א\"כ הם נפרדים הגם שבאמת אינו נפרד אך נראה כמו שהוא נפרד, והעבודה שלהם הוא ע\"ד מ\"ש יחוד קוב\"ה ושכינתי'<sup data-n=\"3847\">26</sup> שכינתא הוא ממכ\"ע שהוא רק הארה בעלמא, וקוב\"ה הוא א\"ס הסוכ\"ע, ויחוד קוב\"ה ושכינתא הוא שיומשך סוכ\"ע בממכ\"ע, כמו\"כ עבודתם להמשיך מא\"ס שקדוש ומובדל מגדר עולמות וכל העולמות הם רק הארה כו' דהנה המלאכים הם מדיבור והנה אנו רואין שהאדם לצורך עצמו א\"צ להדיבור כלל רק לזולתו, דמח' הוא לצורך עצמו שעצם כחות הנפש כמה<sup data-n=\"3848\">27</sup> שמתגלים בהגוף הוא ע\"י המח', אבל דיבור הוא רק לזולתו, ומלאכים נתהוו מהדיבור ומה שיש בהם ביטל הוא ביטל היש, והעבודה שיומשך בהם ביטל אמיתי, והוא בחי' מ\"ה דחכ' כמ\"ש ואנחנו מ\"ה<sup data-n=\"3849\">29</sup>,",[["3836","15","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד."],["3837","16","<b>ועבודה. . עורות עבודין</b>: ראה שבת מט, ב. תו\"ח יתרו ח\"ב רסח, ב. וש\"נ. סה\"מ תרל\"ח ע' שפ. וש\"נ."],["3838","18","<b>די\"ב שעות הוה יומא</b>: ראה ע\"ז ג, ב."],["3839","17","<b>דמלאכים אומרים קדוש. . ד' שעות. . ג\"פ קדוש</b>: ישעי' ו, ג. ראה לקו\"ת שה\"ש כט, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקע\"א ע' קפה. מאמרי אדה\"א נ\"ך ע' שלו. וש\"נ. קונטרסים ע' רמז."],["3840","19","<b>ולכאו' עבודה</b>: אוצ\"ל: ולכאו' איך שייך עבודה."],["3841","20","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו. ראה גם סה\"מ פר\"ת כאן ע' שב."],["3842","21","<b>צבאיו</b>: אוצ\"ל: צבאם."],["3843","22","<b>מחו\"ד. . לבושי הנפש</b>: ראה תניא פ\"ד."],["3844","23","<b>הדיבור אינו נפרד. . בד\"ה וככה</b>: המשך וככה תרל\"ז."],["3845","24","<b>פרק פ'</b>: ראה שם פע\"ט. לקמן (בחלק ההנחות) בהנחה כאן פיסקא וע\"ד."],["3846","25","<b>ומלאכים נתהוו ע\"י הדיבור</b>: ראה אגה\"ת פ\"ד. ש\"א ח, ב ובהערה 39."],["3847","26","<b>יחוד קוב\"ה ושכינתי'</b>: ראה גם לקמן הנחה ד\"ה וירא העם וינועו על יד הערה 87 ואילך. תו\"ח וארא ח\"א נא, ג. המשך וככה תרל\"ז פכ\"ו ע' לג."],["3848","27","<b>כמה</b>: אוצ\"ל: כמו."],["3849","29","<b>ואנחנו מ\"ה</b>: בשלח טז, ז. ח [ושם: ונחנו — אבל עד\"ז מובא בעוד מקומות[ednref_228_א]]. ראה גם מאמרי אדה\"א בראשית ע' כב. וש\"נ. תו\"ח שמות ח\"א מג, א. וש\"נ.\n\n[edn_228_א] ומהם — ראה גם לעיל הנחה ד\"ה ויהי הענן והחשך על יד הערה 35. לקמן הנחה ד\"ה צאינה וראינה על יד הערה 102. (בחלק ההנחות) הנחה ד\"ה וביום הביכורים על יד הערה 76. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 142. מאמרי אדה\"א הנחות תקע\"ז ע' כו. וש\"נ. סה\"מ תרל\"ח ע' תסח. וש\"נ."]]],[2000470428,"והוא בחי' קדש, אך מפני שקדש הוא מילי' בגרמי'<sup data-n=\"3850\">28</sup> לכן ממשיכים קדוש וא\"ו מקדש<sup data-n=\"3851\">30</sup>, אבל נשמות הנה ארז\"ל ישראל עלו במח'<sup data-n=\"3852\">31</sup> ששרשם מהמח' שהוא גילוי העלם העצמי לגבי עצמו, אך מ\"מ הוא רק לבוש ואינו עצם וע\"י המצות שהו\"ע אשר קדשנו במצותיו וצונו<sup data-n=\"3853\">32</sup> עי\"ז נכלל בקדש העליון לאשתאבא בגופא דמלכא<sup data-n=\"3854\">33</sup>, דהנה המצות הם רצה\"ע ונתלבשו בדברים גשמי' ציצית בצמר גשמי ותפילין בקלף גשמי ד\"מ שבלולב בצמחים גשמים, ושרשם בעולם התהו שקדם לתיקון<sup data-n=\"3855\">34</sup> וע\"י מה שעושה אותה מצוה מברר הגוף והנה\"ב, דהנה הנה\"ב מונע ומעכב כל דבר והגוף הוא ממשכא דחוויא<sup data-n=\"3856\">35</sup> ועי\"ז מברר הגוף וגם הנה\"ב לכן נכלל עי\"ז בקדש העליון. וזהו העלי' של נשמות.\n<b>והנה</b> המצות הם זריעה<sup data-n=\"3857\">36</sup> וכמ\"ש אור זרוע לצדיק<sup data-n=\"3858\">37</sup> זרע הקב\"ה את התורה והמצות להנחילן לישראל לעוה\"ב<sup data-n=\"3859\">38</sup> וכמ\"ש אור זרוע כו', וכתי' אשריכם זורעי על כל מים<sup data-n=\"3860\">39</sup>, זרעו לכם צדקה וקצרו לפי חסד<sup data-n=\"3861\">40</sup>, ויזרע יצחק בארץ ההוא וימצא מאה שערים<sup data-n=\"3862\">41</sup>, דהנה כשזורעין גרעין הרי אין בו לא טעם ולא ריח וממנו נצמח אילן וענפים ופירות ועלים, וצ\"ל שהכל הי' בהגרעין אפי' הפרי<sup data-n=\"3863\">42</sup> ג\"כ וראי'",[["3850","28","<b>דחכ'. . שקדש הוא מילי' בגרמי'</b>: ראה זהר אמור צד, ב. לקו\"ת מסעי צג, א. מאמרי אדה\"א דברים ח\"ג ע' תתקב."],["3851","30","<b>קדוש וא\"ו מקדש</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' רסג. וש\"נ. תו\"ח וארא ח\"א נח, ב. וש\"נ. ראה גם לקמן הנחה ד\"ה וירא העם וינועו על יד הערה 62 ואילך. ד\"ה וביום הביכורים על יד הערה 16 ואילך. (בחלק ההנחות) הנחה ד\"ה וביום הביכורים על יד הערה 23 ואילך. ד\"ה ויאמר משה על יד הערה 19. (לעיל בחלק המאמרים) המשך מצה זו רפכ\"ט."],["3852","31","<b>ישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. לקו\"ת בחוקותי מז, א. שה\"ש טז, ד. יט, ב. יז, ד. יח, ב. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["3853","32","<b>אשר קדשנו במצותיו וצונו</b>: נוסח ברכת המצות. ראה תניא פמ\"ו. סה\"מ תרל\"ח ע' תעז. וש\"נ."],["3854","33","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 51."],["3855","34","<b>התהו שקדם לתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת הערה 51."],["3856","35","<b>ממשכא דחוויא</b>: ראה תניא פל\"א (מ, ב) ובמ\"מ הגהות והע\"ק שם. ס' שיעורים בספר התניא כאן (פמ\"ה) ע' 613 הערה 3. הנסמן באוה\"ת חוקת כרך ו ע' א'תתצג מאמרי אדה\"א נ\"ך ע' תלד."],["3857","36","<b>המצות הם זריעה</b>: ראה תו\"א שמות נג, ג. ראה גם להמובא בסמוך אוה\"ת תשא ע' ב'ח."],["3858","37","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["3859","38","<b>זרע הקב\"ה. . לישראל לעוה\"ב</b>: לעיל (בחלק המאמרים) בהמשך מצה זו על יד הערה 1822 מציין: במד\"ר ס\"פ שלח. וש\"נ. ראה גם לעיל הנחה ד\"ה בן פורת יוסף הא' על יד הערה 47 ואילך."],["3860","39","<b>אשריכם זורעי על כל מים</b>: ישעי' לב, כ."],["3861","40","<b>זרעו לכם צדקה וקצרו לפי חסד</b>: הושע י, יב [ושם: לצדקה. קצרו — אבל עד\"ז מובא בעוד מקומות[ednref_229_ב]]."],["3862","41","<b>ויזרע יצחק. . שערים</b>: תולדות כו, יב [בדילוג]."],["3863","42","<b>שהכל הי' בהגרעין אפי' הפרי</b>: ראה גם תו\"ח בראשית כח, ג ובהערה 37. שער האמונה צב, א ובהערה 7.\n\n[edn_229_ב] <b>ומהם</b>: לקמן ח\"ב בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אשריכם זורעי על כל מים על יד הערה 40. מאמרי אדה\"א ויקרא ח\"ב ע' תשטז. וש\"נ. תו\"ח וארא ח\"א פב, ב ובהערה 666."]]],[2000470429,"שאם לא יזרע לא יצמח, ואם יזרע גרעין זה יצמח ממנו פרי זו כו' אלא שהוא בהעלם ואח\"כ יוצא מהעלם אל הגילוי, כמו\"כ הם<sup data-n=\"3864\">43</sup> כמו הגרעין שיש בהם האורות עליונים תפילין ד' מוחין<sup data-n=\"3865\">44</sup> ציצית ל\"ב נת\"ח<sup data-n=\"3866\">45</sup>, אלא שהם בהעלם וצריכים להמשיך מהעלם אל הגילוי, והנה הזריעה צ\"ל בארץ דוקא, כמו\"כ הנה כתיב דור הולך ודור בא והארץ לעולם עומדת<sup data-n=\"3867\">46</sup> קאי על נש\"י שנק' ארץ חפץ<sup data-n=\"3868\">47</sup> ששם מתגלה חפץ העליון, דדוקא כשישראל עושה<sup data-n=\"3869\">48</sup> ממשיך המשכת אלקות וכמ\"ש מגיד דבריו ליעקב<sup data-n=\"3870\">49</sup> חוקיו ומשפטיו לישראל לא עשה כן<sup data-n=\"3871\">50</sup> כו', וזהו ה' חפץ למען צדקו<sup data-n=\"3872\">51</sup> יגדיל תורה ויאדיר כדי שיהי' הגדלות התורה וצדקו הם כללות כל המצות וכמ\"ש וצדקה תהי' לנו<sup data-n=\"3873\">52</sup> כי נשמור לעשות כל המצוה הזאת שהם חפץ ה' הוא ע\"י זריעה דוקא.\n<b>וזה</b> הי' הכריתות ברית עם אברהם<sup data-n=\"3874\">53</sup> שיהיו ישראל ארץ חפץ ויהי' בם הזריעה ואח\"כ יהי' הצמיחה, אבל בזמן הגלות שאין מקיימים תומ\"צ<sup data-n=\"3875\">54</sup> שאז אינם נק' ארץ חפץ אל יאמר נואש אלא אין לך דבר שעומד בפני התשו'<sup data-n=\"3876\">55</sup> וזהו הכריתות ברית עם<sup data-n=\"3877\">56</sup>, והוא במדריגה היותר עליונה וכמארז\"ל ברית כרותה למדה\"ר<sup data-n=\"3878\">57</sup> שאינן חוזרות מלפני ריקם והו\"ע נושא עון ועובר על פשע<sup data-n=\"3879\">58</sup>, וזהו שיהי' ונפלינו אני ועמך<sup data-n=\"3880\">59</sup>, וזהו שא' וזכרתי את בריתי יעקב כו' ואת האר\"ץ אזכור<sup data-n=\"3881\">60</sup>, שיהיו נק' ארץ, ואף גם זאת<sup data-n=\"3882\">61</sup> כו' וזכרתי להם ברית ראשונים<sup data-n=\"3883\">62</sup> ולא נא' ארץ שכריתות ברית זה הוא",[["3864","43","<b>כמו\"כ הם</b>: אוצ\"ל: כמו\"כ המצות הם."],["3865","44","<b>תפילין ד' מוחין</b>: ראה זהר ואתחנן רסב, א. סידור שער התפילין ז, א. אמרי בינה שער התפילין קיב, א ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ד ע' א'רמא. וש\"נ."],["3866","45","<b>ציצית ל\"ב נת\"ח</b>: ראה זח\"ג תוספת שא, א. בחיי שלח טו, לח ד\"ה וע\"ד הקבלה (ירושלים תשל\"ב ס\"ע קא). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקטז ובהנסמן במ\"מ לשם. לקו\"ת קרח נב, ב. ד."],["3867","46","<b>דור הולך. . עומדת</b>: קהלת א, ד. קה\"ר שם (פיסקא והארץ)."],["3868","47","<b>ארץ חפץ</b>: מלאכי ג, יב."],["3869","48","<b>דדוקא כשישראל עושה</b>: ראה תו\"א שמות נג, ד. לעיל הנחה ד\"ה בן פורת יוסף הא' ובהערות 54. 57."],["3870","49","<b>מגיד דבריו ליעקב</b>: תהלים קמז, יט."],["3871","50","<b>לא עשה כן</b>: תהלים שם, כ."],["3872","51","<b>ה' חפץ למען צדקו</b>: ישעי' מב, כא."],["3873","52","<b>כל המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה [ושם: את כל]. ראה לעיל (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 65."],["3874","53","<b>הכריתות ברית עם אברהם. . ברית עם משה</b>: ראה גם אוה\"ת תשא ע' א'תתמח. ב'ט ואילך. כרך ח ע' ג'קיז ואילך. פלח הרמון תשא ע' רצט ואילך. ע' שא ואילך. סה\"מ תר\"ל ע' קה ואילך. תרנ\"ד ע' קעז ואילך. סה\"מ פר\"ת כאן ע' שטז ואילך."],["3875","54","<b>אברהם. . מקיימים תומ\"צ</b>: להעיר משע\"ת קלג, א."],["3876","55","<b>אין לך דבר שעומד בפני התשו'</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. לקו\"ש בא כרך ו ע' 66 הערה 54."],["3877","56","<b>עם</b>: אוצ\"ל: עם משה."],["3878","57","<b>ברית כרותה למדה\"ר</b>: ראה ר\"ה יז, ב."],["3879","58","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["3880","59","<b>ונפלינו אני ועמך</b>: תשא לג, טז."],["3881","60","<b>וזכרתי את בריתי. . אזכור</b>: בחוקותי כו, מב [ושם: והארץ]."],["3882","61","<b>ואף גם זאת</b>: בחוקותי שם, מד."],["3883","62","<b>וזכרתי להם ברית ראשונים</b>: שם כו, מה. ראה אוה\"ת תשא כאן ס\"ע ב'ט ואילך. כרך ח ע' ג'קיז. ע' ג'קיט."]]],[2000470430,"אף שלא יהי' ארץ חפץ מ\"מ לא מאסתים כו', וזהו ש' ביום ההוא כרת ה' את אברם ברית לזרעך אתן האר\"ץ, וזהו כי כארץ תוציא צמחה<sup data-n=\"3884\">63</sup> וכגנה זרועי' תצמיח כן אד' ה' יצמיח צדקה ותהלה, כי כארץ תוציא צמחה הו\"ע הכריתות ברית עם אברהם וכגנה זרועה זרועי'<sup data-n=\"3885\">64</sup> תצמיח ג\"כ כנ\"ל, אך מה ש' כי כארץ<sup data-n=\"3886\">65</sup> הם מצות בלא כוונה ומ\"ש וכגנה כו' הם מצות בכוונה כמו גנה שזורעין בה אילנות משובחים, אך מי שפגם ואינו נק' ארץ חפץ כן אד' ה' יצמיח צדקה ותהלה הוא הכריתות ברית עם משה.\n<b>וזהו</b> אעשה נפלאו\"ת שהוא מבחי' פלא, וזהו אעשה נפלאות אשר לא נבראו כו' דהנה הניסים שהיו קודם מ\"ת היו הכנה למ\"ת, ומ\"ת הוא הזריעה בארץ וזהו הכריתות ברית עם אברהם אבל אעשה נפלאות אשר לא נבראו בכל הארץ שאינם שייכים לארץ, וא\"כ הכריתות ברית הוא דבר חדש דהכריתות ברית עם אברהם הי' שיהיו ישראל ארץ חפץ ויהי' בהם הזריעה, ואח\"כ יהי' הצמיחה, אבל כשאינם נק' ארץ חפץ ומ\"מ יומשך המשכות אלקות זהו הכריתות ברית עם משה.",[["3884","63","<b>כי כארץ תוציא צמחה</b>: ישעי' סא, יא."],["3885","64","<b>זרועה זרועי'</b>: אוצ\"ל: זרועי'."],["3886","65","<b>כי כארץ</b>: ראה גם אוה\"ת תשא כאן ע' ב'י."]]],[2000470431,"<h3>גדולה מילה</h3>\n<b></b><b>יום ג' פ' ויק\"פ תר\"ם לפ\"ק על ב\"מ אצל רי\"ל בר\"ש</b>\n<b></b>יום ג' פ' ויק\"פ. . על ב\"מ אצל רי\"ל בר\"ש\n<b>גדולה</b> מילה<sup data-n=\"3887\">1</sup> שנכרתה עלי' י\"ג בריתות<sup data-n=\"3888\">2</sup>, וצ\"ל והלא כל התורה נכרת עלי' ג' בריתות<sup data-n=\"3889\">3</sup> ומילה שהיא פרט אחד מתורה נכרתה עלי' י\"ג בריתות ה\"ז תוס' מרובה על העיקר, והענין דהנה כתי' מ'י' י'עלה' ל'נו' ה'שמימה' הנה מילה בר\"ת והוי' בס\"ת<sup data-n=\"3890\">4</sup>, וגם זה צ\"ל מפני מילה<sup data-n=\"3891\">5</sup> הוא בר\"ת ושם הוי' בס\"ת. והענין הוא דהנה",[["3887","1","<b>גדולה מילה</b>: דרוש זה נמצא לפנינו בשתי הנחות א) הנחת<sup data-n=\"e230\">*</sup> כ\"ק אדמו\"ר מהורש\"ב והיא הנדפסת פה. ב) הנחה אחרת מדרוש זה ונדפסה לקמן (בחלק ההנחות).\nלמאמר זה ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' יב ואילך. אוה\"ת לך כרך ד ע' תשכה ואילך. סה\"מ תרכ\"ו ע' כו ואילך. תרל\"א (נמצא בדפוס). תרל\"ח ע' שפג ואילך.\nבהכותרת: רי\"ל בר\"ש — לע\"ע לא נתברר מי הוא. השוה גם הכותרת לקמן בהנחה השני' כאן."],["3888","2","<b>גדולה מילה. . י\"ג בריתות</b>: משנה נדרים לא, ב. וראה לקו\"ש לך כרך כה ע' 54 ואילך ובהערה 5. הערה הבאה."],["3889","3","<b>תורה. . ג' בריתות</b>: ברכות מח, סע\"ב ואילך. ראה גם סה\"מ תרכ\"ו ע' כג. תרל\"א (נמצא בדפוס). תרל\"ג ח\"ב ע' שצט. וע' תא."],["3890","4","<b>מ'י' י'עלה'. . מילה בר\"ת והוי' בס\"ת</b>: נצבים ל, יב. ראה בעה\"ט שם. ת\"ז בהקדמה ב, ב. תכ\"ב סה, ב. סו, א. ת\"ע קלא, רע\"א."],["3891","5","<b>מפני מילה</b>: אוצ\"ל: מפני מה מילה."],["e230","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470432,"משה אמר האזינו השמים<sup data-n=\"3892\">6</sup> ותשמע הארץ, וישעי' א' שמעו שמים<sup data-n=\"3893\">7</sup> והאזיני ארץ כמו משה, רק משה א' השמים כו' וישעי' א' שמים, וגם משה א' האזינו השמים כו' וישעי' א' שמעו שמים כו', אך אי' במד' מפני שמשה הי' קרוב לשמים וישעי' לארץ<sup data-n=\"3894\">8</sup> אבל מפני מה א' משה השמים וישעי' שמים.\n<b>והענין</b> דהנה השמים מקיף את הארץ דהארץ היא כגרגיר חרדל<sup data-n=\"3895\">9</sup> ובאמת נלאו החוקרים האיך הארץ עומד באויר<sup data-n=\"3896\">*10</sup> וזה אומר בכה וזה אומר בכה, והעיקר דהנה כתי' אני אענה את השמים<sup data-n=\"3897\">10</sup> והם יענו את הארץ וכל חלק משפיע<sup data-n=\"3898\">11</sup> בארץ לכן תולה באויר, דהנה אנו רואין שהמדה מקפת את הדיבור<sup data-n=\"3899\">12</sup> כמו אהבה הנה כשהוא בהתפעלות עדיין אז המדה בתוקף ואינו יכול לדבר כלל<sup data-n=\"3900\">*13</sup> אך כשמתצמצם המדה אז מגלה האהבה וכשהוא מדבר מן השפה לחוץ אינו מתקבל אצל השומע רק כשמדבר באמת<sup data-n=\"3901\">13</sup> אז מתקבל א\"כ המדה מקפת את הדיבור, ולמעלה מדות ודיבור הם שמים וארץ<sup data-n=\"3902\">14</sup>, וכמו שהוא בשמים וארץ תתאין<sup data-n=\"3903\">15</sup> כמו\"כ יובן בשו\"א שלמעלה מהם והו\"ע השמים והארץ והו\"ע חו\"ב<sup data-n=\"3904\">16</sup> שהחכ' מקפת את הבינה דהנה בינה הוא",[["3892","6","<b>משה אמר האזינו השמים</b>: האזינו לב, א. ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 7. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויאמר כו' לך לך על יד הערה 77 ואילך. ובהנחה שם על יד הערה 102."],["3893","7","<b>וישעי' א' שמעו שמים</b>: ישעי' א, ב."],["3894","8","<b>שמשה. . לשמים וישעי' לארץ</b>: ראה ספרי ר\"פ האזינו. לקו\"ש האזינו כרך ט ע' 204 הערה 1 וראה גם שם בהערה 4."],["3895","9","<b>דהארץ היא כגרגיר חרדל</b>: ראה גם תו\"א בראשית ב, א. תו\"ח בראשית כא, ד ובהערה 34. סה\"מ תרל\"ח ע' שפד. וש\"נ. עטר\"ת ע' רע\"א."],["3896","*10","<b>נלאו החוקרים האיך הארץ עומד באויר</b>: השווה גם (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 12. ראה גם מאמר ד\"ה והנה להבין איך המקום בטל למעלה מן המקום מכ\"ק אדמו\"ר הצ\"צ — בבוך במדבר דברים רב\"ק[ednref_231_א]."],["3897","10","<b>אני אענה את השמים</b>: הושע ב, כג [בהוספת תיבת: אני — וכ\"ה בכ\"מ[ednref_232_ב]]."],["3898","11","<b>אני אענה. . משפיע</b>: ראה גם סידור שער ל\"ג בעומר שג, א. שה\"א לד, ב ובהערה 31."],["3899","12","<b>שהמדה מקפת את הדיבור</b>: ראה גם מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ג. סה\"מ תרכ\"ו ס\"ע כו ואילך. תרל\"ח ע' שפד."],["3900","*13","<b>המדה בתוקף ואינו יכול לדבר כלל</b>: ראה גם (לקמן בחלק ההנחות) בהנחה כאן ובהערה 16."],["3901","13","<b>וכשהוא מדבר. . באמת</b>: ראה ספר הישר לר\"ת שי\"ג. הובא של\"ה שער האותיות אות כ (סט, א). שירת ישראל לר' משה בן עזרא (ירושלים תשכ\"ז ע' קנו)."],["3902","14","<b>מדות ודיבור הם שמים וארץ</b>: ראה גם מאמרי אדה\"ז כאן ע' יג. אוה\"ת כאן תשכה, ב. מאמרי אדמו\"ר הצ\"צ הנ\"ל. סה\"מ תרכ\"ו כאן ע' כו. תרל\"ח כאן ע' שפד. מאמר ד\"ה ויאמר כו' לך לך שבהערה 6."],["3903","15","<b>בשמים וארץ תתאין</b>: באוה\"ת כאן תשכה סע\"א מציין לזהר ויקהל דרנ\"ו ע\"א. וכנצ\"ל: רט, א."],["3904","16","<b>השמים והארץ והו\"ע חו\"ב</b>: ראה גם מאמרי אדמו\"ר הצ\"צ מאמר ד\"ה ויאמר כו' לך לך הנ\"ל. המשך תער\"ב ח\"א ע' רסד. דרושים שבהערה 1.\n\n[edn_231_א] <b>בוך זה הוא הנחות של ר' דוב </b>[בעריל]<b> קאליסקער ממאמרי כ\"ק אדמו\"ר הצ\"צ ונק' בשם</b>: ”במדבר דברים רב\"ק\". ראה עוד ע\"ד הנ\"ל ב”ספריית ליובאוויטש\" ע' ל ואילך. ע' לז ואילך. נמצא גם בבוך 466 אחרי הדרושים דפ' בהעלותך ריש ע' סא.\n\n[edn_232_ב] ראה גם לעיל הנחה ד\"ה ויהי הענן והחשך על יד הערה 56. (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 13. מאמרי אדה\"א ויקרא ח\"א ע' קנה. וש\"נ. תו\"ח וארא ח\"א ס, ב. וש\"נ. סה\"מ תרל\"ח ע' קעז. וש\"נ."]]],[2000470433,"השגה והבנה והנה לא החכ' נמשכת בהשגה רק הארה ממנו שעצם החכ' נתצמצם רק גילוי ממנו וא\"כ החכ' מקפת הבינה, וזהו השמים חכ'<sup data-n=\"3905\">17</sup> והארץ בינה דכתי' התהלך<sup data-n=\"3906\">18</sup> לפני הוי' בארצות החיים<sup data-n=\"3907\">19</sup> שיש ב' ארצות ארץ עילאה וארץ תתאה<sup data-n=\"3908\">20</sup> ארץ תתאה מל' וארץ עילאה בינה<sup data-n=\"3909\">21</sup>, והנה יש עוד שמי השמים<sup data-n=\"3910\">*23</sup> שהוא למעלה משמי השמים והוא מקיף על כל המקיפים, וכאן נא' מי יעלה לנו השמימה<sup data-n=\"3911\">22</sup> כולל השמים וגם שמי השמים לכן מילה בר\"ת והוי' בס\"ת דהנה הוי' הוא מקור המהווה עולמות וזהו הוי' ל' מהווה<sup data-n=\"3912\">23</sup>, אבל מילה הוא מדרי' שמי השמים.\n<b>וזהו</b> גדולה מילה שנכרתה עלי' י\"ג בריתות, הנה תורה נכרתה עלי' ג' בריתות, דהנה הוא<sup data-n=\"3913\">24</sup> תורת הבריאה<sup data-n=\"3914\">25</sup> ולכן ג' בריתות כנגד ג' עולמות בי\"ע, אבל פרט מילה הוא מ\"ש ומלתם את ערלת לבבכם<sup data-n=\"3915\">26</sup> כמו שלמטה יש ערלה המעלים ומסתיר כמו\"כ הנה ארז\"ל י\"ג הבדלות הי' במקדש<sup data-n=\"3916\">27</sup> שהוא הבדלה המבדיל כמו ויבדל אהרן להקדישו קדה\"ק<sup data-n=\"3917\">28</sup> וכמ\"ש והבדילה הפרוכת לכם<sup data-n=\"3918\">29</sup> בין הקדש ובין קדה\"ק דקודש לגבי קדה\"ק הוא כמו השמים לגבי שמי השמים (ע' בד\"ה ת\"ח ברזא דשמא קדישא<sup data-n=\"3919\">30</sup> ), ואהרן הי' לקדה\"ק<sup data-n=\"3920\">31</sup> כמו\"כ ע\"י מילה מעבירים כל ההבדלות וזהו באיזה זכות הי' אהרן נכנס<sup data-n=\"3921\">32</sup> לקדה\"ק זכות המילה הי' נכנסת עמו, דמילה ג\"כ לפנים",[["3905","17","<b>השמים חכ'</b>: ראה אוה\"ת כאן ע' 1450 ואילך. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויאמר כו' לך לך ובהערה 82."],["3906","18","<b>התהלך</b>: וכ\"ה גם בפלח הרמון אמור ע' שעו. וכנצ\"ל: אתהלך."],["3907","19","<b>אתהלך לפני ה' בארצות החיים</b>: תהלים קטז, ט. ראה גם לעיל (בחלק המאמרים) המשך מצה זו פ\"ט על יד הערה 258. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ד\"ה ויאמר כו' לך לך על יד הערה 107."],["3908","20","<b>בארצות. . ב' ארצות ארץ עילאה וארץ תתאה</b>: מובא בשם הזהר במאמרי אדה\"א במדבר ח\"ב ע' תקעא. תו\"ח משפטים ח\"ב רצה, ב."],["3909","21","<b>בארצות. . מל'. . בינה</b>: ראה גם תו\"ח שם רצה, ג. וש\"נ."],["3910","*23","<b>שמי השמים</b>: אוצ\"ל: השמימה."],["3911","22","<b>שמי השמים. . שמי השמים. . השמימה</b>: ראה גם לקמן ח\"ב מאמר והנחה ד\"ה ויאמר כו' לך לך הנ\"ל. סה\"מ תרל\"ח כאן ע' שפד. דרושים שבהערה 1."],["3912","23","<b>הוי' ל' מהווה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים ש\"ד, ספ\"י. שער היחוה\"א פ\"ד. פ\"ז. הערה בסה\"מ ת\"ש ע' 40."],["3913","24","<b>דהנה הוא</b>: אוצ\"ל: דהנה תורתינו הוא."],["3914","25","<b>תורת הבריאה</b>: ראה גם לקו\"ת סוכות פא, ד: בלק\"ת [להאריז\"ל] בתחלת פ' בראשית שהתורה שלפניו[ednref_233_ג] נקרא תורת הבריאה. מאמרי אדה\"א ויקרא ח\"ב ע' תסו. וש\"נ. סה\"מ תרל\"ח ע' קנג ובהערות 950 — 947."],["3915","26","<b>ומלתם את ערלת לבבכם</b>: עקב י, טז."],["3916","27","<b>י\"ג הבדלות הי' במקדש</b>: ראה בסמוך בפנים: פרוכת — יומא נד, א. כתובות קו, א."],["3917","28","<b>ויבדל אהרן להקדישו קדה\"ק</b>: דבהי\"א כג, יג [ושם: קדשים]. ראה גם לעיל הנחה ד\"ה ויהי הענן והחשך על יד הערה 38."],["3918","29","<b>והבדילה הפרוכת לכם</b>: תרומה כו, לג."],["3919","30","<b>בד\"ה ת\"ח רזא דשמא קדישא</b>: ראה תו\"ח יתרו ח\"ב רסט, ג ובהנסמן בריש המאמר שם."],["3920","31","<b>ואהרן הי' לקדה\"ק</b>: אוצ\"ל: ואהרן הי' נכנס לקדה\"ק."],["3921","32","<b>באיזה זכות הי' אהרן נכנס</b>: ראה שמו\"ר פל\"ח, ח. וראה גם אוה\"ת אחרי ח\"א ס\"ע רפו ואילך. סה\"מ תר\"ל ע' קכו.\n\n[edn_233_ג] <b>אוצ\"ל</b>: שלפנינו. תיבה זו ליתא בלקו\"ת להאריז\"ל."]]],[2000470434,"מהי\"ג פרוכת, וזהו\"ע המילה שהו\"ע ומלתם את ערלת לבבכם עי\"ז אח\"כ ומל הוי' את לבבך<sup data-n=\"3922\">33</sup> הוא בחי' שמי השמים, וזהו גדולה מילה שנכרתה עלי' י\"ג בריתות.",[["3922","33","<b>ומל הוי' את לבבך</b>: נצבים ל, ו [ושם ה\"א]. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה עטרת תפארת שיבה על יד הערה 21 ואילך ובהנסמן שם."]]],[2000470435,"<h3>סמכוני באשישות</h3>\n<b>ש\"פ ויק\"פ תר\"ם לפ\"ק</b>\n<b>סמכוני</b> באשישות<sup data-n=\"3923\">1</sup> רפדוני בתפוחים כי<sup data-n=\"3924\">2</sup> חולת אהבה אני, הנה כנס\"י בזמן החורבן<sup data-n=\"3925\">4</sup> קוראים א\"ע<sup data-n=\"3926\">3</sup> בשם חולת אהבה וע\"ז מבקשים סמכוני באשישות כו', דהנה ענין חולת אהבה הוא מצד ההעדר כשרוצה איזה דבר ואינו יכול להשיג<sup data-n=\"3927\">5</sup> אותה. וכמ\"ש בגמ' מעשה בא' שהעלה בלבו טינא<sup data-n=\"3928\">6</sup> כו'. והנמשל הוא דהנה ישראל אומרים פעמים בכ\"י שמע<sup data-n=\"3929\">7</sup> ישראל כו' ואהבת את ה' אלקיך<sup data-n=\"3930\">9</sup>, שרש אהבה הוא אבה<sup data-n=\"3931\">10</sup> ל' רצון ותשוקה לאלקות שהוי' יהי' אלקיך אלוקה שלך<sup data-n=\"3932\">11</sup> שיהי' גילוי שם הוי' אך א\"א שיומשך עכשיו ומצד זה הוא החולת אהבה. אך לא בכל זמן כן דהנה אמרז\"ל שמש בשבת צדקה לעניים<sup data-n=\"3933\">12</sup> וכמ\"ש<sup data-n=\"3934\">13</sup> וזרחה לכם יראי שמי שמש צדקה מרפא כנפי'<sup data-n=\"3935\">14</sup>, דבשבת מאיר שם הוי'<sup data-n=\"3936\">15</sup> ולכן אחר שבת כתי' ביום עשות הוי'<sup data-n=\"3937\">16</sup> כו'",[["3923","1","<b>סמכוני באשישות</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים וש\"נ."],["3924","2","<b>סמכוני באשישות רפדוני בתפוחים</b>: שה\"ש ב, ה."],["3925","4","<b>בזמן החורבן</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 4."],["3926","3","<b>כנס\"י. . קוראים א\"ע</b>: ראה גם רש\"י שה\"ש שם. זהר שמיני מ, א."],["3927","5","<b>חולת אהבה. . ואינו יכול להשיג</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע ערב ואילך (נו\"ש). ע' רעג (נו\"א). סה\"מ תר\"ס ע' עז."],["3928","6","<b>מעשה בא'. . טינא</b>: סנהדרין עה, א."],["3929","7","<b>פעמים בכ\"י שמע</b>: ראה שו\"ע אדה\"ז הל' ק\"ש רסנ\"ח."],["3930","9","<b>ואהבת את ה' אלקיך</b>: ואתחנן שם, ה."],["3931","10","<b>שרש אהבה הוא אבה</b>: ראה ס' שרש ישע שרש אבה הובא בס' החקירה להצ\"צ מערכת אהב (צב, רע\"א[ednref_234_א]). מאמרי אדה\"א הנחות תקע\"ז ע' רסד. וש\"נ. תו\"ח בשלח ח\"א קצט, ב. וש\"נ. סה\"מ תרכ\"ז ע' עב. וש\"נ. לקמן הנחה ד\"ה וירא העם וינועו על יד הערה 82."],["3932","11","<b>שהוי' יהי' אלקיך אלוקה שלך[ednref_235_ב]</b>: ראה גם תו\"א תצוה פב, רע\"ג. לקו\"ת שה\"ש מב, ב. סה\"מ תרל\"ג ח\"ב ע' תמג וע' תנה. וככה תרל\"ז פכ\"ו ע' לג. תרל\"ח ע' שמב. לקמן בהנחה שם על יד הערה 83 ואילך."],["3933","12","<b>שמש בשבת צדקה לעניים</b>: תענית ח, ב. ראה סה\"מ תרצ\"ט ע' 232."],["3934","13","<b>וכמ\"ש</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות כאן הערה 12."],["3935","14","<b>וזרחה לכם. . מרפא כנפי'</b>: מלאכי ג, כ [ושם: ומרפא בכנפי']."],["3936","15","<b>דבשבת מאיר שם הוי'</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שיח. וש\"נ. תו\"ח בשלח ח\"א קמד, א הערה 21. יתרו ח\"ב רסו, ג. סה\"מ תרל\"ח ס\"ע נא ואילך."],["3937","16","<b>ביום עשות הוי'</b>: בראשית ב, ד.\n\n[edn_234_א] במהדורת אותיות מרובעות (תשס\"ג), צד, א.\n\n[edn_235_ב] ראה גם סה\"מ תרע\"ח ס\"ע קמ ואילך."]]],[2000470436,"ובאמת בשבת מאיר מדרי' שלמעל' משם הוי' וכמ\"ש אז תתענג<sup data-n=\"3938\">17</sup> על הוי'<sup data-n=\"3939\">18</sup> למעלה משם הוי', וזהו ישבעו ויתענגו מטובך<sup data-n=\"3940\">19</sup>, טוב העצמי ענג העצמי (וזהו מטובך לנוכח והו\"ע מ\"ש ורב טוב<sup data-n=\"3941\">20</sup> לבית ישראל<sup data-n=\"3942\">8</sup> וכתי' מה רב טובך<sup data-n=\"3943\">21</sup> אשר צפנת ליריאיו, צפנ\"ת בגימ' כתר<sup data-n=\"3944\">22</sup>, וכמו\"כ יש בכל יום מדרי' שבת והו\"ע התפלה<sup data-n=\"3945\">23</sup> וזהו שכ' אשרי תבחר ותקרב ישכון חצריך<sup data-n=\"3946\">25</sup> נשבעה בטו\"ב ביתך קדוש היכלך), ומצד העונג נתרפא החולת אהבה<sup data-n=\"3947\">24</sup>, וזהו שארז\"ל אינו דומה מאור פניו של אדם<sup data-n=\"3948\">26</sup> בשבת ממאור פניו של אדם בחול וזהו מצד העונג. אך בחול אז החולת אהבה, וזהו שמבקשים סמכוני באשישות רפדוני בתפוחים כמו חולה סומכין אותו בריחות טובים לחזק ההרגש כמו\"כ כאן צ\"ל אשישות כו'.\n<b>והנה</b> צ\"ל מהו\"ע אשישות, הנה פי' אשישות ענבים, וכמ\"ש ואוהבי אשישה ענבים<sup data-n=\"3949\">27</sup>, דהנה היין כנוס בתוך הענבים והו\"ע יין המשמח אלקים ואנשים<sup data-n=\"3950\">28</sup> (בפ\"א<sup data-n=\"3951\">29</sup> ישמח ישראל בעושיו<sup data-n=\"3952\">30</sup> ) ומקשים אם אנשים משמח אלקים מה משמח<sup data-n=\"3953\">31</sup>, והענין דהנה ברה\"ע הי' ע\"י שם אלקים<sup data-n=\"3954\">32</sup> וכמ\"ש בראשית ברא אלקים (ות\"י בחוכמתא<sup data-n=\"3955\">33</sup> ) וכתי' ויקרא אלקים<sup data-n=\"3956\">34</sup> ל\"ב פעמים שם אלקים במע\"ב<sup data-n=\"3957\">35</sup> נגד ל\"ב נת\"ח<sup data-n=\"3958\">36</sup>",[["3938","17","<b>בשבת. . אז תתענג</b>: ראה זהר יתרו פח, א. מאמרי אדה\"א שמות ח\"א ע' קצא ואילך (ובהנסמן שם ע' קפה)."],["3939","18","<b>אז תתענג על הוי'</b>: ישעי' נח, יד. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'קי. וש\"נ. תו\"ח וארא ח\"א נ, ב. וש\"נ."],["3940","19","<b>ישבעו ויתענגו מטובך</b>: נוסח ”ישמחו במלכותך\" תפילת העמידה לשבת. ראה גם סה\"מ תרל\"ב ח\"א ע' סד."],["3941","20","<b>ורב טוב לבית ישראל</b>: ישעי' סג, טז."],["3942","8","<b>שמע ישראל</b>: ואתחנן ו, ד."],["3943","21","<b>מה רב טובך</b>: תהלים לא, כ."],["3944","22","<b>צפנ\"ת בגימ' כתר</b>: ראה מאו\"א מערכת צפנת ס\"י. סה\"מ תרל\"ח ע' שפ. וש\"נ."],["3945","23","<b>בכל יום מדרי' שבת והו\"ע התפלה</b>: ראה תו\"א ויקהל פח, א. לקו\"ת האזינו עב, ג. תו\"ח נח סא, ג ובהערה 29. ויקהל ח\"ב תטו, ג. וש\"נ. לקמן ח\"ב (בחלק המאמרים) המשך יונתי ספכ\"ב. ד\"ה רני ושמחי על יד הערה 39. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי על יד הערה 111. ד\"ה רני ושמחי על יד הערה 48. סה\"מ תרכ\"ז ס\"ע קפא ואילך."],["3946","25","<b>אשרי תבחר ותקרב ישכון חצריך</b>: תהלים סה, ה."],["3947","24","<b>שבת. . נתרפא החולת אהבה</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות כאן הערה 9."],["3948","26","<b>אינו דומה מאור פניו של אדם</b>: ראה ב\"ר פי\"א, ב. (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות כאן הערה 19."],["3949","27","<b>ואוהבי אשישה ענבים</b>: הושע ג, א [ושם: אשישי]. ראה רד\"ק שם."],["3950","28","<b>יין המשמח אלקים ואנשים</b>: ס' שופטים ט, יג. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ושאבתם מים פ\"א."],["3951","29","<b>בפ\"א</b>: ראה גם לעיל בהנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["3952","30","<b>ישמח ישראל בעושיו</b>: תהלים קמט, ב."],["3953","31","<b>אם. . מה משמח</b>: ברכות לה, א."],["3954","32","<b>בריה\"ע. . שם אלקים</b>: ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"י ובהערה 188."],["3955","33","<b>בראשית ברא. . בחוכמתא</b>: בראשית א, א ובתרגום ירושלמי שם. ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי הערה 478."],["3956","34","<b>ויקרא אלקים</b>: בראשית א, ה."],["3957","35","<b>ל\"ב פעמים שם אלקים במע\"ב</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["3958","36","<b>ל\"ב נת\"ח</b>: ראה ס\"י פ\"א, מ\"א. הנסמן במאמרי אדה\"א בראשית ע' ג."]]],[2000470437,"דבריאה יש מאין היא מבחי' חכ', ששהיו<sup data-n=\"3959\">37</sup> שרפים בבריאה וחיות ביצי' ואופנים בעשי'<sup data-n=\"3960\">38</sup> עד שנהי' האדם שלמטה שהוא מרוחק יותר מכולם ומה שיש נבראים למטה מהם ה\"ה אינם בעלי השגה כלל אבל האדם נעשה בצלמינו וכדמותינו<sup data-n=\"3961\">39</sup> ה\"ה מרוחק יותר מכולם, והירידה הוא צורך עלי'<sup data-n=\"3962\">40</sup> דע\"י אתכפי' ואתהפכא יבוא לבחי' ביטול היש, אך צ\"ל דהנה הנשמה קודם התלבשותה בגוף כתי' חי הוי' אשר עמדתי לפניו<sup data-n=\"3963\">41</sup> שעמדה באהוי\"ר וביטל לאלקות דאין עמידה למעלה אלא ביטל<sup data-n=\"3964\">42</sup> וכמ\"ש שרפים עומדים<sup data-n=\"3965\">43</sup>, ויעמידם לעד<sup data-n=\"3966\">44</sup>, ומלאכים הם מחיצוניות הכלים ונשמות הם מפנימיות הכלים<sup data-n=\"3967\">45</sup> כ\"ש שהם בטלים לאלקות, וירדה למטה בגוף ונה\"ב המעלים ומסתיר וכל הדרכים בחזקת סכנה<sup data-n=\"3968\">46</sup>, וא\"כ מהו העלי'.\n<b>והענין</b> דהנה כתי' סלסלה ותרוממך<sup data-n=\"3969\">47</sup>, ואמרז\"ל לא הוה ידעי רבנן<sup data-n=\"3970\">48</sup> מאי סלסלה חזיא דקא מהפך בי מזיא אמרית לי' עד מתי אתה מסלסל בשערות, דהנה השערות יונקים ממותרי מוחין<sup data-n=\"3971\">49</sup> ומ\"מ הם צומחים על הגולגלת וכמו\"כ התורה שרשה מחכ'<sup data-n=\"3972\">50</sup> ונמשלה לשערות<sup data-n=\"3973\">51</sup> כמו סלסול השערות הוא שכל שערה תהי' מונחת על מקומה, כמו\"כ תורה היא ג\"כ ענין הבירור כמו ורימינהו שהיא קשי', וענין הקושי' הוא שכאן אמר כך וכאן אמר כך ה\"ז בלבול וכמו השערות כמו שהם מחוברים ה\"ז בלבול השערות, ואח\"כ מתרצים לא קשי' שזה ענין בפ\"ע וזה ענין בפ\"ע וזהו\"ע בירורי ההלכות, ועי\"ז ותרוממך שנתרומם<sup data-n=\"3974\">52</sup> הנפש בעילוי אחר עילוי שנכלל בבחי' אין, דהנה והחכ' מאין תמצא<sup data-n=\"3975\">53</sup> שהוא אין דכתר המהווה מציאות החכ'",[["3959","37","<b>ששהיו</b>: כ\"ה בגוכתי\"ק."],["3960","38","<b>שרפים בבריאה וחיות ביצי' ואופנים בעשי'</b>: ראה סידור שער האלול רל, א. מאמרי אדה\"א ויקרא ח\"א ע' מד. וש\"נ. שע\"ת נח, א ובהערה 3."],["3961","39","<b>האדם נעשה בצלמינו וכדמותינו</b>: ע\"פ בראשית א, כו."],["3962","40","<b>והירידה הוא צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["3963","41","<b>חי הוי' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["3964","42","<b>עמידה. . ביטל</b>: ראה סוטה לט, א. וראה גם (לעיל בחלק המאמרים) מאמר הנ\"ל ובהערה 61."],["3965","43","<b>שרפים עומדים</b>: ישעי' ו, ב."],["3966","44","<b>ויעמידם לעד</b>: תהלים קמח, ו. ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א. וש\"נ."],["3967","45","<b>ומלאכים הם מחיצוניות. . מפנימיות הכלים</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"א. שער פו\"ח ש\"מ, דרוש י. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"ג ע' תשסח. וש\"נ. תו\"ח בשלח ח\"א רמ, ד ואילך."],["3968","46","<b>וכל הדרכים בחזקת סכנה</b>: ירושלמי ברכות פ\"ד, ה\"ד. קה\"ר ג, ב (ב)."],["3969","47","<b>סלסלה ותרוממך</b>: משלי ד, ח. ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א ובהערה 221."],["3970","48","<b>לא הוה ידעי רבנן</b>: ראה מגילה יח, א."],["3971","49","<b>השערות יונקים ממותרי מוחין</b>: ראה גם תו\"א תצוה פב, ב. קי, ב. לקו\"ת קרח נג, א. תצא לח, סע\"ג ואילך. לט, ב. שה\"ש לו, ד."],["3972","50","<b>התורה שרשה מחכ'</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["3973","51","<b>התורה. . ונמשלה לשערות</b>: ראה גם ערה\"כ לבעל סדה\"ד מערכת שערות. לעיל הערה 47."],["3974","52","<b>שנתרומם</b>: אולי כצ\"ל."],["3975","53","<b>והחכ' מאין תמצא</b>: איוב כח, יב. ראה מאמרי אדה\"א דברים ח\"ג ע' תשעט. וש\"נ. תו\"ח בראשית ז, ד ובהערה 49. בא ח\"א קא, ג. וש\"נ."]]],[2000470438,"אבל א\"ס הוא מרומם ונשגב מגדר עולמות ומע\"ס, דע\"ס הם נק' רזא דשמא קדישא<sup data-n=\"3976\">54</sup> רזא דמהימנותא<sup data-n=\"3977\">55</sup> כמו שם האדם אינו נוגע לעצמיות האדם<sup data-n=\"3978\">56</sup> אפי' לחו\"ב דעצם מכ\"ש לעצמיות וכמו\"כ למעלה הנה כתי' אני הוי' הוא שמי<sup data-n=\"3979\">57</sup>, הוא שמי שקרא לי אדה\"ר<sup data-n=\"3980\">58</sup> בשעה שקרא אדה\"ר שמות לבהמה ולחי' ולעוף<sup data-n=\"3981\">59</sup> א\"ל ואני מה שמי א\"ל לך נאה לקרות הוי'<sup data-n=\"3982\">60</sup> דיו\"ד הוא חכ'<sup data-n=\"3983\">61</sup> ה' בינה דחכ' הוא ראשית ההשתל'<sup data-n=\"3984\">62</sup> אבל א\"ס הוא מרומם ונשגב מע\"ס דאין ערוך אליך<sup data-n=\"3985\">63</sup> דקמי' כולא כלא חשיב<sup data-n=\"3986\">64</sup>, וזהו העלי' דישראל שנכללים בקדש העליון וזהו שכ' קדושים תהיו<sup data-n=\"3987\">65</sup> כמו שא\"ס הוא קדוש ומובדל כמו\"כ ישראל ג\"כ יוכללו בקדש העליון, וזהו ואנשי קדש תהיון לי<sup data-n=\"3988\">66</sup>, שיוכללו בקדש העצמי, וזהו העלי' לאשתאבא בגופא דמלכא<sup data-n=\"3989\">67</sup>, ובאמת הוא בחי' א\"ס אלא שנק' גופא, וזהו העלי' שיתעלו בבחי' אין, אך הוא בחי' אין דכולא קמי' כלא חשיב.\n<b>וזהו</b> נכנס יין יצא סוד<sup data-n=\"3990\">68</sup>, ובעבודה הו\"ע האהבה המוסתרת שיש בכאו\"א מישראל אלא שהוא מוסתר ונעלם, וזהו שיצא מהעלם אל הגילוי. ועוי\"ל יין הוא כנוס בענביו והו\"ע יינה<sup data-n=\"3991\">69</sup> של תורה<sup data-n=\"3992\">70</sup> שהלכות נתלבשו בדברים גשמים וע\"י נכנס יין הו\"ע סלסלה, עי\"ז יצא סוד, סוד הוי' ליריאיו<sup data-n=\"3993\">71</sup>, ובאמת גם למעלה משם הוי',",[["3976","54","<b>דע\"ס. . רזא דשמא קדישא</b>: ראה זהר יתרו סז, ב ובמפרשים שם. מאמרי אדה\"א הנחות תקע\"ז ע' שנ. וש\"נ."],["3977","55","<b>דע\"ס הם. . רזא דמהימנותא</b>: ראה זהר יתרו שם. שער היחוה\"א ספ\"ט. לקו\"ת בלק סח, ד. תו\"ח יתרו ח\"ב רסט, ג."],["3978","56","<b>שם האדם. . האדם</b>: ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ד ובהערה 58."],["3979","57","<b>אני הוי' הוא שמי</b>: ישעי' מב, ח."],["3980","58","<b>הוא שמי שקרא לי אדה\"ר</b>: ראה ב\"ר פי\"ז, ד. ראה גם (לעיל בחלק המאמרים) המשך מצה זו על יד הערה 1445."],["3981","59","<b>שקרא. . לבהמה ולחי' ולעוף</b>: בראשית ב, כ."],["3982","60","<b>הוי'</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות כאן הערה 46."],["3983","61","<b>דיו\"ד הוא חכ'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["3984","62","<b>דחכ' הוא ראשית ההשתל'</b>: ראה לקו\"ת שה\"ש כו, ד שמציין: כ\"ה בע\"ח שער מוחין דצלם פ\"ה[ednref_236_ג] בשם ספר יצירה וכ\"כ עוד בשער כ\"ה דרוש ה' וכ\"כ הרמ\"ז פ' ואתחנן בדף רס\"ו[ednref_237_ד] ועיין בזהר ויקרא ד\"י סע\"ב קדמאה י\"ה ועיין מק\"מ שם. סה\"מ תש\"ח ע' 112 בהערה שמציין: ראה ע\"ח שער דרושי אבי\"ע פ\"א. שער היחוד והאמונה פח\"ט. תו\"א וש\"א רד\"ה יביאו לבוש מלכות."],["3985","63","<b>דאין ערוך אליך</b>: תהלים מ, ו."],["3986","64","<b>דקמי' כולא כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["3987","65","<b>קדושים תהיו</b>: ר\"פ קדושים."],["3988","66","<b>ואנשי קדש תהיון לי</b>: משפטים כב, ל. ראה לקו\"ת בהעלותך ל, סע\"ג ואילך. יו\"כ סט, ב."],["3989","67","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה. תו\"ח בראשית מ, ב הערה 25."],["3990","68","<b>נכנס יין יצא סוד</b>: ערובין סה, סע\"א. ראה גם תו\"ח ויחי רלו, ב."],["3991","69","<b>יינה</b>: אולי כצ\"ל."],["3992","70","<b>יינה של תורה</b>: ע\"ז לה, א."],["3993","71","<b>סוד הוי' ליריאיו</b>: תהלים כה, יד.\n\n[edn_236_ג] <b>במהדורת שקלאב, ולפנינו</b>: פ\"א.\n\n[edn_237_ד] <b>באוה\"ת יתרו ע' תתמ</b>: דרס\"ה ע\"ב בד\"ה אבל צריך. בדפי הספר קצד, סע\"ב."]]],[2000470439,"וזהו יין המשמח אלקים, דהנה אלקים הוא בחי' הצמצום<sup data-n=\"3994\">72</sup> ול\"ב פעמים אלקים במע\"ב ובכל אלקים יש ק\"ך צירופי' דאלקים<sup data-n=\"3995\">73</sup> והיין הוא משמח אלקים שנמשך בחי' הוי'.\n<b>רפדוני</b> בתפוחים הוא כמ\"ש וריח אפך כתפוחים<sup data-n=\"3996\">74</sup>, הנה ריח דמאכל הוא מדרי' היותר גבוה מריח דמשקה, דהנה איתא בזהר אכלו ריעים<sup data-n=\"3997\">75</sup> לעילא שתו ושכרו דודים לתתא, אכלו ריעים לעילא הוא בחי' חו\"ב שתו ושכרו דודים לתתא זו\"נ, וזהו שמיעה בהאי אתר תליא<sup data-n=\"3998\">76</sup> עשי' לעילא, שמיעה בהאי אתר תליא מפרשים על בחי' מל' עשי' לעילא הוא בחי' בינה, הרי שמאכל הוא למעלה ממשקה וריח של מאכל הוא למעלה גם מעצם מאכל, דהנה ריח הוא דבר שהנשמה נהנה<sup data-n=\"3999\">77</sup> ממנו ולא הגוף דמאכל הוא מחבר הנשמה עם הגוף וריח הוא רק ממשיך הארת הנפש בהגוף, והו\"ע מצות<sup data-n=\"4000\">78</sup> של מעלה הגם שמצות למטה הם מצות המלך<sup data-n=\"4001\">79</sup> מ\"מ הרי תרי\"ג מצות דאורייתא<sup data-n=\"4002\">80</sup> וז'<sup data-n=\"4003\">83</sup> מצות דרבנן<sup data-n=\"4004\">82</sup> הם תר\"ך<sup data-n=\"4005\">81</sup> עמודי אור<sup data-n=\"4006\">84</sup> דכתר והוא עטרה ע\"ג הראש שהוא בחי' מקיף, וכללות כל המצות הם צדקה וכמ\"ש וצדקה תהי' לנו<sup data-n=\"4007\">85</sup> כי נשמור לעשות כל המצוה הזאת, הרי כתי' צדקה תרומם גוי<sup data-n=\"4008\">86</sup> כמו גבי תורה כתי' סלסלה ותרוממך כך צדקה תרומם גוי וגם נמשך בחכ' ג\"כ דע\"י מעשה מזדככים מוחו ולבו אלף פעמים ככה<sup data-n=\"4009\">87</sup> וזהו\"ע רפדוני בתפוחים.",[["3994","72","<b>אלקים. . הצמצום</b>: ראה שער היחוה\"א רפ\"ו. תו\"ח שמות ח\"א לד, ד. וש\"נ."],["3995","73","<b>ק\"כ צירופי' דאלקים</b>: ראה ע\"ח שער הזיווגים שט\"ו, פ\"ו. שער השמות שמ\"ד, פ\"ה. בהנחה שלאח\"ז על יד הערה *28. הנסמן במאמרי אדה\"א שמות ח\"א ע' קלז."],["3996","74","<b>וריח אפך כתפוחים</b>: שה\"ש ז, ט."],["3997","75","<b>אכלו ריעים</b>: שה\"ש ה, א. זהר ויקרא ד, א."],["3998","76","<b>שמיעה בהאי אתר תליא</b>: ראה זהר בהר קח, ב. ביאוה\"ז בהר פב, סע\"ב ואילך. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תעא ואילך. סה\"מ תרל\"ח ע' רלג ואילך. תרע\"ח ע' שצו ואילך."],["3999","77","<b>ריח. . שהנשמה נהנה</b>: ראה ברכות מג, ב. (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ח ובהערה 134."],["4000","78","<b>וריח. . מצות</b>: ראה שהש\"ר פ\"א, ג. ערה\"כ לבעל סדה\"ד מערכת ריח. לקו\"ת מסעי צא, א. אוה\"ת שה\"ש ח\"ב ע' תכז. ע' תכח."],["4001","79","<b>שמצות. . מצות המלך</b>: ראה אסתר ג, ג. מאמרי אדה\"א שמות ח\"א ע' יא. וש\"נ. נ\"ך ע' רלה. ש\"א ע' נו."],["4002","80","<b>תרי\"ג מצות דאורייתא</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. לקו\"ש יתרו כרך כו ס\"ע 424 ואילך. אג\"ק שלו ח\"ג ע' רג."],["4003","83","<b>וז' מצות דרבנן</b>: ראה אגה\"ק סכ\"ט. דרך חיים פנ\"ו. פס\"ד. לקו\"ש שופטים כרך כט ע' 104 ואילך. וש\"נ."],["4004","82","<b>וז' מצות דרבנן</b>: וסימנם: נ\"ע בשמח\"ה — ראה לקו\"ש יתרו כרך כא ע' 401. אג\"ק שלו ח\"ב ע' שכ."],["4005","81","<b>תרי\"ג. . וז'. . תר\"ך</b>: ראה תורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שיו, א. מאו\"א מערכת תר\"ך סנ\"ו. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלח."],["4006","84","<b>תר\"ך עמודי אור</b>: ראה לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. תו\"ח בראשית מה, ג הערה 32."],["4007","85","<b>כל המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה [בדילוג]. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות כאן הערה 65."],["4008","86","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["4009","87","<b>מעשה מזדככים מוחו ולבו אלף פעמים ככה</b>: ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח לאחרי פי\"ט ובהערה 494."]]],[2000470440,"<b>אך</b> צ\"ל מה צריכים לשניהם סמכוני באשישות וגם רפדוני בתפוחים, הענין הוא דהנה אי' בענין שוהם וישפה<sup data-n=\"4010\">88</sup> שיש ב' אופנים ביחודים עד\"מ א' עומד בגובה ההר וא'<sup data-n=\"4011\">89</sup> בשפולי ההר, יש ב' אופנים באופן יחודם או שהעליון יורד לתחתון או שהתחתון יעלה לעליון, כמו\"כ יובן למעלה הנה כתי' שמאלו תחת לראשי<sup data-n=\"4012\">90</sup> וימינו תחבקיני, שמאלו תחת לראשי הו\"ע שמאל דוחה<sup data-n=\"4013\">91</sup> והוא התורה שהיא המשכה מלמעלמ\"ט כדי שיהי' העלאה מלמטלמ\"ע, ומה שתורה נק' בשם שמאלו הגם שהיא תורת חסד<sup data-n=\"4014\">92</sup>, הוא מפני שתורה היא כשר פסול טמא טהור אלו טרפות<sup data-n=\"4015\">93</sup> ואילו אסורות<sup data-n=\"4016\">94</sup>, פי' שהם אסורים וקשורים בידי החיצונים<sup data-n=\"4017\">95</sup> וא\"א שיתעלו, ועי\"ז הכשרים יכולים להתעלות, וזהו שעיקר למוד התורה הוא דוקא בדיבור<sup data-n=\"4018\">96</sup> שמדחה החיצונים. וזהו\"ע מתניתא מלכתא<sup data-n=\"4019\">97</sup> כמו מלך שגוזר אומר כך בתורה שפוסק כשר פסול כו' וזהו\"ע סלסול השערות דתחילה הדין מעורב וע\"י שפוסקין כך ולא כך זהו\"ע הסלסול, וימינו תחבקיני הוא ההמשכה מלמעלמ\"ט ע\"י מצות, וכללות כל המצות הוא מצות צדקה שהוא להחיות רוח שפלים<sup data-n=\"4020\">98</sup> דעני דלית לי' מגרמי' כלום ה\"ה נותן לו חיות, כמו\"כ ע\"י המצות ממשיכים המשכת אלקות [שכולם שפלים ודלים לגבי הקב\"ה], ותחילה צ\"ל שמאלו תחת לראשי והוא כמ\"ש על כן ירום ראש<sup data-n=\"4021\">99</sup>, ראש הוא נש\"י<sup data-n=\"4022\">100</sup> וצריכים להרים הראש ועי\"ז אח\"כ וימינו תחבקיני, וכמו\"כ סמכוני באשישות רפדוני בתפוחים הוא ג\"כ ענין שמאלו תחת לראשי וימינו תחבקיני שהם תורה ומצות לכן צריכים לשניהם שאינו שייך המשכה בלא העלאה, וזה מה שת\"י<sup data-n=\"4023\">101</sup> על סמכוני באשישות הם משה ואהרן שסומכין את ישראל בתורה ועי\"ז נרפא החולת אהבה, דהנה תורה היא אש דת<sup data-n=\"4024\">102</sup> וזהו באשישות ל' אש<sup data-n=\"4025\">103</sup>, אך הוא אש אוכלה אש<sup data-n=\"4026\">104</sup> שאוכל האש זר, דהנה החולת אהבה הוא מצד ההעדר והוא מחמת האש זר ותאוות עוה\"ז, אך אש דתורה אוכל האש זר ממילא מתרפא החולת אהבה, וזהו סמכוני באשישות רפדוני בתפוחים כי חולת אהבה אני מפני שחולת",[["4010","88","<b>שוהם וישפה</b>: ראה לקו\"ת פ' ראה כז, ד. תו\"א תשא קיב, ג. מאמרי אדה\"א דברים ח\"ב ע' תע."],["4011","89","<b>עד\"מ א'. . וא'</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות כאן הערה 69."],["4012","90","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."],["4013","91","<b>שמאל דוחה</b>: סוטה מז, א."],["4014","92","<b>תורת חסד</b>: משלי לא, כו."],["4015","93","<b>אלו טריפות</b>: חולין פ\"ג, מ\"א."],["4016","94","<b>ואילו אסורות</b>: סוטה ו, א (במשנה). חולין לב, ב."],["4017","95","<b>אסורים. . החיצונים</b>: ראה תניא פ\"ז. אגה\"ק סכ\"ו (קמג, ב)."],["4018","96","<b>למוד התורה. . בדיבור</b>: ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פכ\"ג ובהערה 667."],["4019","97","<b>מתניתא מלכתא</b>: כתובות סא, ב. ראה תו\"א וישב כז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קפט."],["4020","98","<b>להחיות רוח שפלים</b>: ישעי' נז, טו. ראה גם סה\"מ תרל\"ג ח\"ב ע' תסה ובהנסמן שם."],["4021","99","<b>על כן ירום ראש</b>: תהלים קי, ז [ושם: ירים]."],["4022","100","<b>ראש הוא נש\"י</b>: ראה גם ערה\"כ לבעל סדה\"ד מערכת ראש."],["4023","101","<b>שת\"י</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות כאן הערה 88."],["4024","102","<b>תורה היא אש דת</b>: ברכה לג, ב."],["4025","103","<b>באשישות ל' אש</b>: ראה תרגום עה\"פ. שהש\"ר רפ\"ב. ת\"ז ריש תקונא שתתיאה קמג, ב."],["4026","104","<b>אש אוכלה אש</b>: יומא כא, ב."]]],[2000470441,"אהבה אני והוא מחמת האש זר שמונע ומעכב לכן מבקשים כנס\"י סמכוני באשישות רפדוני בתפוחים כו'."],[2000470442,"<h3>גדולה תשובה</h3>\n<b>ש\"פ ויקרא ט\"ל לפ\"ק</b>\n<b>גדולה</b> תשובה<sup data-n=\"4027\">1</sup> שמביא רפואה לעולם<sup data-n=\"4028\">2</sup>, ולכאורה צ\"ל מה שייך רפואה לעולם, והלא רפואה אינו שייך כ\"א למדבר או לבע\"ח אבל כאן משמע שהרפואה היא לעולם מה שייך לעולם רפואה. והענין דהנה נת\"ל<sup data-n=\"4029\">3</sup> שחולה הו\"ע חולת אהבה<sup data-n=\"4030\">4</sup> אך יש עוד מין חולה והוא מ\"ש כל מחלה<sup data-n=\"4031\">5</sup> אשר שמתי במצרים לא אשים עליך כי אני הוי' רפאיך ואמרז\"ל מחלה זו מרה<sup data-n=\"4032\">6</sup>, דהנה כתי' נופת תטופנה שפתי זרה<sup data-n=\"4033\">7</sup> ואחריתה מרה כלענה<sup data-n=\"4034\">8</sup> ואי' בזהר שקאי על ק\"נ<sup data-n=\"4035\">9</sup>, והנה מבואר בסש\"ב דק\"נ הוא מעורב טו\"ר<sup data-n=\"4036\">10</sup> ומזה נמשך עשי' שהוא רובו ככולו רע רק מעט טוב מעורב בו ומזה הם התאוות היתר אשר אסרן התורה וראי' מבן סורר ומורה<sup data-n=\"4037\">11</sup> אמרה תורה ימות זכאי<sup data-n=\"4038\">12</sup>, דהנה אי' במשנה<sup data-n=\"4039\">13</sup> מאימתי נעשה בן סורר ומורה משיאכל טרטימר בשר וישתה חצי לוג יין האיטלקי, ובאמת הרי אין זה איסר, שהרי מותר לאכול בשר ולשתות יין, אך הוא יתר מכפי המדה אמרה תורה ימות זכאי אף שהוא זכאי מ\"מ ימות, הרי שתאוות היתר מלבד שהם אסורים מפני שיבוא לתאוות איסר הרי חייבה התורה עליהם מיתה, ואי' בחינוך<sup data-n=\"4040\">14</sup> מי שהוא רודף אחר תאוות היתר עובר על לאו דלא תתורו<sup data-n=\"4041\">15</sup> ובחיי<sup data-n=\"4042\">16</sup> מאריך בענין זה, ובאמת הרי צ\"ל בהיפך וכמ\"ש ותורתך בתוך מעי<sup data-n=\"4043\">17</sup> שאמר דוד א\"ע כל מה שבתוך מעי הכל ע\"פ דרכי<sup data-n=\"4044\">18</sup> התורה והנהגת פרישותו<sup data-n=\"4045\">19</sup> לא מה שירצה האדם יעשה אלא צ\"ל פרישה, וזהו צדיק אוכל לשובע נפשו<sup data-n=\"4046\">20</sup> כמו א' שאוכל בעת שהוא שבע הרי אין בזה תאווה וכמו\"כ צ\"ל בכל הדברים שיהי' בלא תאווה.",[["4027","1","<b>גדולה תשובה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה: ”ואמנם יש עוד בחי' חולה\" שנדפס לעיל בחלק המאמרים. וש\"נ.\nבהכותרת כאן נרשם: ט\"ל — אוצ\"ל: תר\"ם."],["4028","2","<b>גדולה תשובה שמביא רפואה לעולם</b>: ראה יומא פו, סע\"א."],["4029","3","<b>נת\"ל</b>: בהנחה שלפנ\"ז ד\"ה סמכוני באשישות."],["4030","4","<b>חולת אהבה</b>: שה\"ש ב, ה."],["4031","5","<b>כל המחלה</b>: בשלח טו, כו."],["4032","6","<b>מחלה זו מרה</b>: ב\"מ קז, ב."],["4033","7","<b>נופת תטופנה שפתי זרה</b>: משלי ה, ג."],["4034","8","<b>ואחריתה מרה כלענה</b>: שם ה, ד."],["4035","9","<b>שקאי על ק\"נ</b>: זהר ויקהל רג, ב."],["4036","10","<b>בסש\"ב דק\"נ הוא מעורב טו\"ר</b>: פ\"ז."],["4037","11","<b>מבן סורר ומורה</b>: תצא כא, כ."],["4038","12","<b>אמרה תורה ימות זכאי</b>: סנהדרין עא, ב (במשנה — ראה בשנויי נוסחאות במשניות שם)."],["4039","13","<b>אי' במשנה</b>: ראה סנהדרין ע, א."],["4040","14","<b>בחינוך</b>: מצוה שפז."],["4041","15","<b>לאו דלא תתורו</b>: שלח טו, לט."],["4042","16","<b>ובחיי</b>: ר\"פ קדושים."],["4043","17","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["4044","18","<b>דרכי</b>: אולי כצ\"ל."],["4045","19","<b>פרישותו</b>: אולי כצ\"ל."],["4046","20","<b>צדיק אוכל לשובע נפשו</b>: משלי יג, כה. ראה לעיל (בחלק המאמרים) מאמר ד\"ה ואמנם כו' חולה כאן הערה 13."]]],[2000470443,"<b>אך</b> מי שהוא משוקע בתאוות היתר ה\"ז חולה, וזהו שכ' גבי בשר [היתר] (איסר)<sup data-n=\"4047\">21</sup> והי' לכם לזרא<sup data-n=\"4048\">22</sup> ופירש\"י לחרב והוא כמ\"ש כאן חדה כחרב פיות<sup data-n=\"4049\">23</sup> שהוא מאבד, וזהו מחלה זו מרה והוא כמ\"ש נופת תיטופנה שפתי זרה ואחריתה מרה כלענה, דהנה תי' מחלה יש בו ב' פי' א' ל' חולי ב' ל' מתיקות וכמו מחליא לי' לישבח<sup data-n=\"4050\">24</sup> וזהו שאי' במד'<sup data-n=\"4051\">25</sup> ע\"פ והסיר ה' ממך כל חולי<sup data-n=\"4052\">26</sup> זה היצה\"ר, ופי' המת\"כ שהמד' מפרש ב' פי' בתיבת חולי ל' מחליא ול' חולאת, וי\"ל זה על ב' דרכים א' ע\"פ פשוט שהיצה\"ר מסית ומדיח וממתק איך שטוב לו אך אחריתה מרה כלענה, ובאמת י\"ל דהנה העונש בא לאחר זמן לא תיכף וזהו שתחלתו מתוק אך סופו כשבא העונש אז מר, ותי' מר הוא ב\"פ ק\"ך דהנה י\"ש ק\"כ צירופי' דשם אלקים<sup data-n=\"4053\">*28</sup> והנה ע\"ב צירופים הראשונים הם גבורות ממותקות, אך מ\"ח צירופי' אחרונים<sup data-n=\"4054\">28</sup> הם גבו' בלתי ממותקות וכשמתחברים ק\"ך צירופי' דנוגה עם ק\"ך צירופי' דקדושה<sup data-n=\"4055\">27</sup> אז נעשים גבורות קשות להשמיד להרג ולאבד<sup data-n=\"4056\">29</sup>, והסיר ה' ממך כל חולי אי' במד' ממך שהחולי הוא ממך<sup data-n=\"4057\">30</sup>, דהנה אי' במד' משעה שא' הקב\"ה<sup data-n=\"4058\">31</sup> ראה הנה נתתי<sup data-n=\"4059\">32</sup> לפניך את החיים ואת הטוב כו' לא ירדה טובה לעושה<sup data-n=\"4060\">33</sup> רעה ולא רעה לעושה טובה אלא טובה לעושה טובה כו' וא\"כ הרי האדם בעצמו ממשיך זה.\n<b>ומ\"מ</b> אל יאמר נואש דהנה יש בכחו להפוך דהנה אי' בזהר שהוא כמשל זונה עם בן המלך<sup data-n=\"4061\">34</sup> דעיקר כוונת היצה\"ר הוא שלא יעשה הרע, וזהו מ\"ש בקהלת הוא ענין רע אשר נתן אלקים לבני אדם לענות בו<sup data-n=\"4062\">35</sup>, רע הוא יצה\"ר וכמ\"ש כי יצר לב האדם רע מנעוריו<sup data-n=\"4063\">36</sup>, וכמו בורא רע<sup data-n=\"4064\">37</sup>, ראה נתתי לפניך כו' ואת הרע, אשר נתן אלקים לבנ\"א כוח לענות בו ע\"ד מלאך רע בע\"כ יענה אמן<sup data-n=\"4065\">38</sup>, וזהו ואהבת את ה'",[["4047","21","[היתר]<b> (איסר)</b>: אולי כן נאמר ע\"י כ\"ק אדמו\"ר מהר\"ש. והוסיף כ\"ק אדמו\"ר מהורש\"ב המוסגרים."],["4048","22","<b>והי' לכם לזרא</b>: בהעלותך יא, כ."],["4049","23","<b>חדה כחרב פיות</b>: המשך הכתוב ואחריתה מרה כלענה — משלי ה, ד."],["4050","24","<b>מחליא לי' לישבח</b>: ראה ע\"ז לט, א. מת\"כ לשמו\"ר פמ\"ג, ג."],["4051","25","<b>שאי' במד'</b>: ויק\"ר פט\"ז, ח."],["4052","26","<b>והסיר ה' ממך כל חולי</b>: עקב ז, טו."],["4053","*28","<b>ק\"כ צירופי' דשם אלקים</b>: ראה לעיל הנחה ד\"ה סמכוני באשישות ובהערה 73."],["4054","28","<b>מ\"ח צירופי' אחרונים</b>: ראה לקמן הנחה ד\"ה גן נעול הב' ובהערה 50."],["4055","27","<b>מר הוא ב\"פ ק\"ך. . דקדושה</b>: ראה לעיל (בחלק המאמרים) מאמר ד\"ה ואמנם כו' חולה כאן הערה 23."],["4056","29","<b>להשמיד להרג ולאבד</b>: אסתר ג, יג."],["4057","30","<b>והסיר. . הוא ממך</b>: עקב ז, טו. ויק\"ר פט\"ז, ח. ראה גם אוה\"ת עקב ס\"ע תקיא ואילך."],["4058","31","<b>משעה שא' הקב\"ה</b>: ראה איכ\"ר פ\"ג אות מ. דב\"ר פ\"ד, ג. סה\"מ תרל\"ו ח\"ב ע' רסט (ומציין לשינויים). המשך תער\"ב ח\"ג ס\"ע א'תכט ואילך."],["4059","32","<b>ראה הנה נתתי</b>: נצבים ל, טו [בהוספת תיבת הנה ובהשמטת תיבת היום]."],["4060","33","<b>לעושה</b>: אולי כצ\"ל."],["4061","34","<b>כמשל זונה עם בן המלך</b>: ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ב ובהערה 31."],["4062","35","<b>הוא ענין. . לענות בו</b>: קהלת א, יג [בהוספת תיבת אשר. ושם: האדם]."],["4063","36","<b>כי יצר לב האדם רע מנעוריו</b>: נח ח, כא. סוכה נב, א."],["4064","37","<b>בורא רע</b>: ע\"פ ישעי' מה, ז."],["4065","38","<b>מלאך רע בע\"כ יענה אמן</b>: שבת קיט, ב."]]],[2000470444,"אלקיך בכל לבבך בשני יצריך<sup data-n=\"4066\">39</sup> שגם היצה\"ר יהי' לו אהבה לאלקות, והוא ע\"י ההתבוננות שקודם לזה שמע ישראל הוא ביטול דיחו\"ע<sup data-n=\"4067\">40</sup> איך שכולא קמי' כלא חשיב<sup data-n=\"4068\">41</sup> אך הנה\"ב אינו שייך שיתפעל מהתבוננות דיחו\"ע כ\"א מהתבוננות דיחו\"ת וזהו בשכמל\"ו<sup data-n=\"4069\">42</sup> שכללות העולמות הם רק משם והארה בעלמא וההארה בטל לאלקות והנה\"ב בעצם אינו רע<sup data-n=\"4070\">43</sup> ולכן אמרו במד' שהחולי ממך לכן אפשר להפוך אותו, וזהו כל המחלה אשר שמתי במצרים לא אשים עליך דמצרים הוא מצרים וגבולים<sup data-n=\"4071\">44</sup> והו\"ע תאוות גשמים<sup data-n=\"4072\">45</sup> לא אשים עליך שנהפך היצה\"ר, כי אני ה' רפאיך וצ\"ל מאחר שלא אשים מה שייך רפואה, הגם שי\"ל מפני שאני ה' רפאיך לכן לא אשים, לפ\"ז אינו שייך לומר רפאיך דרופא משמע שעושה איזה פעולה, והענין דהנה רפאות תהי לשריך<sup data-n=\"4073\">46</sup> ואי' במאור עינים מהר\"ן ז\"ל<sup data-n=\"4074\">47</sup> שקאי על מאמר המין שחלק בין פלגא דלעילא לפלגא דלתתא<sup data-n=\"4075\">48</sup> והשיב לו שאין חילוק וזהו שכ' רפאות כו' שפלגא דלתתא יהי' כמו פלגא דלעילא.\n<b>וביאור</b> הענין דהנה כתי' משם יפרד<sup data-n=\"4076\">49</sup> דמשם התחלות הפירוד דהנה כתי' קודם לזה ונהר יוצא מעדן להשקות את הגן ונהרא מכיפי' מיבריך<sup data-n=\"4077\">51</sup> והוא יש שהוא השגה והבנה<sup data-n=\"4078\">50</sup> אבל ומעיין מבית ה' יוצא<sup data-n=\"4079\">52</sup> והשקה את נחל השיטים מעיין הוא אין דחכ'<sup data-n=\"4080\">53</sup> שיש בכוחו להשקות הנחל השיטים שהוא ל' שטות<sup data-n=\"4081\">54</sup> כמ\"ש שטו העם ולקטו<sup data-n=\"4082\">55</sup>, וכמו אין אדם עובר עבירה<sup data-n=\"4083\">56</sup> אא\"כ נכנס בו רוח שטות, וע\"י בחי' אין הוא",[["4066","39","<b>ואהבת. . בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, ב במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פט\"ז."],["4067","40","<b>שמע ישראל. . דיחו\"ע</b>: ואתחנן ו, ד. זהר בראשית יח, ב. ראה תו\"א שבהערה 42."],["4068","41","<b>שכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["4069","42","<b>דיחו\"ת וזהו בשכמל\"ו</b>: זהר בראשית יח, ב. פסחים נו, א. ראה תו\"א ויקהל קטו, ב."],["4070","43","<b>והנה\"ב בעצם אינו רע</b>: ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ב."],["4071","44","<b>דמצרים הוא מצרים וגבולים</b>: ראה תו\"א יתרו עא, ג."],["4072","45","<b>דמצרים. . תאוות גשמים</b>: ראה גם לקו\"ת בהעלותך לג, א. חוקת סא, ג."],["4073","46","<b>רפאות תהי לשריך</b>: משלי ג, ח."],["4074","47","<b>במאור עינים מהר\"ן ז\"ל</b>: בספר מאור עינים מהרב מנחם נחום מטשארנביל פ' בשלח עה\"פ ויאמר אם שמוע תשמע בסופו. ראה גם אוה\"ת משלי כרך א ע' תקנב."],["4075","48","<b>מאמר המין. . לפלגא דלתתא</b>: ראה סנהדרין לט, א."],["4076","49","<b>משם יפרד</b>: בראשית ב, י [ושם: ומשם]."],["4077","51","<b>ונהרא מכיפי' מיבריך</b>: שבת סה, ב. ראה גם לקו\"ת שה\"ש לט, א ואילך. אמ\"ב שער התפילין קכא, סע\"ג ואילך."],["4078","50","<b>ונהר יוצא מעדן. . השגה והבנה</b>: בראשית ב, י. ראה תו\"א משפטים עה, ד: כמ\"ש בזהר פ' אמור [צט, א]."],["4079","52","<b>ומעיין מבית ה' יוצא</b>: יואל ד, יח."],["4080","53","<b>מעיין. . דחכ'</b>: ראה זהר בא מב, ב. מאמרי אדה\"א דברים ח\"ג ע' תתצב. וש\"נ. שה\"א צ, א הערה 12."],["4081","54","<b>השיטים. . שטות</b>: ראה סנהדרין קו, א. במדב\"ר פ\"כ, כב. תנחומא שם טז."],["4082","55","<b>שטו העם ולקטו</b>: בהעלותך יא, ח. ראה לקו\"ת שה\"ש לט, ב. אוה\"ת חוקת ע' תשצו. כרך ה' ע' א'תרכה [ובמהדורת תשנ\"ח ע' 17]."],["4083","56","<b>אין אדם עובר עבירה</b>: סוטה ג, א. ראה מאמרי אדה\"א דברים ח\"ב ע' תרמה. וש\"נ. לקמן הנחה ד\"ה צאינה וראינה על יד הערה 76 ואילך."]]],[2000470445,"נהפוך, וכח זה יש בתורה ג\"כ דכתי' ועשו ארון עצי שיטים<sup data-n=\"4084\">57</sup> ולמה הי' מעצי שיטים להורות שיש כח בתורה להפוך השטות ג\"כ, וזהו אם פגע בך מנוול זה ופירש\"י זה היצה\"ר<sup data-n=\"4085\">58</sup> משכהו לבהמ\"ד אפי' אם אבן הוא נמוח, דתורה הוא מים<sup data-n=\"4086\">59</sup> ומים ממחה את האבן, וזהו בראתי יצה\"ר בראתי תורה תבלין<sup data-n=\"4087\">60</sup> כמו התבלין נותנין טעם בהמאכל כמו\"כ התורה מהפך היצה\"ר, וזהו כי אני רפאיך שפלגא דלתתא יהי' כמו פלגא דלעילא שלא יהי' נפרד כ\"כ, דנפרד הוא גרע מנבדל דאי' במד'<sup data-n=\"4088\">61</sup> ע\"פ הפרד נא מעלי<sup data-n=\"4089\">62</sup> הבדל אכ\"כ<sup data-n=\"4090\">63</sup> אלא הפרד כמ\"ש כסוס כפרד<sup data-n=\"4091\">64</sup> שהוא ענין אחר לגמרי, וזהו רפאיך שלא יהי' נפרד כ\"כ, ובעבודה הו\"ע פגם הברית שיהי' נטירת הברית, ולפ\"ז אינו סותר כלל אף דכל המחלה אשר שמתי במצרים לא אשים עליך היינו התאוות היתר אך הקרומא דפסיק במעי' דבר נש<sup data-n=\"4092\">65</sup> זה ישנו באדם וזהו הרפואה שלא יהי' נפרד כ\"כ.\n<b>וזהו</b> גדולה תורה<sup data-n=\"4093\">66</sup> שמביאה רפואה לעולם, דהנה ראה נתתי לפניך את החיים ואת הטוב ואת המות ואת הרע והוא כמ\"ש יהי רקיע ויהי מבדיל<sup data-n=\"4094\">67</sup> בין מים למים, הנה המים אשר מעל לרקיע הוא מקור על חיים טובים ומים שמתחת לרקיע הוא מקור על כל דברים הווים ונפסדים, דבתחילה הי' מים במים<sup data-n=\"4095\">68</sup>, מים העליונים לא היו בתכלית העילוי ומים התחתונים לא הי' מקור על גשמיות, אבל אחר ההבדלה מים העליונים הם מקור חיים טובים ומ\"ת הם מקור כל דבר הווה ונפסד עד שנעשה חול ל' חולין עד שנעשה ממשלת ק\"נ דעולם הוא היתר וזהו תאוות היתר ה\"ה קרובים דתחילת הבריאה הי' שלא יהי' ממשלת ק\"נ וזהו בראשית ברא ל' בריאה ול' בריאות<sup data-n=\"4096\">69</sup> וכמ\"ש ובראך יעקב<sup data-n=\"4097\">70</sup> ל' בריאות, וזהו ויניחהו בג\"ע<sup data-n=\"4098\">71</sup> לעבדה ולשמרה מה שעכשיו הוא עבודה<sup data-n=\"4099\">72</sup> אז הי' שם העבודה, דתחילת הבריאה הי' באופן שיומשך המשכת אלקות ולא יהי' ממשלת ק\"נ, אך לאחר חטא עה\"ד כתי' וכי תאוה הוא לעינים<sup data-n=\"4100\">73</sup> ונחמד העץ למאכל<sup data-n=\"4101\">74</sup> אז התחילו התאוות וזהו חולי, הגם שאמרז\"ל אלה",[["4084","57","<b>ועשו ארון עצי שטים</b>: תרומה כה, י. ראה לעיל (בחלק המאמרים) מאמר ד\"ה ואמנם כו' חולה כאן הערה 58."],["4085","58","<b>אם פגע. . היצה\"ר</b>: ראה סוכה נב, ב וברש\"י שם."],["4086","59","<b>דתורה הוא מים</b>: ראה סוכה וברש\"י שם. תניא פ\"ד ובמ\"מ הגהות והע\"ק לשם."],["4087","60","<b>בראתי יצה\"ר. . תבלין</b>: ראה קדושין ל, ב."],["4088","61","<b>דאי' במד'</b>: ראה ב\"ר פמ\"א, ו."],["4089","62","<b>הפרד נא מעלי</b>: לך יג, ט."],["4090","63","<b>אכ\"כ</b>: אין כתיב כאן."],["4091","64","<b>כמ\"ש כסוס כפרד</b>: ראה מתנות כהונה שם — תהלים לב, ט. ראה קונט' עה\"ח ע' 23."],["4092","65","<b>הקרומא דפסיק במעי' דבר נש</b>: ראה זהר בראשית לב, ב."],["4093","66","<b>תורה</b>: אוצ\"ל: תשובה."],["4094","67","<b>יהי </b>[אולי כצ\"ל]<b> רקיע ויהי מבדיל</b>: בראשית א, ו [בדילוג]. ראה לק\"ת ואתחנן יא, ב."],["4095","68","<b>דבתחלה הי' מים במים</b>: ראה ב\"ר פ\"ה, ב. שה\"א נג, ב הערה 16. לעיל (בחלק המאמרים) מאמר ד\"ה כמגדל דוד צוארך בתחלתו."],["4096","69","<b>ברא. . בריאות</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ואמנם כו' חולה כאן הערה 77."],["4097","70","<b>ובראך יעקב</b>: ישעי' מג, א [ושם: בראך]. ראה גם לעיל שם על יד הערה 78."],["4098","71","<b>ויניחהו בג\"ע</b>: בראשית ב, טו."],["4099","72","<b>עבודה</b>: אוצ\"ל: שכר."],["4100","73","<b>וכי תאוה הוא לעינים</b>: בראשית ג, ו."],["4101","74","<b>למאכל</b>: שם: טוב העץ למאכל. . וכי תאוה. . העץ להשכיל — ראה גם מאמרי אדה\"א דברים ח\"ב ע' תרצב."]]],[2000470446,"תולדות השמים וארץ בהבראם שהם חזקים כיום הבראם<sup data-n=\"4102\">75</sup>, אך הרי באמת חסרו ו' דברים<sup data-n=\"4103\">76</sup> וחסרון ה\"ז חולי, ואין סתירה למה שא' שהם חזקים כו' דשמים וארץ שישנם הם חזקים אבל מה שחסר חסר, וזהו חולי זהו שארז\"ל גדולה תשובה שמביא רפואה לעולם, דתשובה הוא בא\"א<sup data-n=\"4104\">77</sup> וכתי' וארוכתך מהרה תצמח<sup data-n=\"4105\">78</sup> שנמשך ארוכה ורפואה שיהי' כמו בשבת, דהנה בתחילת הבריאה לא הי' חול רק אחר חטא עה\"ד אז הי' שבת וניכר שמה שקדם לו הי' חול, ושבת אז הרע שבנוגה<sup data-n=\"4106\">79</sup> נדחה לגמרי והרע<sup data-n=\"4107\">80</sup> נכלל ונתעלה בקדושה, וזהו\"ע הרפואה ששת יומין דחול יהיו כמו שבת, וזהו גדולה תשובה שמביא רפואה לעולם דתחילת הבריאה הי' שלא יהי' ממשלת ק\"נ אך בחטא עה\"ד יש ממשלה לק\"נ וצריכים רפואה שיהי' כמו שבת, וזהו ע\"י תשובה הוא בא\"א והוא כמ\"ש וארוכתך מהרה תצמח כו'.\n<b>מיתה</b> ורע<sup data-n=\"4108\">81</sup>, רע הוא תאוות היתר, ומיתה הוא תאוות איסור אשר שרשן מז' מלכין קדמין<sup data-n=\"4109\">82</sup>.",[["4102","75","<b>אלה תולדות. . כיום הבראם</b>: בראשית ב, ד. ראה לעיל (בחלק המאמרים) מאמר ד\"ה ואמנם כו' חולה כאן הערה 81."],["4103","76","<b>חסרו ו' דברים</b>: ראה ב\"ר פי\"ב, ו. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי על יד הערה 62: ה' דברים. לעיל (בחלק המאמרים) מאמר ד\"ה ואמנם כו' חולה כאן הערה 84."],["4104","77","<b>דתשובה הוא בא\"א</b>: ראה לעיל (בחלק המאמרים) מאמר ד\"ה ואמנם כו' חולה כאן הערה 80."],["4105","78","<b>וארוכתך מהרה תצמח</b>: ישעי' נח, ח."],["4106","79","<b>ושבת אז הרע שבנוגה</b>: ראה לעיל (בחלק המאמרים) מאמר ד\"ה ואמנם כו' חולה כאן ובהערה 64."],["4107","80","<b>והרע</b>: אוצ\"ל: והטוב."],["4108","81","<b>מיתה ורע. . מלכין קדמין</b>: נרשם באותיות קטנות לאחרי המאמר."],["4109","82","<b>מז' מלכין קדמין</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו הערה 1623."]]],[2000470447,"<h3>סמוכים לעד</h3>\n<b>ש\"פ צו תר\"ם לפ\"ק</b>\n<b>סמוכים</b> לעד<sup data-n=\"4110\">1</sup> לעולם<sup data-n=\"4111\">2</sup>, הנה פי' בזהר<sup data-n=\"4112\">3</sup> שקאי על בחי' זו\"ן דאצי' שנק' סמוכים, ובפרדס<sup data-n=\"4113\">4</sup> מבאר זה שהם ת\"ת ומל', שמל' נסמך מת\"ת, ות\"ת נסמך במל' וזהו סמוכים לעד שהם סומכים זל\"ז, והנה צ\"ל מהו\"ע הסמיכה, הנה מצינו סמיכה בקרבנות וכמ\"ש וסמך ידו על ראש העולה<sup data-n=\"4114\">5</sup> ואמרז\"ל ש\"מ סמיכה בשתי ידיו<sup data-n=\"4115\">6</sup>",[["4110","1","<b>סמוכים לעד</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ. ההנחה לא נגמרה בכתיבתה."],["4111","2","<b>סמוכים לעד לעולם</b>: תהלים קיא, ח."],["4112","3","<b>פי' בזהר</b>: בראשית לה, א."],["4113","4","<b>ובפרדס</b>: נסמן לעיל (בחלק המאמרים) מאמר ד\"ה סמוכים לעד כאן הערה 4."],["4114","5","<b>וסמך ידו על ראש העולה</b>: ויקרא א, ד."],["4115","6","<b>ש\"מ סמיכה בשתי ידיו</b>: ראה מנחות צג, א (במשנה). שם ב."]]],[2000470448,"ופעמים אי' בכל כחו<sup data-n=\"4116\">7</sup> הרי דסמיכה צ\"ל בשתי ידיו ובכל כחו, וצ\"ל מהו\"ע הסמיכה שהי' צ\"ל בקרבנות, והנה צ\"ל תחילה שרש ענין הקרבנות, דכשאדם חטא מקריב בהמה ע\"ג המזבח וזה מכפר וצ\"ל מה שייכות זל\"ז דאדם חטא ובהמה מכפרת<sup data-n=\"4117\">8</sup>. והענין דהנה כדי שיתמלא החטא ועון צריכים להמשיך אור שלולא הפגם לא הי' צריך להמשיך אור כזה, דצריך להמשיך ממקום שאינו נוגע כלל וכמ\"ש אם חטאת מה תפעל בו<sup data-n=\"4118\">9</sup> ורבה פשעיך מה תעשה לו אם צדקת מה תתן לו<sup data-n=\"4119\">10</sup> ומה מידך יקח<sup data-n=\"4120\">11</sup>, ומשם יומשך סליחת עוונות שיהי' נושא עון ועובר על פשע<sup data-n=\"4121\">12</sup>.\n<b>והנה</b> צ\"ל איך יש בכח הקרבן להמשיך בחי' זו, הנה צ\"ל תחילה שרש האדם, דהנה שרש האדם הוא (בפ\"א<sup data-n=\"4122\">14</sup> : משם מ\"ה דתיקון) מתיקון<sup data-n=\"4123\">13</sup> וכמ\"ש נעשה אדם בצלמינו כדמותינו<sup data-n=\"4124\">15</sup> וכתיב בצלם אלקים עשה את האדם<sup data-n=\"4125\">16</sup>, דכן מצינו למעלה ג\"כ בחי' אדם וכמ\"ש ועל דמות הכסא<sup data-n=\"4126\">17</sup> דמות כמראה אדם עליו מלמעלה, וצ\"ל והלא אין לו דמות הגוף<sup data-n=\"4127\">18</sup> ולא גוף ומה שייך לומר אדם למעלה. אך הנה אדם למעלה הוא זיווגי המדות והתכללותן, דכמו באדם שלמטה יש יד ימין ויד שמאל וגוף המחברם כמו\"כ למעלה יש חו\"ג שהם ב' הפכים דחסד הוא להשפיע לכל אפי' למי שאינו ראוי וכמ\"ש לו ישמעאל יחי' לפניך<sup data-n=\"4128\">19</sup>, וכי לא ידע את ישמעאל, אלא שמצד החסד צריכים להשפיע לכל אפי' למי שאינו ראוי ומצד הגבו' הרי היא גבו' וצמצומים צמצום אחר צמצום, ומדת הרחמים הוא מכריע בין חו\"ג שהגם שהיא מטה כלפי חסד אך נותן מקום למדה\"ד, לו יהי שאינו ראוי מ\"מ צריכים להשפיע לו (בפ\"א<sup data-n=\"4129\">20</sup> : מפני שחסר לו), לא כמדת החסד שאומר שראוי הוא אך מדת הרחמים אומר שאינו ראוי מ\"מ צריכים להשפיע לו, והנהגת המדות הוא ע\"פ שכל וכמ\"ש לפי שכלו יהולל איש<sup data-n=\"4130\">21</sup>, איש הוא מדות, הנהגתן ע\"פ השכל, וכמו\"כ באדם יש חסד להשפיע לכל וגבו' שהו\"ע הצמצום וצ\"ל מדה\"ר להכריע ע\"פ<sup data-n=\"4131\">22</sup> שאינו ראוי מ\"מ ישפיע לו, והנהגתן צ\"ל ע\"פ השכל, וזהו ואהבת את ה' אלקיך בכל לבבך בשני יצריך<sup data-n=\"4132\">23</sup> שהיצה\"ר יהי' לו אהבה",[["4116","7","<b>סמיכה. . בכל כחו</b>: חגיגה טז, ב."],["4117","8","<b>דאדם חטא ובהמה מכפרת</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה סמוכים לעד כאן ובהערה 7."],["4118","9","<b>אם חטאת מה תפעל בו</b>: איוב לה, ו [ושם: ורבו — ראה גם סה\"מ תרל\"ח ע' תיג. וש\"נ]."],["4119","10","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["4120","11","<b>ומה מידך יקח</b>: נסמן לעיל בהנחה ד\"ה ויהי בימי אחשורוש הערה 19."],["4121","12","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["4122","14","<b>בפ\"א</b>: ראה גם לעיל בהנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["4123","13","<b>שרש האדם. . מתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ג."],["4124","15","<b>נעשה אדם בצלמינו כדמותינו</b>: בראשית א, כו."],["4125","16","<b>בצלם אלקים עשה את האדם</b>: נח ט, ו."],["4126","17","<b>ועל דמות הכסא</b>: יחזקאל א, כו."],["4127","18","<b>אין לו דמות הגוף</b>: ע\"פ פיוט יגדל. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה נעשה אדם ובהערה 31."],["4128","19","<b>לו ישמעאל יחי' לפניך</b>: לך יז, יח. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה גור ארי' ספ\"ב ובהנסמן שם."],["4129","20","<b>בפ\"א</b>: ראה גם לעיל הערה 14."],["4130","21","<b>לפי שכלו יהולל איש</b>: משלי יב, ח. ראה גם מאמרי אדה\"א נ\"ך ע' רסו. וש\"נ."],["4131","22","<b>ע\"פ</b>: אוצ\"ל: אע\"פ."],["4132","23","<b>ואהבת. . בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פט\"ז."]]],[2000470449,"לאלקות, וצ\"ל והלא היצה\"ר הוא המסית ומדיח ואיך שייך שיהי' לו אהבה לאלקות<sup data-n=\"4133\">24</sup>. והענין דהנה ניתן כח לאדם שיהי' מוח שליט על הלב<sup data-n=\"4134\">25</sup>, לב הוא חמימות התאווה ורשפי אש בתאוות זרות, ומוח שליט על הלב שמכבה האש זר כמו למטה מים מכבה אש כמו\"כ המוח הוא קר ולח<sup data-n=\"4135\">26</sup> והוא יסוד המים<sup data-n=\"4136\">27</sup>, ה\"ה מכבה את האש והוא ע\"י התבוננות וידעת היום והשבת אל לבבך כי הוי' הוא אלקים<sup data-n=\"4137\">28</sup> כולא חד<sup data-n=\"4138\">29</sup> בלא פרודא, עי\"ז לא ירצה אפי' בתאוות היתר וכ\"ש בתאוות איסר אפי' שמץ דבר אסור ואפי' איסר קל של ד\"ס דחומר ד\"ס<sup data-n=\"4139\">30</sup> יותר מיינה של תורה<sup data-n=\"4140\">31</sup> עד שיהי' לו אהבה לאלקות ובפרטיות ית' אי\"ה. ועי\"ז מעלה הנה\"א ג\"כ<sup data-n=\"4141\">32</sup> בעילוי אחר עילוי.\n<b>אך</b> כ\"ז אם המוח שליט על הלב אזי מעלה גם הנה\"א וזהו תכלית ירידתה בגוף לברר הנה\"ב דהנשמה מצ\"ע אינה צריכה לשום תיקון<sup data-n=\"4142\">33</sup> (דהיא חלק הוי'<sup data-n=\"4143\">34</sup> ממש דהיינו חלק מעצם ואינה דבר נוסף על עצמותו, רק ע\"י שמברר הנה\"ב מתעלה גם הנה\"א) רק כדי לברר הנה\"ב, אך כשנמשך אחר התאוות ותענוגי עוה\"ז לא די שאינו מעלה אותו ה\"ה מוריד אותו עשר מעלות אחורנית<sup data-n=\"4144\">35</sup>, דהנשמה קודם התלבשותה בגוף הרי כתי' חי ה' אשר עמדתי לפניו<sup data-n=\"4145\">36</sup>, שעמדה באהוי\"ר וביטל לאלקות, וירדה למטה בגוף וע\"י החטא ועון נעשה בה פגם, רק נשמה דאצילות נסתלק קודם החטא<sup data-n=\"4146\">37</sup>",[["4133","24","<b>היצה\"ר. . אהבה לאלקות</b>: ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח ספ\"א ואילך."],["4134","25","<b>מוח שליט על הלב</b>: ראה תניא פי\"ב. מאמרי אדה\"א דברים ח\"ב ע' תצ. וש\"נ. ראה גם מאמרי אדה\"ז על ענינים ע' תיט ואילך. עטרת ראש ע' 38 ואילך."],["4135","26","<b>המוח הוא קר ולח</b>: ראה מאמרי אדה\"א בראשית ע' תעא ואילך. הנחות תקע\"ז ע' קמז. תו\"ח שמות ח\"א כז, ג ובהנסמן במקומות הנ\"ל."],["4136","27","<b>המוח. . יסוד המים</b>: ראה תניא פ\"ג. תו\"א בראשית ח, סע\"א. ריש ע\"ב. מקץ ל, ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' א'כב בשם ספרי הרפואה."],["4137","28","<b>וידעת היום. . אלקים</b>: ואתחנן ד, לט [ושם: האלקים]."],["4138","29","<b>הוי' הוא אלקים כולא חד</b>: נסמן לעיל (בחלק המאמרים) מאמר ד\"ה סמוכים לעד כאן הערה 52."],["4139","30","<b>דחומר ד\"ס</b>: ראה ערובין כא, ב. סנהדרין פי\"א, מ\"ג (סנהדרין פח, ב). ירושלמי ברכות פ\"א, ה\"ד. ראה אגה\"ק סכ\"ג. אוה\"ת שלח ס\"ע תצא ואילך. סה\"מ תרל\"ד ע' קלט."],["4140","31","<b>יותר מיינה של תורה</b>: ע\"ז לה, א."],["4141","32","<b>מעלה הנה\"א ג\"כ</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשמה. וש\"נ. סה\"מ תרל\"ד ע' קנ הערה 18."],["4142","33","<b>דהנשמה מצ\"ע. . לשום תיקון</b>: ראה תניא פל\"ז (מח, ב). ש\"א ט, א הערה 4."],["4143","34","<b>דהנשמה. . חלק הוי'</b>: האזינו לב, ט. ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה כמים הפנים סוף פיסקא א. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ד ד\"ה וככל. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' ד\"ה וככל."],["4144","35","<b>עשר מעלות אחורנית</b>: ע\"פ מלכים-ב כ, י. יא. ישעי' לח, ח."],["4145","36","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["4146","37","<b>נשמה דאצילות נסתלק קודם החטא</b>: ראה ת\"ז ת\"ע קכד, סע\"א ובכס\"מ שם. עמה\"מ שער רישא דז\"א פי\"ח (קלה, א). אגה\"ק ס\"כ[ednref_238_א] (קל, א). מאמרי אדה\"ז תקס\"ב ח\"א ע' פו[ednref_239_ב]. תקס\"ד ע' קו[ednref_240_ג]. המשך תער\"ב ח\"א ע' שפח. ח\"ב ע' תתעז. בהערה הבאה. וראה גם המשך והחרים תרל\"א ע' כ.\n\n[edn_238_א] ראה גם סה\"מ תרס\"ט ע' קנז. המשך תער\"ב ח\"ג ע' א' שסט וע' א'תסט. תרע\"ח ע' שטו וע' שעא.\n\n[edn_239_ב] ראה גם מאמרי אדה\"א נ\"ך ע' קצא ואילך.\n\n[edn_240_ג] ראה גם אוה\"ת ויחי ח\"ב ע' שנט. סה\"מ תרל\"ב ח\"א ע' לט וע' ר. תרל\"ג ח\"א ע' נ. ח\"ב ס\"ע תקצו ואילך. תרנ\"ה ע' נד."]]],[2000470450,"וה\"ז ג\"כ פגם אבל (נשמות דבי\"ע) הרי כתי' ונפש כי תחטא<sup data-n=\"4147\">38</sup> שע\"י החטא ועון נעשה בה פגם, אך מ\"מ אל יאמר נואש דזהו\"ע הקרבן וכמ\"ש אדם כי יקריב מכם<sup data-n=\"4148\">39</sup>, ומהו מכם, פי' תמורת שהוריד תחילה הנה\"א צריך להעלות אותו עתה, וראשית ההקרבה הוא מן הבהמה ומן הבקר<sup data-n=\"4149\">40</sup>, בהמה הוא מין הבהמה וגם להורות על הנה\"ב, דהנה שרש הבהמה הוא מעולם התהו שקדם לתיקון<sup data-n=\"4150\">41</sup> ופי' קדם במעלה וכשמקריבין אותה ע\"ג המזבח נכללת באש של מטה ואש של מעלה עד שעולה ונכללת לה' ועי\"ז והחיות נושאות את הכסא<sup data-n=\"4151\">42</sup>, דשרש הבהמה הוא מפני שור<sup data-n=\"4152\">43</sup> שבמרכבה, ועי\"ז והחיות נושאות את הכסא והאדם שעל הכסא לבחי' כי לא אדם הוא<sup data-n=\"4153\">44</sup> הרי נתעלה גם האדם, ומפני דשרש הבהמה הוא מתהו לכן ע\"י הקרבן נמשך אש שלמעלה מתהו ותיקון ומתמלאים הפגמים, וזהו דאי' שנתמלאו כל הפגמים<sup data-n=\"4154\">45</sup> הוא מפני שנמשך אור שלמעלה מתהו ותיקון, וכ\"ז בד\"כ, ובד\"פ (בפ\"א<sup data-n=\"4155\">46</sup> הו\"ע התפלה דתפילה במקום תמידין תקנו<sup data-n=\"4156\">47</sup>. ד) הנה כשאדם נעור משנתו ה\"ה בריה חדשה<sup data-n=\"4157\">48</sup> וה\"ז כמ\"ש<sup data-n=\"4158\">49</sup>",[["4147","38","<b>נשמות דבי\"ע. . ונפש כי תחטא</b>: ויקרא ה, א. ראה פרדס שער הנשמה של\"א, פ\"י. לקוטי הש\"ס להאריז\"ל לתענית יא, א ד\"ה ר' חזקי'[ednref_241_ד] אומר נשמתו של אדם (ח, ב בדפי הספר). לקוטי הגהות לתניא ריש ע' עו. בהערה שלפנ\"ז."],["4148","39","<b>אדם כי יקריב מכם</b>: ויקרא א, ב. ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פט\"ז ובהערה 405."],["4149","40","<b>מן הבהמה ומן הבקר</b>: המשך הכתוב אדם כי יקריב [ושם: מן]."],["4150","41","<b>בהמה. . מעולם התהו שקדם לתיקון</b>: ראה לעיל הערה 13. (לקמן ח\"ב בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ובהערה 51."],["4151","42","<b>והחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["4152","43","<b>דשרש הבהמה הוא מפני שור</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ח. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["4153","44","<b>כי לא אדם הוא</b>: שמואל-א טו, כט. ראה תו\"א יתרו עא, ב ואילך. עב, ג."],["4154","45","<b>דאי' שנתמלאו כל הפגמים</b>: ראה גם סה\"מ תרל\"ו ח\"ב ע' שמא."],["4155","46","<b>בפ\"א</b>: ראה גם לעיל הערה 14."],["4156","47","<b>דתפלה במקום תמידין תקנו</b>: ראה ברכות כו, ב."],["4157","48","<b>כשאדם. . בריה חדשה</b>: ראה ב\"ר רפע\"ח. סה\"מ תרל\"ח ע' רי. וש\"נ."],["4158","49","<b>כמ\"ש</b>: ע\"כ נרשם בגוכתי\"ק והמשך העמוד נשאר חלק. ראה ההמשך לעיל (בחלק המאמרים) מאמר ד\"ה סמוכים לעד כאן.\n\n[edn_241_ד] כ\"ה הגי' שם."]]],[2000470451,"<h3>מצה זו</h3>\n<b></b><b>ליל ב' דחגה\"פ תר\"ם לפ\"ק, לובאוויטש</b>\nליל ב' דחגה\"פ\n<b>מצה</b> זו<sup data-n=\"4159\">1</sup> שאנו אוכלין על שום מה ע\"ש שלא הספיק בצקת של אבותינו להחמיץ עד שנגלה עליהם<sup data-n=\"4160\">2</sup> מלך מלכי המלכים הקב\"ה וגאלם, והנה לכאו' צ\"ל מה שייך מצה זו שאנו אוכלין למצה דמצרים שהי' מפני שלא הספיקו כו', דציווי על אכילת מצה הרי כתי' בערב תאכלו מצות<sup data-n=\"4161\">3</sup> ובמצרים הי' אחר חצות אז נגלה עליהם מלך כו', אבל מצה זו שאנו אוכלין שהיא קודם חצות מה שייך למה שנגלה עליהם מלך מלכי המלכים הקב\"ה. וצ\"ל דכל ענין דמצה יש לו שייכות עם מה שנגלה עליהם ממה\"מ.\n<b>והענין</b> דהנה כתי' גן נעול אחותי כלה<sup data-n=\"4162\">4</sup> גל נעול מעין חתום ואי' במדר'<sup data-n=\"4163\">5</sup> ע\"פ ויאמר ה' אל משה<sup data-n=\"4164\">6</sup> ואל אהרן בארץ מצרים מה הקב\"ה עושה במצרים, בשביל ישראל, אר\"י נפחא משל למטרונה א' שהיתה מקטרגת למלך נתנה בפילקי (פי' בית הסוהר<sup data-n=\"4165\">7</sup> ) והלך לו, והי' עמה א\"ל כ\"כ למה, אמר כל הימים שאני עמה איני<sup data-n=\"4166\">8</sup> נוטלת שם רע, כך ישראל נשתעבדו במצרים וגלה הקב\"ה עמם וכמ\"ש אנכי ארד עמך מצרים<sup data-n=\"4167\">9</sup> ואנכי אעלך גם עלה<sup data-n=\"4168\">10</sup>, בבל למענכם שולחתי<sup data-n=\"4169\">12</sup> בבלה<sup data-n=\"4170\">11</sup> כו', א\"ל כ\"כ למה אמר כל הימים שאני עמה איני נוטלת<sup data-n=\"4171\">13</sup> שם רע, במצרים הייתי עמה<sup data-n=\"4172\">14</sup> ולא נטלה שם רע וכמ\"ש גן נעול מעין חתום<sup data-n=\"4173\">15</sup>, א\"כ השראת השכינה הי' במצרים לאגנה עלייהו שלא יומשכו כ\"כ וכמ\"ש הנה לא ינום<sup data-n=\"4174\">16</sup> ולא ישן שומר ישראל, אך צ\"ל דהנה ארז\"ל הכל בידי שמים<sup data-n=\"4175\">17</sup> חוץ מיראת שמים וא\"כ אינו תלוי בידי שמים כלל ואיך נמשך מלמעלה לאגנה עלייהו, אך באמת הרי כתי' גבי אבימלך ואחשוך גם אנכי<sup data-n=\"4176\">18</sup> אותך מחטוא לי הרי שנשמר מלמעלה, וצ\"ל ע\"ד מ\"ש מי יתן והי' לבבם זה ליראה אותי<sup data-n=\"4177\">19</sup>, ואי' במדר' הו\"ל תן אתה<sup data-n=\"4178\">20</sup>, וצ\"ל ג\"כ כנ\"ל והלא יר\"ש אינו תלוי בידי שמים. וצ\"ל שאינו תלוי בידי שמים כ\"א בבחי' מי שהוא למעלה מהשגה, למעלה מבחי' שמים בכלל, ומשם נמשך בחי' יר\"ש, ואפ\"ל דהנה יצ\"מ הי' הכנה למ\"ת שניתנו ג\"ן",[["4159","1","<b>מצה זו</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים [מג' פרקים — כמצויין שם. וההנחה מפ\"ד — נדפסה לקמן אחר הנחה זו]. וש\"נ."],["4160","2","<b>מצה זו. . עד שנגלה עליהם</b>: נוסח ההגדה."],["4161","3","<b>בערב תאכלו מצות</b>: בא יב, יח."],["4162","4","<b>גן נעול אחותי כלה</b>: שה\"ש ד, יב."],["4163","5","<b>במדר'</b>: ראה שמו\"ר פט\"ו, טז."],["4164","6","<b>ויאמר ה' אל משה</b>: בא יב, א."],["4165","7","<b>בית הסוהר</b>: מתנות כהונה שם."],["4166","8","<b>איני</b>: במדרש: אינה."],["4167","9","<b>אנכי ארד עמך מצרים</b>: ויגש מו, ד [ושם: מצרימה]."],["4168","10","<b>ואנכי אעלך גם עלה</b>: ראה לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 18."],["4169","12","<b>שולחתי</b>: ראה יפ\"ת ופי' מהרז\"ו לשמו\"ר שם."],["4170","11","<b>למענכם שולחתי בבלה</b>: ישעי' מג, יד."],["4171","13","<b>עמה איני נוטלת</b>: במדרש: עמהם אין נוטלין."],["4172","14","<b>עמה</b>: שם: עמהם."],["4173","15","<b>מעין חתום</b>: שם: אחותי כלה."],["4174","16","<b>הנה לא ינום</b>: תהלים קכא, ד."],["4175","17","<b>הכל בידי שמים</b>: ברכות לג, ב."],["4176","18","<b>ואחשוך גם אנכי</b>: וירא כ, ו."],["4177","19","<b>מי יתן. . ליראה אותי</b>: ואתחנן ה, כו. ראה אוה\"ת ואתחנן ע' קצה ואילך."],["4178","20","<b>במדר' הו\"ל תן אתה</b>: ראה ילקוט שמעוני תבוא רמז תתקס. ע\"ז ה, סע\"א."]]],[2000470452,"סדרים דאורייתא<sup data-n=\"4179\">21</sup> וג\"ן אורות דג\"ן סדרים נמשכו לאגנה עלייהו דבלא זה א\"א להיות מ\"ת, וה\"ז ע\"ד שארז\"ל שאפי' מצות מגינא ומצלי ומכ\"ש תורה<sup data-n=\"4180\">22</sup>, וזהו שהג\"ן אורות נמשכו לאגנה עלייהו וזהו גן נעול אחותי כלה.\n<b>ובת\"ז</b> פי' כלה היא שכינה<sup data-n=\"4181\">23</sup> וי\"ל זה על ב' דרכים הא' שקאי על תושבע\"פ, דתושבע\"פ נק' כלה ותושב\"כ נק' חתן<sup data-n=\"4182\">24</sup> דהנה תושבע\"פ הוא פי' וביאור תושב\"כ דכל המצות כמו מצות מצה בתושבע\"פ<sup data-n=\"4183\">25</sup> הוא בקיצור נמרץ ובתושבע\"פ נתפרש ונתבאר באורך ורוחב מס' פסחים והרבה הלכות לכן נק' תושבע\"פ כלה ותושב\"כ נק' חתן, ועוי\"ל שקאי על בחי' כנס\"י שהיא מקור ושרש נש\"י, דכמו שתושבע\"פ נק' כלה מפני שמקבל מתושב\"כ כן ס\"ר נש\"י<sup data-n=\"4184\">26</sup> מקבלים מס\"ר אותיות התורה<sup data-n=\"4185\">27</sup>, באמת לא יש רק ל\"ו רבוא<sup data-n=\"4186\">28</sup> אך יש אותיות אהו\"י שיוצאים והם נק' אותיות הנקוד<sup data-n=\"4187\">29</sup> ובס\"ה הם ס\"ר, וס\"ר נשמות כללות כל נשמה יש לה אות בתורה<sup data-n=\"4188\">30</sup>, וביאור הענין דהנה האותיות מקבלים מחו\"ב, וזהו מ\"ש ונהר יוצא מעדן<sup data-n=\"4189\">31</sup> להשקות את הגן, ונהר הוא בחי' בינה<sup data-n=\"4190\">32</sup> כי רחובות הנהר<sup data-n=\"4191\">33</sup> הוא משל להשגת הבינה כמו הנהר שמתפשט לאורך ורוחב כמו\"כ השגות הבינה הוא באורך ורוחב ויוצא מעדן בחי' ח\"ע<sup data-n=\"4192\">34</sup>, והנהר אינו בשביל עצמו כ\"א להשקות את הגן הם ג\"ן סדרים דאורייתא<sup data-n=\"4193\">35</sup>, ומאחר שאומרים שאין הנהר בשביל עצמו כ\"א בשביל האותיות צ\"ל שיש מציאות האותיות קודם לזה והנהר משקה אותם, שאם לא יש אותיות אינו שייך להשקות.\n<b>והענין</b> דהנה באותיות יש ב' מדרי' אור השכלה של האותיות ועצם האותיות שאינו שייך לההשכלה, כמו תי' ברוך האור השכל שבו הוא בל\"א",[["4179","21","<b>ג\"ן סדרים דאורייתא</b>: ראה זהר מדהנ\"ע וירא קד, ב. מאמרי אדה\"א דברים ח\"ד ע' א'רג. וש\"נ."],["4180","22","<b>מצות מגינא. . ומכ\"ש תורה</b>: ראה סוטה כא, א. ש\"א יב, א ובהערה 6."],["4181","23","<b>כלה היא שכינה</b>: ראה זהר שמות ה, ב."],["4182","24","<b>דתושבע\"פ נק' כלה ותושב\"כ נק' חתן</b>: ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פכ\"א הערה 570."],["4183","25","<b>בתושבע\"פ</b>: אוצ\"ל: בתושב\"כ."],["4184","26","<b>ס\"ר נש\"י</b>: ראה דרשת תורת ה' תמימה[ednref_242_א] להרמב\"ן: וקבלת רז\"ל כי לא נבראו בשנוי פרצופים אלא בששים ריבוא. תניא פל\"ז. מאמרי אדה\"ז תקס\"ו ס\"ע קצ ואילך. תק\"ע ע' קד. סה\"מ תרמ\"ד ע' רסה."],["4185","27","<b>מס\"ר אותיות התורה</b>: ראה ז\"ח שה\"ש עד, ד. מג\"ע אופן קפו. לקו\"ש טו\"ב כסלו תשמ\"א כרך כ ע' 419 בהערה. שו\"ת הצ\"צ חאבהע\"ז סרמ\"ט (צה, א)."],["4186","28","<b>אותיות התורה. . ל\"ו רבוא</b>: ראה שולי הגליון בלקו\"ש שם."],["4187","29","<b>אהו\"י. . הנקוד</b>: ראה לקו\"ת בהר מא, ב. שו\"ת הצ\"צ שם."],["4188","30","<b>נשמות כללות כל נשמה. . אות בתורה</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רנב. וש\"נ. שה\"א צז, סע\"א ובהערה 13."],["4189","31","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["4190","32","<b>ונהר. . בינה</b>: ראה תו\"א משפטים עה, ד: כמ\"ש בזהר פ' אמור [צט, א]."],["4191","33","<b>בינה. . רחובות הנהר</b>: וישלח לו, ז. ראה זהר אד\"ר נשא קמב, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרט ואילך (נו\"ש)."],["4192","34","<b>מעדן בחי' ח\"ע</b>: ראה גם תו\"ח בשלח ח\"א קמא, א ובהערה 98."],["4193","35","<b>והנהר. . להשקות. . ג\"ן סדרים דאורייתא</b>: ראה גם תו\"ח שמות ח\"א ז, ד. וש\"נ.\n\n[edn_242_א] כתבי הרמב\"ן ח\"א ירושלים תשכ\"ד ע' קסב."]]],[2000470453,"גיבענצט או גילובט<sup data-n=\"4194\">36</sup> לפי הענין אך עצם האותיות ב' ר' ו' ך' אינו שייך לההשכלה כלל, דהנה האותיות<sup data-n=\"4195\">37</sup> אינו ע\"ד המושכל ולא בטבע המבטא לפעול האותיות, דה' מוצאות הפה<sup data-n=\"4196\">38</sup> שהם אחה\"ע<sup data-n=\"4197\">39</sup> מן הגרון גיכ\"ק מן החיך דטלנ\"ת מן הלשון זסשר\"ץ<sup data-n=\"4198\">40</sup> מן השיניים בומ\"ף מן השפתים, וכשצריך לומר אות ב' צריך לעקם השפתים, וכי הוא מעקם השפתים וממילא אומר אות ב' אלא הוא אומר אות ב' וממילא מתעקמים השפתים ואינו יודע כלל שהשפתים מתעקמים, ולא שמבטא פועלים האותיות שהי' צ\"ל איזה שהיות זמן, ואפי' הקול ואפילו הבל הלב ג\"כ אינו פועל בהאותיות כלום דהקול שוה בכל האותיות ויש קול בלא אותיות, ואלא הקול הוא אור האותיות ולא שפועל בהאותיות, דשרש אותיות הם בקדמות השכל<sup data-n=\"4199\">41</sup> וכשעולה ברצונו לומר אות ב' ממילא מתעקמים השפתים, ומ\"ש שעולה ברצונו הוא מפני שהרצון הוא גילוי הראשון מן קדמות השכל, ולא שתלוי בהמבטא דאם הי' תלוי בהמבטא הי' צ\"ל איזה שהיות זמן וכמו המנגן בכינור כשדוחק באצבע על חוט זה יוצא הקול כך וכשדוחק על חוט אחר יוצא קול אחר וכשמקרב האצבע יוצא קול זה וכשמרחיקו יוצא קול אחר, ה\"ז תלוי בדחיקות האצבעות על איזה חוטי הכינור וה\"ז צריך שהיות זמן ויש בזה חשבון, אבל בהאותיות אנו רואין שתיכף שעולה ברצונו תיכף הוא מדבר וא\"י יודע<sup data-n=\"4200\">*42</sup> כלל שהשפתים מתעקמים.\n<b>ויותר</b> יובן ענין זה מהנקו'<sup data-n=\"4201\">**42</sup>, דנקודת קמץ צריך לקמוץ השפתים ובנקודת פתח צריך לפתוח השפתים, והרי אנו רואין וכי כשצריך לומר קמץ הוא מכוון לקמץ השפתים ויאמר קמץ אלא שהוא אומר קמץ וממילא נקמצים השפתים, ובאמת אינו צריכים להאריך בזה הרבה ומובן שאין זה ע\"ד המושכל שהוא למעלה מהשגה וגם לא בטבע המבטא, ולכן תינוק אע\"פ שיש לו חכ' מ\"מ אינו יכול לדבר והוא מפני שהדיבור אינו תלוי בחכ' רק בעצם הנפש בחי' קדמות השכל ולכן כשמתחיל שלימות הנפש אז יכול לדבר, ופי' קדמות השכל<sup data-n=\"4202\">42</sup> הוא למעלה משכל, דבאמת הוא תי' מורכבת שכל הוא גילוי, וקדמות הוא למעלה מן השכל, קדמות השכל פי' קדם לשכל שלמעלה משכל, אך מפני שהוא חכם ולא בחכמה ידיעא<sup data-n=\"4203\">43</sup> ולגבי בחי' לא בחכמה ידיעא ה\"ז חכם לכן נק' שכל, אך מ\"מ משם נמשך איזה הארה שמזה נעשה שכל וזה בא לידי השגה והבנה וכל ההשגה וההבנה הכל הוא מההארה זו, וזהו ונהר",[["4194","36","<b>ברוך. . גיבענצט או גילובט</b>: ראה גם לקמן הנחה ד\"ה אז ישיר משה על יד הערה 55. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ובהערה 54."],["4195","37","<b>דהנה האותיות</b>: ראה אגה\"ק ס\"ה (קז, א)."],["4196","38","<b>דה' מוצאות הפה</b>: ראה ס\"י (מהדורת מנטובא שכ\"ב) פ\"ב, מ\"א. ובדפו\"א שם, מ\"ג (ובמפרשים שם). ת\"ז ת\"ע קלב, סע\"א."],["4197","39","<b>אחה\"ע</b>: ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' קה."],["4198","40","<b>זסשר\"ץ</b>: ראה בהערה שלפנ\"ז."],["4199","41","<b>דשרש אותיות הם בקדמות השכל</b>: ראה אגה\"ק שם (קז, ב). בפיסקא הבאה. לעיל הנחה ד\"ה כי הנה יוצר הרים הערה 23."],["4200","*42","<b>וא\"י יודע</b>: כ\"ה בגוכתי\"ק."],["4201","**42","<b>ויותר יובן. . מהנקו'</b>: ראה אגה\"ק שם (קז, א ואילך)."],["4202","42","<b>ופי' קדמות השכל</b>: ראה גם לקמן הנחה ד\"ה אז ישיר משה על יד הערה 28. הנחה ד\"ה גל נעול על יד הערה 25."],["4203","43","<b>חכם ולא בחכמה ידיעא</b>: ראה ז\"ח יתרו לד, ד. ת\"ז בהקדמה יז, ב."]]],[2000470454,"יוצא מעדן להשקות את הגן, נהר הוא השגה והבנה יוצא מעדן הוא בחי' קדמות השכל שכל הנעלם והוא בחי' חכם ולא בחכ' ידיעא, והנהר אינו בשביל עצמו וואס מאכט אוס השגה<sup data-n=\"4204\">44</sup> והבנה בלא אותיות אלא עיקרו להשקות את הגן הם האותיות, נמצא יש ב' מדרי' באותיות עצם האותיות ועז\"נ אבא יסד ברתא<sup data-n=\"4205\">45</sup>, דאור אבא הוא למעל' מהשתל' יסד ברתא הוא בחי' מל' עולם הדיבור<sup data-n=\"4206\">46</sup>, ואור השכלה של האותיות שהוא הארה מח\"ע, ולפ\"ז צ\"ל מ\"ש עדן הוא בחי' בעדן מקדם<sup data-n=\"4207\">47</sup> שהוא בחי' קדמות השכל שכל הנעלם חכים ולא בחכ' ידיעא, ועל ל' החסידות הוא תענוג העליון.\n<b>וזהו</b> ביו\"ד נברא העוה\"ב<sup data-n=\"4208\">48</sup> באור השכלה דיו\"ד וגם בעצם אות יו\"ד וא\"כ צ\"ל ביו\"ד בכל היו\"ד בהאור השכלה וגם בעצם היו\"ד וא\"כ צ\"ל יש ב' מדרי' בג\"ע, ואפ\"ל כמו שאנו רואין למטה דכשמשכיל איזה השכלה ה\"ה מתענג א\"ע והתענוג אינו ההשכלה כלל שהם ב' ענינים רק שהתענוג נתלבש בההשכלה<sup data-n=\"4209\">49</sup> כמו שהאותיות הם כלים לההשכלה כמו השכל הוא כלי להתענוג כמו\"כ יובן בג\"ע שכל ההשכלה דג\"ע כמו אבות העולם<sup data-n=\"4210\">50</sup> שהם בג\"ע כמה אלפים שנה ומשיגים השגות הכל מאור השכלה דיו\"ד והתענוג העליון שיש בג\"ע הוא מצד עצם האות יו\"ד, אך הנה מ\"מ הוא רק הארה מצומצמת דמה תופס מקום אות יו\"ד לגבי כל האותיות שהם ך\"ב קל<sup data-n=\"4211\">51</sup> [וכ\"ש] לגבי כללות הדיבור, ומה גם האות היו\"ד שהוא נקודה חדא<sup data-n=\"4212\">52</sup> דיש אות שיש לו אורך ורוחב אבל היו\"ד הוא רק נקודא חדא וא\"כ ה\"ז רק צמצום עצום הן באור השכלה דג\"ע שהוא מצד אור השכלה דיו\"ד ה\"ז צמצום עצום והן מצד הענג העליון שהוא מצד עצם אות היו\"ד ה\"ז ג\"כ מצומצם מאד, וזהו ויניחהו בג\"ע לעבדה ולשמרה<sup data-n=\"4213\">53</sup> להמשיך תוס' אורות בג\"ע, וכן כל העבודה דעכשיו הוא להמשיך תוס' אורות בג\"ע, ועל ל' הקבלה הוא להמתיק דיני לאה<sup data-n=\"4214\">54</sup>, לאה הוא אותיות המח'<sup data-n=\"4215\">55</sup> ואותיות הם מגבילים את השכל, דבלי האותיות אפשר להתפשט השכל הרבה והאותיות מגבילים אותו, שהשכל הוא כמה שיש בהאותיות, וע\"י לימוד התורה לשמה לשם התורה<sup data-n=\"4216\">56</sup> להמשיך אוא\"ס בתורה ממתיקים דיני לאה, דהנה בתורה יש ב' מדרי'",[["4204","44","<b>אוס השגה</b>: כ\"ה בגוכתי\"ק."],["4205","45","<b>אבא יסד ברתא</b>: נסמן לעיל (בחלק המאמרים) בהמשך זאת חנוכת המזבח פט\"ז הערה 396."],["4206","46","<b>מל' עולם הדיבור</b>: ראה זהר לך פו, ב. ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["4207","47","<b>בעדן מקדם</b>: בראשית ב, ח."],["4208","48","<b>ביו\"ד נברא העוה\"ב</b>: ראה מנחות כט, ב."],["4209","49","<b>שהתענוג נתלבש בההשכלה</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה כמגדל דוד צוארך על יד הערה *8. המשך מצה זו פכ\"ב ובהערות 685 682. וראה גם שעה\"י קיג, א ובהערה 3."],["4210","50","<b>אבות העולם</b>: ירושלמי סנהדרין פ\"י, ה\"א."],["4211","51","<b>קל</b>: כ\"ה בגוכתי\"ק."],["4212","52","<b>היו\"ד שהוא נקודה חדא</b>: זהר בראשית ל, ב."],["4213","53","<b>ויניחהו בג\"ע לעבדה ולשמרה</b>: בראשית ב, טו."],["4214","54","<b>להמתיק דיני לאה</b>: ראה פע\"ח שער הנהגת הלימוד בתחילתו."],["4215","55","<b>לאה הוא אותיות המח'</b>: ראה סידור שחרית ס, ג. סט, א. מאמרי אדה\"א נ\"ך ע' קג. וש\"נ."],["4216","56","<b>לשמה לשם התורה</b>: ראה פע\"ח שער הנהגת הלימוד. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. שה\"א סט, ב ובהערה 26. סה\"מ תרכ\"ז ס\"ע רסח ואילך. וש\"נ."]]],[2000470455,"דיבור דתורה והוא עיקר מצות לימוד התורה בדיבור<sup data-n=\"4217\">58</sup> וכמ\"ש ודברת בם<sup data-n=\"4218\">59</sup>, ועיון<sup data-n=\"4219\">57</sup> בתורה, והעיון הוא שמעמיק דעתו בהדבר ההוא וכל שמעמיק דעתו יותר, יותר הוא מבין איך שאינו יודע כלל, שזה א\"י וזה א\"י, וה\"ז בחי' אין וכמ\"ש והחכ' מאין תמצא<sup data-n=\"4220\">60</sup>, ומשם יומשך הגילוי אור, ומוח העיון ומוח הזכרון שניהם בחכמה<sup data-n=\"4221\">61</sup>, לכן משם נמשך להמתיק דיני לאה, דביו\"ד לבד נברא העוה\"ב וע\"י לימוד התורה ממשיך ריבוי אותיות [הגם (במשכיל) לא יש מציאות האותיות, אך כשעולה ברצונו להשפיע השכל להזולת הרי יש מציאות האותיות ג\"כ וא\"כ כמו שהשכל הוא מהרצון כמו\"כ האותיות] ובחי' זו נמשך מחכ' דבחכ' שורה אוא\"ס<sup data-n=\"4222\">62</sup>, ועוי\"ל דחכמה אפי' כלי החכמה אינם מסתירים על אוא\"ס השורה בו, ועל ל' הקבלה הוא חכ' דא\"ק שמלובש בחכ' דאצילות אין כלי החכ' מסתירים עליו, וזהו ע\"י לימוד התורה לשמה נמשך להמתיק כו', פי' שנמשך מבחי' יסו\"א להמתיק כו', ומ\"ש יסו\"א שהוא פתיחות החכמה דהנה ידוע דאותיות שבעולם העליון הם נעשים מוחין בעולם שלמטה<sup data-n=\"4223\">63</sup> ממנו וכמו א' כשנופל לו איזה ברק המבריק<sup data-n=\"4224\">64</sup>, תחילה אינו יודע אותו כלל ואח\"כ הוא בא לידי השגה לגבי עצמו ואח\"כ נעשה מזה מוחין בכל העולם, וכמו\"כ הוא בחי' יסו\"א שהוא פתיחות החכ'. ועפ\"ז יובן מה שכנס\"י נק' כלה<sup data-n=\"4225\">65</sup> שהוא ל' כלתה נפשי<sup data-n=\"4226\">66</sup> דס\"ר נש\"י שרשם בס\"ר אותיות התורה, והאותיות שרשם מבחי' קדמות השכל שלמעלה מהשגה לכן יש לו בטבעו כליון ותשוקה לאלקות למס\"נ באחד<sup data-n=\"4227\">67</sup> דכל דבר נמשך אחר השרש<sup data-n=\"4228\">68</sup>, ועי\"ז נמשך מ\"ש ונהר יוצא מעדן, דמשנת\"ל דהנהר הוא בינה, היינו רחובות הנהר, אבל עצם הנהר כמו שיוצא מהמעיין שנובע טיף טיף הוא בחי' חכמה, ובחי' זו נמשך להשקות את הגן הם האותיות, ולכן נק' הנהר שלום וכמ\"ש הנני נוטה",[["4217","58","<b>עיקר מצות לימוד התורה בדיבור</b>: ראה הל' ת\"ת שם. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פכ\"ג הערה 667."],["4218","59","<b>ודברת בם</b>: ואתחנן ו, ז. לקמן הנחה ד\"ה גל נעול על יד הערה 28."],["4219","57","<b>בתורה יש ב' מדרי' דיבור. . ועיון</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. מאמרי אדה\"א בראשית ע' תקכז. וש\"נ. קונטרסים ע' תקמב. וש\"נ. תו\"ח בשלח ח\"א קסט, ב. וש\"נ."],["4220","60","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["4221","61","<b>ומוח העיון ומוח הזכרון שניהם בחכמה</b>: נסמן לעיל (בחלק המאמרים) המשך מצה זו כאן הערות 81-82."],["4222","62","<b>דבחכ' שורה אוא\"ס</b>: ראה תניא פי\"ח. פל\"ה בהג\"ה[ednref_243_ב]. לקו\"ת במדבר יד, ב[ednref_244_ג]. תו\"ח שמות ח\"א ז, ד הערה 333. סה\"מ תרנ\"ח ע' יב."],["4223","63","<b>דאותיות שבעולם העליון. . מוחין בעולם שלמטה</b>: ראה לקו\"ת שלח לט, סע\"ב."],["4224","64","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לעיל הנחה ד\"ה כי הנה יוצר הרים ובהערה 21."],["4225","65","<b>שכנס\"י נק' כלה</b>: ראה פסדר\"כ פכ\"ב (שוש אשיש). וש\"נ. תו\"ח וארא ח\"א עב, ג ובהערה 7."],["4226","66","<b>כלה. . כלתה נפשי</b>: תהלים פד, ג. ראה גם תו\"ח בשלח ח\"א רח, א ובהערה 19."],["4227","67","<b>למס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["4228","68","<b>דכל דבר נמשך אחר השרש</b>: ראה גם מאמרי אדה\"א נ\"ך ע' תצא. וש\"נ. תו\"ח בא ח\"א צה, ב הערה 408. לקמן הנחה ד\"ה אז ישיר משה על יד הערה 12.\n\n[edn_243_ב] ובמ\"מ הגהות והע\"ק שם.\n\n[edn_244_ג] <b>ושם מציין</b>: ”בע\"ח שער מ\"ז פ\"ג\" ולפנינו הוא פ\"ב ”ושער ב במה\"ב פ\"א פ\"ג\" ולפנינו הוא בשער סדר אצי' ש\"ג."]]],[2000470456,"אלי' כנהר שלום<sup data-n=\"4229\">69</sup>, וכן גבי תורה כתי' צאינה וראינה בנות ציון<sup data-n=\"4230\">70</sup> במלך שלמה בעטרה שעטרה לו אמו ביום חתונתו זו מ\"ת<sup data-n=\"4231\">71</sup>, ואמרז\"ל מלך שלמה מלך שהשלום שלו<sup data-n=\"4232\">72</sup>, דהתורה נק' שלום וכמ\"ש כל נתיבותי' שלום<sup data-n=\"4233\">73</sup>, וכדי שיומשך בחי' זו בתושבע\"פ עז\"נ והאיתנים מוסדי ארץ<sup data-n=\"4234\">74</sup> שהם ממשיכים מתושב\"כ לתושבע\"פ, דכל בנין דתושבע\"פ הוא ע\"י תנאים (ע' בד\"ה ויתן אל משה ככלותו<sup data-n=\"4235\">75</sup>, תוך פ\"ה ובסוף הדרוש).\n<b>וזהו</b> מצה זו שאנו אוכלין על שום מה, שכל ענין מצה הוא לפעול ביטול בנש\"י, דההפרש בין מצה לחמץ הוא דחמץ הוא הגבהה והתנשאות, ומצה הוא ביטול ושפלות<sup data-n=\"4236\">76</sup>, וכ\"ז הוא מפני שמרוחק דמי שהוא קרוב אינו שייך שיהי' התנשאות, ולכן צ\"ל תחלה השבתת שאר<sup data-n=\"4237\">77</sup>, אך ובמצרים אחר חצות הי' מפני שנגלה עליהם מלך מלכי המלכים הקב\"ה, מלכים הוא כמ\"ש הנה המלכים נועדו<sup data-n=\"4238\">78</sup> הם יהודה ויוסף זו\"ן, מלכי המלכים חו\"ב, מלך מלכי המלכים הוא בחי' כתר (ע' בלקו\"ת ד\"ה מצה זו<sup data-n=\"4239\">79</sup> ) ומשם נמשך שלא יהי' מקום לחמץ כלל, וכמו עד\"מ א' שעומד לפני המלך אינו שייך שיהי' לו איזה הגבהה והתנשאות, כמו\"כ מאחר שנמשך מבחי' כתר אינו שייך שיהי' חמץ כלל, ובתורה הוא לימוד התורה לשמה לשם התורה שממשיכים מבחי' קדמות השכל, ובמצות הו\"ע מצות מצה, דמצה על ל' הקבלה הוא קטנות אבא<sup data-n=\"4240\">80</sup> ונת' במ\"א (בד\"ה וככה ל\"ז<sup data-n=\"4241\">81</sup> ) באריכות שבקטנות אבא יש כל מה שבגדלות אבא אלא שהוא בקטנות (וכמו עד\"מ קטן יש בו כל מה שבגדול כל הכחות וכל החושים אלא שהוא בקטנות) וא\"כ יש בו גם מה שלמע' מהשכל שהוא בחי' קדמות השכל. וזהו מצה זו שאנו אוכלין על שום מה על שום שלא הספיק בצקת של אבותינו להחמיץ עד שנגלה עליהם מלך מלכי המלכים הקב\"ה וזה הי' במצרים אחר חצות וכמו\"כ מצה שלנו שהוא קודם חצות יש לו שייכות וקישור למה שנגלה עליהם כו' מפני שכל ענין מצה הוא בחי' זו (ע' בלקו\"ת בד\"ה הנ\"ל<sup data-n=\"4242\">82</sup> ובסידור בד\"ה והגדת לבנך<sup data-n=\"4243\">83</sup> כו') וזהו מצה זו שאנו אוכלין קודם חצות מפני שנגלה עליהם מלך מלכי המלכים שהוא בחי' כתר.",[["4229","69","<b>הנני נוטה אלי' כנהר שלום</b>: ישעי' סו, יב."],["4230","70","<b>צאינה וראינה בנות ציון</b>: שה\"ש ג, יא."],["4231","71","<b>ביום חתונתו זו מתן תורה</b>: תענית כו, ב (במשנה). ראה מאמרי אדמור מהר\"ש דרושי חתונה ע' לד. מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["4232","72","<b>מלך שלמה מלך שהשלום שלו</b>: ראה שה\"ש שם. שהש\"ר פ\"א, א [יא]. פ\"ג, יא [א]. שבועות לה, ב."],["4233","73","<b>כל נתיבותי' שלום</b>: משלי ג, יז [ושם: וכל]."],["4234","74","<b>והאיתנים מוסדי ארץ</b>: מיכה ו, ב."],["4235","75","<b>בד\"ה ויתן אל משה ככלותו</b>: ראה גם ד\"ה זה באוה\"ת תשא ע' א'תתקעט (פ\"ו). ע' א'תתקפא (ס\"ח)."],["4236","76","<b>דחמץ. . והתנשאות ומצה. . שפלות</b>: ראה לקו\"ת צו יג, ג. שה\"ש יד, ד."],["4237","77","<b>תחלה השבתת שאר</b>: בא יב, טו."],["4238","78","<b>הנה המלכים נועדו</b>: תהלים מח, ה. זהר ויגש רו, א."],["4239","79","<b>ע' בלקו\"ת ד\"ה מצה זו</b>: צו יב, ב. ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 106."],["4240","80","<b>דמצה. . קטנות אבא</b>: ראה סידור סדר הגדה חצר, סע\"א ואילך. תו\"ח בא ח\"א צד, ד הערה 393."],["4241","81","<b>בד\"ה וככה ל\"ז</b>: פנ\"ה ואילך."],["4242","82","<b>בלקו\"ת בד\"ה הנ\"ל</b>: יב, ב ואילך."],["4243","83","<b>ובסידור בד\"ה והגדת לבנך</b>: סדר הגדה חצר, ג ואילך."]]],[2000470457,"<h3>משה קבל תורה מסיני</h3>\n<b></b><b>יום ב' של חגה\"פ תר\"ם לפ\"ק</b>\nיום ב' של חגה\"פ\n<b>משה</b> קבל תורה מסיני<sup data-n=\"4244\">1</sup> ומסרה ליהושע ויהושע לזקנים וזקנים לנביאים ונביאים מסרוה לאנשי כנה\"ג<sup data-n=\"4245\">2</sup>, ממ\"ש ל' קיבל משמע שהוא למעלה מהשגה רק בדרך קבלה ובחי' זו גופא מסרוה כו', ובאמת כל התורה יש בה השגה ומה שייך ע\"ז לומר ומסרה.\n<b>והענין</b> דמשנת\"ל<sup data-n=\"4246\">3</sup> שהתורה שרשה מחכ' דאורייתא מחכ' נפקת<sup data-n=\"4247\">4</sup>, הוא רק נובלות חכ' דאי' במד' ג' נובלות הן<sup data-n=\"4248\">5</sup>, נובלות חכ' שלמעלה תורה, פי' נובלות מה שנובל ונושר מהאילן, דשרש התורה הוא מבחי' אחוריים וחיצוניות מבחי' חכ', דהנה בחי' חכ' לית מח' תפיסא בי' כלל<sup data-n=\"4249\">6</sup>, דבחכ' מאיר אוא\"ס בקירוב מקום<sup data-n=\"4250\">7</sup>, ומקום אין פי' מקום בגשמיות<sup data-n=\"4251\">8</sup>, שמה שקרוב בשטח נק' קרוב במקום ומה שרחוק בשטח נק' רחוק במקום, דמה שייך מקום גשמי למעלה, אלא כמו מעלה ומטה בו\"ק דמקום שא\"א להגיע לשם נק' מעלה, ומקום שיכולים להגיע נק' מטה, כמו\"כ למעלה מקום",[["4244","1","<b>משה[ednref_245_א] קבל תורה מסיני</b>: הנחת[ednref_246_ב] כ\"ק אדמו\"ר מהורש\"ב מפ\"ד[ednref_247_ג] מהמשך מצה זו שנדפס לעיל בחלק המאמרים (ושם הפתיחא: וביאור הענין).\nלתוכן המאמר ראה גם המשך וככה תרל\"ז פכ\"ט-פל\"ד."],["4245","2","<b>משה קבל. . לאנשי כנה\"ג</b>: אבות רפ\"א."],["4246","3","<b>דמשנת\"ל</b>: ראה בהנחה שלפנ\"ז. (ולעיל בחלק המאמרים) המשך מצה זו פ\"ב ואילך."],["4247","4","<b>דאורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["4248","5","<b>במד' ג' נובלות הן</b>: ב\"ר פי\"ז, ס\"ה. פמ\"ד, יז. ראה תו\"א לך יא, ג. תו\"ח לך פב, ג. אוה\"ת לך כרך ו ע' תתרעד ואילך."],["4249","6","<b>לית מח' תפיסא בי' כלל</b>: ע\"פ לשון הת\"ז בהקדמה יז, א. וראה גם לקמן פיסקא וביאור ענין ההפרש."],["4250","7","<b>דבחכ'. . בקירוב מקום</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג-ד. שער סדר אבי\"ע שמ\"ז, פ\"א. תו\"ח בראשית יז, ג הערה 5. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה להבין שרש ענין מקיפים דבינה[ednref_248_ד] ובהנסמן שם."],["4251","8","<b>ומקום אין פי' מקום בגשמיות</b>: ראה גם לקמן ח\"ב שם ובהערה 23. סה\"מ תרכ\"ז ע' שמח ובהנסמן שם. המשך וככה תרל\"ז כאן פ\"ל.\n\n[edn_245_א] נדפס גם בקונ' בפ\"ע בצירוף מ\"מ — עשק\"מ החודש אייר, ה'תשנ\"ח.\n\n[edn_246_ב] <b>ברשימת יומן כ\"ק אדמו\"ר מש\"ק ר\"ח אייר תרצ\"ה (נדפס ברשימות חוב' קמג ע' 5) מספר כ\"ק אדמו\"ר מהוריי\"צ נ\"ע</b>: תרנ\"ה ש\"ק שאחר חהמ\"צ ביום אחר הסעודה קראני אדנ\"ע. . נתן לי הנחה שלו על דא\"ח מהרשנ\"ע ”משה קבל תורה מסיני\" (והוא משנת תר\"ם בהמשך מצה זו. קטן. בן שני פרקים. כמאמרי זקני מועט מחזיק את המרובה. כק\"ש) וא\"ל: „ז דו ועסט ‘לערנען און פ„רשטיין תכנס אלי. פ„רשטיין איז ד ך „ ברייטער ו רט גם זמני הי' קבוע להלימוד עם רשב\"ץ ולכן ביום ג' או ד' עדיין לא גמרתיו. קראני ושאלני: נו.. . וא\"ל שעדיין א\"י. וחזר לפני המאמר ג\"פ. ביום ה' א\"ל: איך בין דיר מחזיק טובה. דער ט„טע ה ט מיר געהייסען חזר'ן דעם מאמר 36 פעמים. „ז דער ט„טע ה ט געהייסען חזר'ן איז ד ס געווען בדיבור ניט נ ר במחשבה (החזקת טובה כי עי\"ז נזכר כמה מאורעות מעת ההיא. כק\"ש).\n\n[edn_247_ג] <b>באג\"ק כ\"ק אדמו\"ר מהוריי\"צ ח\"ב ע' שכד מספר</b>: ”וידוע שבמאמרי מהר\"ש יש חילוק גדול בין הכתבים לכמו שאמרם, שהכתבים מקוצרים הרבה, והנחות כ\"ק אאמו\"ר זצוקללה\"ה הם ע\"פ הרוב כמו שהיו בעת הדבור\".\n\n[edn_248_ד] נדפס גם בסה\"מ תרכ\"ט ס\"ע שסט ואילך."]]],[2000470458,"שמאיר אוא\"ס בריבוי ובגילוי וכמו שהוא נק' קירוב מקום, ומקום שמאיר אוא\"ס ע\"י צמצום שאינו מאיר רק הארה בעלמא הגם שבההארה יש בה הכל זה נק' ריחוק מקום, וכמו עד\"מ כשאחד עומד בקרוב לאיזה דבר ומסתכל בה ה\"ה רואה אותה דבר בכל הפרטים כמו שהוא, אבל כשעומד בריחוק מקום אף שרואה את הדבר מ\"מ אינו רואה אותה בכל החלקים כמו בקרוב, ומי גורם לזה הוא הריחוק מקום, וכמו\"כ הוא למעלה ג\"כ ענין קירוב מקום כו', אבל לא שנא' בו ח\"ו מקום גשמי, דהנה מקום אתי<sup data-n=\"4252\">9</sup> כתי' הוא מקומו של עולם<sup data-n=\"4253\">10</sup> ואין העולם מקומו, דשרש המקום הוא ברשימו אשר שם נצטיירו כל הד' עולמות אבי\"ע בהשוואה א' ושם אינו שייך לומר רחוק וקרוב, אך למטה בגשמיות אין לנו ציור אחר רק מעלה ומטה כו'.\n<b>וביאור</b> ענין קירוב מקום וריחוק מקום יובן מענין מח' ודיבור, דמח' הוא גילוי העלם העצמי לגבי עצמו ודיבור הוא גילוי לגבי זולתו, הנה אנו רואים עד שהשכל בא לדיבור ה\"ה נתצמצם במיעוט אחר מיעוט, דכדי שיומשך ממח' לדיבור צ\"ל תחילה מדה שבלב, ואח\"כ צריך להתקטין ולהתצמצם המדה, דכשהמדה בתוקף ההתפעלות אינו יכול לדבר כלל<sup data-n=\"4254\">*11</sup> רק שמוכרח להתצמצם, ואח\"כ כשמשפיע בדיבור ה\"ז רק ההארה<sup data-n=\"4255\">11</sup>, דא\"א לגלות השכל כמו שהוא גבי עצמו רק בחי' תחתונה, וכמו\"כ במח' שהוא גילוי העלם העצמי לגבי עצמו א\"א לגלות כמו שהוא בהעלם העצמי, דמאחר שהוא גילוי השכל, וכל שהוא גילוי אינו עצם, ובהעלם העצמי נשאר יותר ממה שמגלה המח', וממח' למדות ג\"כ אינו בערך, דמח' לבוש הראשון לשכל ה\"ז מוחין, ומוחין למדות אינו בערך, הגם שנת\"ל שהמח' ג\"כ אינו מגלה כמו שהוא בהעלם העצמי, אך בגילויים א\"א להתגלות יותר, ומה שאפשר להיות בגילוי הרי המח' הוא גילוי הראשון, וכמו\"כ יובן למעלה דמח' הוא קירוב מקום ודיבור הוא ריחוק מקום, אך מח' ה\"ז אותיות (המעלימים).\n<b>ויובן</b> זה בעומק יותר עד\"מ הראי' שרואה מהות הדבר כמו שהוא, וזהו ההפרש בין ראי' לשמיעה דארז\"ל אינו דומה שמיעה לראי'<sup data-n=\"4256\">12</sup>, ואם נאמר שאינו בערך וסוג זה כלל אינו שייך לומר אינו דומה, אלא צ\"ל שהם בערך זל\"ז, אך מ\"מ אינו דומה כו', וההפרש בין ראי' לשמיעה הוא, דראי' ה\"ה רואה מהות הדבר כמו שהוא אבל שמיעה אינו רואה מהות הדבר כלל רק שמצייר בשכלו הדבר ההוא, ואף",[["4252","9","<b>דהנה מקום אתי</b>: תשא לג, כא. ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 66. ראה גם בענין מקום לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה סוכה שחמה מרובה מצלתה על יד הערה 68 ואילך."],["4253","10","<b>הוא מקומו של עולם</b>: ב\"ר פס\"ח, ט. ראה מאמרי אדה\"א דברים ח\"א ע' רצא. וש\"נ. תו\"ח בראשית מג, א הערה 2. סה\"מ תרכ\"ט ע' קסט. וש\"נ."],["4254","*11","<b>דכשהמדה בתוקף. . לדבר כלל</b>: ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה גדולה מילה ובהערה 16."],["4255","11","<b>שהשכל בא לדיבור. . רק ההארה</b>: ראה גם מאמר ד\"ה ויאמר מה תצעק אלי תרנ\"א — תרנ\"ד ע' 9 בשולי היריעה. ראה גם לעיל (בחלק המאמרים) המשך מצה זו ספ\"ה ובהערה 198."],["4256","12","<b>אינו דומה שמיעה לראי'</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה גור ארי' ובהערה 17."]]],[2000470459,"שהמספר ראה מהות הדבר אבל השומע לא ראה, ולבד זאת הרי מספר לו בדיבור, וא\"א לגלות בדיבור כמו שהוא גבי עצמו, ודיבור זה נעשה גבי השומע מקור לשמיעה, וכידוע דחיצוניות שבעליון נעשה פנימיות בתחתון<sup data-n=\"4257\">13</sup>, לכן כשזה השומע רואה את הדבר ההוא ה\"ה מתפעל מזה והוא מפני שהוא קנין אחר בנפשו, וזהו ההפרש בין ראי' לשמיעה, דשמיעה לבד מה שהוא רק בדיבור, הרי אין כאן המהות כלל ובראי' ה\"ה רואה מהות, וראי' ושמיעה הם חו\"ב<sup data-n=\"4258\">14</sup>, ראי' הוא משל לחכ' אשר שם מאיר אוא\"ס בקירוב מקום, ובינה הוא כמו שמיעה שהוא בריחוק מקום, ומפני שבחכ' מאיר אוא\"ס בקירוב מקום לכן אין בו השגה והבנה וכמו אותיות החקוקים על אבן טוב מצד עוצם בהירות האבן מפני הניצוצות שנתזין ממנו אינו יכול לקרוא האותיות הגם שהאותיות משחירים על המקום אשר הם חקוקים שמה, מ\"מ הם מבהיקים, ופי' משחירים ר\"ל שהם משנים העצם, דזה ידוע דכל עצם הוא בלתי מתגלה<sup data-n=\"4259\">15</sup> והאותיות הם גילוי, ממילא מובן שאין זה עצם, ובזה מכוון יותר המשל דראי' שרואה מהות הדבר, הגם שבראי' ג\"כ אינו רואה עצם הדבר דידוע דסיבות<sup data-n=\"4260\">16</sup> ראי' העין הוא מפני שכל צדדיו בהירים וצד האחור חשוך והדבר הנראה נצטייר בהעין<sup data-n=\"4261\">17</sup> ולכן הוא רואה וה\"ז כמו מראה (בל\"א שפיגל) שאינו רואה העצם, ובזה יש יתרון מעלה במישוש שתופס מהות הדבר, וראי' הוא מראה, אך מ\"מ אינו דומה למראה, שמה שרואה בהמראה הדמות ה\"ה נצטייר בהעין נמצא שהוא ציור מדמות, אבל ראי' ה\"ז דמות מעצם, אך זה אינו לכאן<sup data-n=\"4262\">18</sup> ואכ\"מ. וכמו\"כ יובן למעלה שבחכ' מאיר עצם האוא\"ס, רק אנו אין לנו משל בדקות יותר מראי' שאינו עצם שהוא גילוי וכל עצם בלתי כו' ובגילוי א\"א להיות יותר, אבל למעלה בחכ' מאיר עצם האוא\"ס.\n<b>וביאור</b> ענין ההפרש בין חו\"ב יובן מההפרש שבין אצי' לבריאה, דהנה אי' בת\"ז דאבא עילאה מקננא באצי'<sup data-n=\"4263\">19</sup> ואימא עילאה [בינה<sup data-n=\"4264\">20</sup> ] מקננא בכורסייא<sup data-n=\"4265\">21</sup>",[["4257","13","<b>דחיצוני' שבעליון נעשה פנימי' בתחתון</b>: ראה ע\"ח שער א\"א שי\"ד, פ\"ט. אגה\"ק (קו\"א) להבין מ\"ש בפע\"ח (תניא קנז, א). לקו\"ת שלח מא, ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ח ח\"א ע' תלז ואילך."],["4258","14","<b>וראי' ושמיעה הם חו\"ב</b>: ראה תו\"א וירא טו, ד. מקץ מ, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' רפז. תקס\"ט ע' פט. שער האמונה מג, ב. תו\"ח שמות ח\"א כז, ג הערות 15-16."],["4259","15","<b>דכל עצם הוא בלתי מתגלה</b>: ראה גם סה\"מ תרנ\"ב ע' צו. הגהות לד\"ה פתח אלי' תרנ\"ח ע' נא. סה\"מ תרנ\"ח ס\"ע קסד. תער\"ב ח\"ב ע' תרנד. ע' תשיז. ר\"ע תשכח."],["4260","16","<b>דסיבות</b>: אוצ\"ל: דסיבת."],["4261","17","<b>ראי' העין. . נצטייר בהעין</b>: ראה גם רמ\"ז לזהר פקודי רכה, ב (רמט, סע\"ב ואילך). הגהות הרמ\"ז על אוצר\"ח שער הנקודים פ\"א הערה נא. שבילי אמונה לר' מאיר אבן אלדבי הנתיב הרביעי ד\"ה העינים. מאמרי אדה\"א הנחות תקע\"ז ע' קמז. אוה\"ת שה\"ש ח\"א ע' שיד. המשך וככה תרל\"ז פנ\"ז. פע\"ג. סה\"מ תרל\"ח ע' רעח. ע' תנד. תרס\"ח ע' לב. תער\"ב ח\"א ע' תקמג. ח\"ב ע' תשטז. סה\"ש תורת שלום ע' 76. פלח הרמון שה\"ש ע' מא. לקו\"ב לשעה\"י פ\"ג קסח, ג."],["4262","18","<b>אינו לכאן</b>: אוצ\"ל: אינו שייך לכאן."],["4263","19","<b>דאבא עילאה מקננא באצי'</b>: ראה ת\"ז ת\"ו כג, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' רלה."],["4264","20","<b>ואימא עילאה [בינה</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"ח."],["4265","21","<b>ואימא. . מקננא בכורסייא</b>: ת\"ז שם. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."]]],[2000470460,"[עולם הבריאה] והנה הריחוק הערך בין אצי' לבריאה<sup data-n=\"4266\">22</sup> הוא כמו בין בורא לנברא, דהנה בריאה הם נבראים נפרדים אשר המהווה מוכרח להסתתר מהדבר המתהווה, הגם שהבריאה הוא בכח הא\"ס וכמארז\"ל אפי' מתכנשין כל באי עולם<sup data-n=\"4267\">23</sup> אינם יכולים לברוא אפי' כנף יתוש אחת, וא\"כ איך הם נפרדים, אך המהווה מוכרח להסתתר מהדבר המתהווה לכן הם נפרדים, אך אצי' הוא ל' אצלו וסמוך<sup data-n=\"4268\">24</sup> והוא הפרשות<sup data-n=\"4269\">25</sup> הארה מאוא\"ס וכמו שהוא אוא\"ס כמו\"כ הארתו אוא\"ס, ולכן באצי' הוא אינון ואינון הוא<sup data-n=\"4270\">26</sup>, איהו וחיוהי חד ואיהו וגרמוהי חד בהון<sup data-n=\"4271\">27</sup>, שהרי בהם וע\"י בורא יש מאין אשר זה בכח הא\"ס, א\"כ אין ערוך כלל ביניהם, וכל ההפרש הזה הוא מפני שבאצי' אבא עילאה כו' ובבריאה אימא עילאה כו', ולפ\"ז יובן ההפרש בין חו\"ב ג\"כ, ולכן בחכ' לית מח' תפיסא בי' כלל אנת הוא חכים<sup data-n=\"4272\">28</sup> ולא בחכ' ידיעא, דחכ' הוא כח מה<sup data-n=\"4273\">29</sup> אחד האמת שבו שורה אוא\"ס ואי' בתניא<sup data-n=\"4274\">30</sup> וזו היא מדרי' החכ', והנה מ\"ש אורייתא מחכ' נפקת הוא מנובלות חכ' כמו פרחים שנושרים מהאילן, כמו\"כ תורה הוא אחוריים וחיצוניות דח\"ע.\n<b>וזהו</b> משה קיבל תורה מסיני, משה הי' רבן של כל הנביאים<sup data-n=\"4275\">31</sup>, ובמקום שנבואה מגיע השיג מדרי' היותר עליונה דהשיג אחוריים וחיצוניות דח\"ע<sup data-n=\"4276\">32</sup>, אך לא פנימיות דח\"ע, והוא אור אבא שמלובש בבינה והארתו שפועל ומתפשט בנהי\"מ, ובחי' זו השיג משה אבל לא הפנימיות דח\"ע ועז\"כ ופני לא יראו<sup data-n=\"4277\">33</sup>, הגם שכל נבואה",[["4266","22","<b>הריחוק הערך בין אצי' לבריאה</b>: ראה גם לקמן הנחה ד\"ה גן נעול הא' על יד הערה 10. ש\"א כח, ב ובהנסמן במ\"מ לשם."],["4267","23","<b>אפי' מתכנשין כל באי עולם</b>: ראה ירושלמי סנהדרין ספ\"ז. ספרי ואתחנן ו, ה. ב\"ר פל\"ט, יד. וש\"נ. לקו\"ש משפטים כרך כו ע' 366."],["4268","24","<b>אצי' הוא ל' אצלו וסמוך</b>: ראה פרדס שער אבי\"ע שט\"ז, רפ\"א. לעיל (בחלק המאמרים) המשך מצה זו פנ\"ה על יד הערה 1604. לקמן ח\"ב (בחלק המאמרים) ד\"ה להבין שרש ענין מקיפים דבינה ספ\"ב. לקו\"ת ואתחנן ח, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שיא ובהנסמן במ\"מ לשם. ח\"ב ע' תקעב. תקס\"ז ע' תכט[ednref_249_ה]. אוה\"ת בשלח ר\"ע תפט[ednref_250_ו]. סה\"מ תרכ\"ז ע' שמט."],["4269","25","<b>הפרשות</b>: אוצ\"ל: הפרשת."],["4270","26","<b>הוא אינון ואינון הוא</b>: ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ו הערה 102."],["4271","27","<b>איהו וחיוהי. . וגרמוהי חד בהון</b>: ראה לעיל שם ובהערה 99."],["4272","28","<b>אנת הוא חכים</b>: ת\"ז בהקדמה יז, ב. ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 23. סה\"מ תרל\"ח ע' קצב ובהערה 1537."],["4273","29","<b>דחכ' הוא כח מה</b>: זהר רע\"מ צו כח, א. לד, א. ראה גם לעיל הנחה ד\"ה כי הנה יוצר הרים ובהערה 39. לקמן הנחה ד\"ה וירא העם וינועו על יד הערה 66."],["4274","30","<b>ואי' בתניא</b>: פל\"ה בהגה\"ה."],["4275","31","<b>משה הי' רבן של כל הנביאים</b>: שמו\"ר פכ\"א, ד."],["4276","32","<b>דהשיג אחוריים וחיצוניות דח\"ע</b>: ראה אגה\"ק סי\"ט. הועתק לעיל (בחלק המאמרים) המשך המשך מצה זו כאן פ\"ד."],["4277","33","<b>ועז\"כ </b>[ ועל זה כתיב]<b> ופני לא יראו</b>: תשא לג, כג.\n\n[edn_249_ה] נדפס גם באוה\"ת על ענינים ע' קסז ואילך.\n\n[edn_250_ו] <b>שם ע' תפח כותב</b>: ”ה' אלפים תקפ\"ג מב\"ע\". ומזה משמע שדרוש זה נכתב בזמן הנ\"ל."]]],[2000470461,"הוא מנו\"ה דאצי'<sup data-n=\"4278\">34</sup>, אך הוא ע\"י התלבשות בבריאה כו' ובמשה הי' בדרך מעבר הבריאה<sup data-n=\"4279\">35</sup>, ולכן קיבל תורה מסיני מפני שהגיע למדרי' זו.",[["4278","34","<b>שכל נבואה הוא מנו\"ה דאצי'</b>: ראה שער היחודים פ\"א. שער רוה\"ק פ\"א. שער מאמרי רשב\"י לת\"ז ת\"כ. תו\"א מקץ מג, ב. סידור שער הק\"ש עט, א. שער החנוכה עדר, ב. סהמ\"צ להצ\"צ ע' 344. סה\"מ תרכ\"ז ס\"ע ריא."],["4279","35","<b>ובמשה הי' בדרך מעבר הבריאה</b>: ראה לקו\"ש שמות כרך ו ע' 252 ואילך."]]]]});
